\\u0153: [\\u0153Message\\u0153]}", "target": "Agent-R27kt", "targetHandle": "{\\u0153fieldName\\u0153: \\u0153input_value\\u0153, \\u0153id\\u0153: \\u0153Agent-R27kt\\u0153, \\u0153inputTypes\\u0153: [\\u0153Message\\u0153], \\u0153type\\u0153: \\u0153str\\u0153}"}, {"data": {"sourceHandle": {"dataType": "Agent", "id": "Agent-R27kt", "name": "response", "output_types": ["Message"]}, "targetHandle": {"fieldName": "input_value", "id": "ChatOutput-lbrgJ", "inputTypes": ["Data", "DataFrame", "Message"], "type": "str"}}, "id": "xy-edge__Agent-R27kt{\\u0153dataType\\u0153:\\u0153Agent\\u0153,\\u0153id\\u0153:\\u0153Agent-R27kt\\u0153,\\u0153name\\u0153:\\u0153response\\u0153,\\u0153output_types\\u0153:[\\u0153Message\\u0153]}-ChatOutput-lbrgJ{\\u0153fieldName\\u0153:\\u0153input_value\\u0153,\\u0153id\\u0153:\\u0153ChatOutput-lbrgJ\\u0153,\\u0153inputTypes\\u0153:[\\u0153Data\\u0153,\\u0153DataFrame\\u0153,\\u0153Message\\u0153],\\u0153type\\u0153:\\u0153str\\u0153}", "source": "Agent-R27kt", "sourceHandle": "{\\u0153dataType\\u0153: \\u0153Agent\\u0153, \\u0153id\\u0153: \\u0153Agent-R27kt\\u0153, \\u0153name\\u0153: \\u0153response\\u0153, \\u0153output_types\\u0153: [\\u0153Message\\u0153]}", "target": "ChatOutput-lbrgJ", "targetHandle": "{\\u0153fieldName\\u0153: \\u0153input_value\\u0153, \\u0153id\\u0153: \\u0153ChatOutput-lbrgJ\\u0153, \\u0153inputTypes\\u0153: [\\u0153Data\\u0153, \\u0153DataFrame\\u0153, \\u0153Message\\u0153], \\u0153type\\u0153: \\u0153str\\u0153}"}], "nodes": [{"data": {"id": "ChatInput-JJmqy", "node": {"base_classes": ["Message"], "beta": false, "category": "inputs", "conditional_paths": [], "custom_fields": {}, "description": "Get chat inputs from the Playground.", "display_name": "Chat Input", "documentation": "", "edited": false, "field_order": ["input_value", "should_store_message", "sender", "sender_name", "session_id", "files", "background_color", "chat_icon", "text_color"], "frozen": false, "icon": "MessagesSquare", "key": "ChatInput", "legacy": false, "lf_version": "1.2.0", "metadata": {}, "minimized": true, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Chat Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 0.0020353564437605998, "template": {"_type": "Component", "background_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Background Color", "dynamic": false, "info": "The background color of the icon.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "background_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "chat_icon": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.base.data.utils import IMG_FILE_TYPES, TEXT_FILE_TYPES\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.inputs.inputs import BoolInput\\nfrom langflow.io import (\\n    DropdownInput,\\n    FileInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n)\\nfrom langflow.schema.message import Message\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_USER,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatInput(ChatComponent):\\n    display_name = \\"Chat Input\\"\\n    description = \\"Get chat inputs from the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-input\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatInput\\"\\n    minimized = True\\n\\n    inputs = [\\n        MultilineInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input Text\\",\\n            value=\\"\\",\\n            info=\\"Message to be passed as input.\\",\\n            input_types=[],\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_USER,\\n            info=\\"Type of sender.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_USER,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        FileInput(\\n            name=\\"files\\",\\n            display_name=\\"Files\\",\\n            file_types=TEXT_FILE_TYPES + IMG_FILE_TYPES,\\n            info=\\"Files to be sent with the message.\\",\\n            advanced=True,\\n            is_list=True,\\n            temp_file=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(display_name=\\"Chat Message\\", name=\\"message\\", method=\\"message_response\\"),\\n    ]\\n\\n    async def message_response(self) -> Message:\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        icon = self.chat_icon\\n\\n        message = await Message.create(\\n            text=self.input_value,\\n            sender=self.sender,\\n            sender_name=self.sender_name,\\n            session_id=self.session_id,\\n            files=self.files,\\n            properties={\\n                \\"background_color\\": background_color,\\n                \\"text_color\\": text_color,\\n                \\"icon\\": icon,\\n            },\\n        )\\n        if self.session_id and isinstance(message, Message) and self.should_store_message:\\n            stored_message = await self.send_message(\\n                message,\\n            )\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n"}, "files": {"_input_type": "FileInput", "advanced": true, "display_name": "Files", "dynamic": false, "fileTypes": ["txt", "md", "mdx", "csv", "json", "yaml", "yml", "xml", "html", "htm", "pdf", "docx", "py", "sh", "sql", "js", "ts", "tsx", "jpg", "jpeg", "png", "bmp", "image"], "file_path": "", "info": "Files to be sent with the message.", "list": true, "list_add_label": "Add More", "name": "files", "placeholder": "", "required": false, "show": true, "temp_file": true, "title_case": false, "trace_as_metadata": true, "type": "file", "value": ""}, "input_value": {"_input_type": "MultilineInput", "advanced": false, "display_name": "Input Text", "dynamic": false, "info": "Message to be passed as input.", "input_types": [], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "User"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "User"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "list_add_label": "Add More", "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "selected_output": "message", "showNode": false, "type": "ChatInput"}, "dragging": false, "id": "ChatInput-JJmqy", "measured": {"height": 48, "width": 192}, "position": {"x": 253.05570107641427, "y": 309.91174183872147}, "selected": false, "type": "genericNode"}, {"data": {"id": "ChatOutput-lbrgJ", "node": {"base_classes": ["Message"], "beta": false, "category": "outputs", "conditional_paths": [], "custom_fields": {}, "description": "Display a chat message in the Playground.", "display_name": "Chat Output", "documentation": "", "edited": false, "field_order": ["input_value", "should_store_message", "sender", "sender_name", "session_id", "data_template", "background_color", "chat_icon", "text_color"], "frozen": false, "icon": "MessagesSquare", "key": "ChatOutput", "legacy": false, "lf_version": "1.2.0", "metadata": {}, "minimized": true, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Output Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 0.003169567463043492, "template": {"_type": "Component", "background_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Background Color", "dynamic": false, "info": "The background color of the icon.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "background_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "chat_icon": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "clean_data": {"_input_type": "BoolInput", "advanced": true, "display_name": "Basic Clean Data", "dynamic": false, "info": "Whether to clean the data", "list": false, "list_add_label": "Add More", "name": "clean_data", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from collections.abc import Generator\\nfrom typing import Any\\n\\nimport orjson\\nfrom fastapi.encoders import jsonable_encoder\\n\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.inputs.inputs import BoolInput, DropdownInput, HandleInput, MessageTextInput\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.schema.properties import Source\\nfrom langflow.template.field.base import Output\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_AI,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatOutput(ChatComponent):\\n    display_name = \\"Chat Output\\"\\n    description = \\"Display a chat message in the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-output\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatOutput\\"\\n    minimized = True\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Inputs\\",\\n            info=\\"Message to be passed as output.\\",\\n            input_types=[\\"Data\\", \\"DataFrame\\", \\"Message\\"],\\n            required=True,\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_AI,\\n            advanced=True,\\n            info=\\"Type of sender.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_AI,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"data_template\\",\\n            display_name=\\"Data Template\\",\\n            value=\\"{text}\\",\\n            advanced=True,\\n            info=\\"Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"clean_data\\",\\n            display_name=\\"Basic Clean Data\\",\\n            value=True,\\n            info=\\"Whether to clean the data\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\"Output Message\\",\\n            name=\\"message\\",\\n            method=\\"message_response\\",\\n        ),\\n    ]\\n\\n    def _build_source(self, id_: str | None, display_name: str | None, source: str | None) -> Source:\\n        source_dict = {}\\n        if id_:\\n            source_dict[\\"id\\"] = id_\\n        if display_name:\\n            source_dict[\\"display_name\\"] = display_name\\n        if source:\\n            # Handle case where source is a ChatOpenAI object\\n            if hasattr(source, \\"model_name\\"):\\n                source_dict[\\"source\\"] = source.model_name\\n            elif hasattr(source, \\"model\\"):\\n                source_dict[\\"source\\"] = str(source.model)\\n            else:\\n                source_dict[\\"source\\"] = str(source)\\n        return Source(**source_dict)\\n\\n    async def message_response(self) -> Message:\\n        # First convert the input to string if needed\\n        text = self.convert_to_string()\\n\\n        # Get source properties\\n        source, icon, display_name, source_id = self.get_properties_from_source_component()\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        if self.chat_icon:\\n            icon = self.chat_icon\\n\\n        # Create or use existing Message object\\n        if isinstance(self.input_value, Message):\\n            message = self.input_value\\n            # Update message properties\\n            message.text = text\\n        else:\\n            message = Message(text=text)\\n\\n        # Set message properties\\n        message.sender = self.sender\\n        message.sender_name = self.sender_name\\n        message.session_id = self.session_id\\n        message.flow_id = self.graph.flow_id if hasattr(self, \\"graph\\") else None\\n        message.properties.source = self._build_source(source_id, display_name, source)\\n        message.properties.icon = icon\\n        message.properties.background_color = background_color\\n        message.properties.text_color = text_color\\n\\n        # Store message if needed\\n        if self.session_id and self.should_store_message:\\n            stored_message = await self.send_message(message)\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n\\n    def _serialize_data(self, data: Data) -> str:\\n        \\"\\"\\"Serialize Data object to JSON string.\\"\\"\\"\\n        # Convert data.data to JSON-serializable format\\n        serializable_data = jsonable_encoder(data.data)\\n        # Serialize with orjson, enabling pretty printing with indentation\\n        json_bytes = orjson.dumps(serializable_data, option=orjson.OPT_INDENT_2)\\n        # Convert bytes to string and wrap in Markdown code blocks\\n        return \\"```json\\\\n\\" + json_bytes.decode(\\"utf-8\\") + \\"\\\\n```\\"\\n\\n    def _validate_input(self) -> None:\\n        \\"\\"\\"Validate the input data and raise ValueError if invalid.\\"\\"\\"\\n        if self.input_value is None:\\n            msg = \\"Input data cannot be None\\"\\n            raise ValueError(msg)\\n        if isinstance(self.input_value, list) and not all(\\n            isinstance(item, Message | Data | DataFrame | str) for item in self.input_value\\n        ):\\n            invalid_types = [\\n                type(item).__name__\\n                for item in self.input_value\\n                if not isinstance(item, Message | Data | DataFrame | str)\\n            ]\\n            msg = f\\"Expected Data or DataFrame or Message or str, got {invalid_types}\\"\\n            raise TypeError(msg)\\n        if not isinstance(\\n            self.input_value,\\n            Message | Data | DataFrame | str | list | Generator | type(None),\\n        ):\\n            type_name = type(self.input_value).__name__\\n            msg = f\\"Expected Data or DataFrame or Message or str, Generator or None, got {type_name}\\"\\n            raise TypeError(msg)\\n\\n    def convert_to_string(self) -> str | Generator[Any, None, None]:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        self._validate_input()\\n        if isinstance(self.input_value, list):\\n            return \\"\\\\n\\".join([safe_convert(item, clean_data=self.clean_data) for item in self.input_value])\\n        if isinstance(self.input_value, Generator):\\n            return self.input_value\\n        return safe_convert(self.input_value)\\n"}, "data_template": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Data Template", "dynamic": false, "info": "Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "data_template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "{text}"}, "input_value": {"_input_type": "MessageInput", "advanced": false, "display_name": "Inputs", "dynamic": false, "info": "Message to be passed as output.", "input_types": ["Data", "DataFrame", "Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "input_value", "placeholder": "", "required": true, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Machine"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "Pok\\u00e9dex"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "list_add_label": "Add More", "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "showNode": false, "type": "ChatOutput"}, "id": "ChatOutput-lbrgJ", "measured": {"height": 48, "width": 192}, "position": {"x": 1020, "y": 180}, "selected": false, "type": "genericNode"}, {"data": {"id": "note-avilJ", "node": {"description": "## Open the playground and ask anything about a Pok\\u00e9mon! \\u26a1 \\ud83d\\udc39", "display_name": "", "documentation": "", "template": {"backgroundColor": "transparent"}}, "type": "note"}, "dragging": false, "height": 324, "id": "note-avilJ", "measured": {"height": 324, "width": 391}, "position": {"x": 972.3620941029305, "y": -566.962566336068}, "resizing": false, "selected": false, "type": "noteNode", "width": 391}, {"data": {"id": "note-g8DQ7", "node": {"description": "# Pok\\u00e9dex Agent\\n\\nCollect research on Pok\\u00e9mon with a specialized **Agent** and the Pok\\u00e9dex API.\\n\\n## Prerequisites\\n\\n* An [OpenAI API key](https://platform.openai.com/)\\n\\n## Quickstart\\n\\n1. Paste your OpenAI API key in the **Agent** component.\\n2.  Click **Playground** and ask about your favorite Pok\\u00e9mon.\\nThe **Agent** queries the Pokedex API and returns a formatted entry.", "display_name": "", "documentation": "", "template": {}}, "type": "note"}, "dragging": false, "height": 543, "id": "note-g8DQ7", "measured": {"height": 543, "width": 348}, "position": {"x": -364.79357624384227, "y": -251.04685859774636}, "resizing": false, "selected": false, "type": "noteNode", "width": 348}, {"data": {"id": "note-Y6FRA", "node": {"description": "### \\ud83d\\udca1 Add your OpenAI API key here", "display_name": "", "documentation": "", "template": {"backgroundColor": "transparent"}}, "type": "note"}, "dragging": false, "height": 324, "id": "note-Y6FRA", "measured": {"height": 324, "width": 335}, "position": {"x": 572.2283687381639, "y": -341.52394719582}, "resizing": false, "selected": false, "type": "noteNode", "width": 335}, {"data": {"id": "APIRequest-omX8o", "node": {"base_classes": ["Data", "DataFrame"], "beta": false, "category": "data", "conditional_paths": [], "custom_fields": {}, "description": "Make HTTP requests using URL or cURL commands.", "display_name": "API Request", "documentation": "", "edited": false, "field_order": ["urls", "curl", "method", "use_curl", "query_params", "body", "headers", "timeout", "follow_redirects", "save_to_file", "include_httpx_metadata"], "frozen": false, "icon": "Globe", "key": "APIRequest", "legacy": false, "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Toolset", "group_outputs": false, "hidden": null, "method": "to_toolkit", "name": "component_as_tool", "options": null, "required_inputs": null, "selected": "Tool", "tool_mode": true, "types": ["Tool"], "value": "__UNDEFINED__"}], "pinned": false, "score": 0.007568328950209746, "template": {"_type": "Component", "body": {"_input_type": "TableInput", "advanced": true, "display_name": "Body", "dynamic": false, "info": "The body to send with the request as a dictionary (for POST, PATCH, PUT).", "input_types": ["Data"], "is_list": true, "list_add_label": "Add More", "name": "body", "placeholder": "", "required": false, "show": true, "table_icon": "Table", "table_schema": {"columns": [{"default": "None", "description": "Parameter name", "disable_edit": false, "display_name": "Key", "edit_mode": "popover", "filterable": true, "formatter": "text", "hidden": false, "name": "key", "sortable": true, "type": "str"}, {"default": "None", "description": "Parameter value", "disable_edit": false, "display_name": "Value", "edit_mode": "popover", "filterable": true, "hidden": false, "name": "value", "sortable": true}]}, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "trigger_icon": "Table", "trigger_text": "Open table", "type": "table", "value": []}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import json\\nimport re\\nimport tempfile\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom typing import Any\\nfrom urllib.parse import parse_qsl, urlencode, urlparse, urlunparse\\n\\nimport aiofiles\\nimport aiofiles.os as aiofiles_os\\nimport httpx\\nimport validators\\n\\nfrom langflow.base.curl.parse import parse_context\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.inputs.inputs import TabInput\\nfrom langflow.io import (\\n    BoolInput,\\n    DataInput,\\n    DropdownInput,\\n    IntInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n    TableInput,\\n)\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dotdict import dotdict\\nfrom langflow.services.deps import get_settings_service\\nfrom langflow.utils.component_utils import set_current_fields, set_field_advanced, set_field_display\\n\\n# Define fields for each mode\\nMODE_FIELDS = {\\n    \\"URL\\": [\\n        \\"url_input\\",\\n        \\"method\\",\\n    ],\\n    \\"cURL\\": [\\"curl_input\\"],\\n}\\n\\n# Fields that should always be visible\\nDEFAULT_FIELDS = [\\"mode\\"]\\n\\n\\nclass APIRequestComponent(Component):\\n    display_name = \\"API Request\\"\\n    description = \\"Make HTTP requests using URL or cURL commands.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-data#api-request\\"\\n    icon = \\"Globe\\"\\n    name = \\"APIRequest\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\"url_input\\",\\n            display_name=\\"URL\\",\\n            info=\\"Enter the URL for the request.\\",\\n            advanced=False,\\n            tool_mode=True,\\n        ),\\n        MultilineInput(\\n            name=\\"curl_input\\",\\n            display_name=\\"cURL\\",\\n            info=(\\n                \\"Paste a curl command to populate the fields. \\"\\n                \\"This will fill in the dictionary fields for headers and body.\\"\\n            ),\\n            real_time_refresh=True,\\n            tool_mode=True,\\n            advanced=True,\\n            show=False,\\n        ),\\n        DropdownInput(\\n            name=\\"method\\",\\n            display_name=\\"Method\\",\\n            options=[\\"GET\\", \\"POST\\", \\"PATCH\\", \\"PUT\\", \\"DELETE\\"],\\n            value=\\"GET\\",\\n            info=\\"The HTTP method to use.\\",\\n            real_time_refresh=True,\\n        ),\\n        TabInput(\\n            name=\\"mode\\",\\n            display_name=\\"Mode\\",\\n            options=[\\"URL\\", \\"cURL\\"],\\n            value=\\"URL\\",\\n            info=\\"Enable cURL mode to populate fields from a cURL command.\\",\\n            real_time_refresh=True,\\n        ),\\n        DataInput(\\n            name=\\"query_params\\",\\n            display_name=\\"Query Parameters\\",\\n            info=\\"The query parameters to append to the URL.\\",\\n            advanced=True,\\n        ),\\n        TableInput(\\n            name=\\"body\\",\\n            display_name=\\"Body\\",\\n            info=\\"The body to send with the request as a dictionary (for POST, PATCH, PUT).\\",\\n            table_schema=[\\n                {\\n                    \\"name\\": \\"key\\",\\n                    \\"display_name\\": \\"Key\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Parameter name\\",\\n                },\\n                {\\n                    \\"name\\": \\"value\\",\\n                    \\"display_name\\": \\"Value\\",\\n                    \\"description\\": \\"Parameter value\\",\\n                },\\n            ],\\n            value=[],\\n            input_types=[\\"Data\\"],\\n            advanced=True,\\n            real_time_refresh=True,\\n        ),\\n        TableInput(\\n            name=\\"headers\\",\\n            display_name=\\"Headers\\",\\n            info=\\"The headers to send with the request\\",\\n            table_schema=[\\n                {\\n                    \\"name\\": \\"key\\",\\n                    \\"display_name\\": \\"Header\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Header name\\",\\n                },\\n                {\\n                    \\"name\\": \\"value\\",\\n                    \\"display_name\\": \\"Value\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Header value\\",\\n                },\\n            ],\\n            value=[{\\"key\\": \\"User-Agent\\", \\"value\\": get_settings_service().settings.user_agent}],\\n            advanced=True,\\n            input_types=[\\"Data\\"],\\n            real_time_refresh=True,\\n        ),\\n        IntInput(\\n            name=\\"timeout\\",\\n            display_name=\\"Timeout\\",\\n            value=30,\\n            info=\\"The timeout to use for the request.\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"follow_redirects\\",\\n            display_name=\\"Follow Redirects\\",\\n            value=True,\\n            info=\\"Whether to follow http redirects.\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"save_to_file\\",\\n            display_name=\\"Save to File\\",\\n            value=False,\\n            info=\\"Save the API response to a temporary file\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"include_httpx_metadata\\",\\n            display_name=\\"Include HTTPx Metadata\\",\\n            value=False,\\n            info=(\\n                \\"Include properties such as headers, status_code, response_headers, \\"\\n                \\"and redirection_history in the output.\\"\\n            ),\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"API Response\\", name=\\"data\\", method=\\"make_api_request\\"),\\n    ]\\n\\n    def _parse_json_value(self, value: Any) -> Any:\\n        \\"\\"\\"Parse a value that might be a JSON string.\\"\\"\\"\\n        if not isinstance(value, str):\\n            return value\\n\\n        try:\\n            parsed = json.loads(value)\\n        except json.JSONDecodeError:\\n            return value\\n        else:\\n            return parsed\\n\\n    def _process_body(self, body: Any) -> dict:\\n        \\"\\"\\"Process the body input into a valid dictionary.\\"\\"\\"\\n        if body is None:\\n            return {}\\n        if isinstance(body, dict):\\n            return self._process_dict_body(body)\\n        if isinstance(body, str):\\n            return self._process_string_body(body)\\n        if isinstance(body, list):\\n            return self._process_list_body(body)\\n        return {}\\n\\n    def _process_dict_body(self, body: dict) -> dict:\\n        \\"\\"\\"Process dictionary body by parsing JSON values.\\"\\"\\"\\n        return {k: self._parse_json_value(v) for k, v in body.items()}\\n\\n    def _process_string_body(self, body: str) -> dict:\\n        \\"\\"\\"Process string body by attempting JSON parse.\\"\\"\\"\\n        try:\\n            return self._process_body(json.loads(body))\\n        except json.JSONDecodeError:\\n            return {\\"data\\": body}\\n\\n    def _process_list_body(self, body: list) -> dict:\\n        \\"\\"\\"Process list body by converting to key-value dictionary.\\"\\"\\"\\n        processed_dict = {}\\n        try:\\n            for item in body:\\n                if not self._is_valid_key_value_item(item):\\n                    continue\\n                key = item[\\"key\\"]\\n                value = self._parse_json_value(item[\\"value\\"])\\n                processed_dict[key] = value\\n        except (KeyError, TypeError, ValueError) as e:\\n            self.log(f\\"Failed to process body list: {e}\\")\\n            return {}\\n        return processed_dict\\n\\n    def _is_valid_key_value_item(self, item: Any) -> bool:\\n        \\"\\"\\"Check if an item is a valid key-value dictionary.\\"\\"\\"\\n        return isinstance(item, dict) and \\"key\\" in item and \\"value\\" in item\\n\\n    def parse_curl(self, curl: str, build_config: dotdict) -> dotdict:\\n        \\"\\"\\"Parse a cURL command and update build configuration.\\"\\"\\"\\n        try:\\n            parsed = parse_context(curl)\\n\\n            # Update basic configuration\\n            url = parsed.url\\n            # Normalize URL before setting it\\n            url = self._normalize_url(url)\\n\\n            build_config[\\"url_input\\"][\\"value\\"] = url\\n            build_config[\\"method\\"][\\"value\\"] = parsed.method.upper()\\n\\n            # Process headers\\n            headers_list = [{\\"key\\": k, \\"value\\": v} for k, v in parsed.headers.items()]\\n            build_config[\\"headers\\"][\\"value\\"] = headers_list\\n\\n            # Process body data\\n            if not parsed.data:\\n                build_config[\\"body\\"][\\"value\\"] = []\\n            elif parsed.data:\\n                try:\\n                    json_data = json.loads(parsed.data)\\n                    if isinstance(json_data, dict):\\n                        body_list = [\\n                            {\\"key\\": k, \\"value\\": json.dumps(v) if isinstance(v, dict | list) else str(v)}\\n                            for k, v in json_data.items()\\n                        ]\\n                        build_config[\\"body\\"][\\"value\\"] = body_list\\n                    else:\\n                        build_config[\\"body\\"][\\"value\\"] = [{\\"key\\": \\"data\\", \\"value\\": json.dumps(json_data)}]\\n                except json.JSONDecodeError:\\n                    build_config[\\"body\\"][\\"value\\"] = [{\\"key\\": \\"data\\", \\"value\\": parsed.data}]\\n\\n        except Exception as exc:\\n            msg = f\\"Error parsing curl: {exc}\\"\\n            self.log(msg)\\n            raise ValueError(msg) from exc\\n\\n        return build_config\\n\\n    def _normalize_url(self, url: str) -> str:\\n        \\"\\"\\"Normalize URL by adding https:// if no protocol is specified.\\"\\"\\"\\n        if not url or not isinstance(url, str):\\n            msg = \\"URL cannot be empty\\"\\n            raise ValueError(msg)\\n\\n        url = url.strip()\\n        if url.startswith((\\"http://\\", \\"https://\\")):\\n            return url\\n        return f\\"https://{url}\\"\\n\\n    async def make_request(\\n        self,\\n        client: httpx.AsyncClient,\\n        method: str,\\n        url: str,\\n        headers: dict | None = None,\\n        body: Any = None,\\n        timeout: int = 5,\\n        *,\\n        follow_redirects: bool = True,\\n        save_to_file: bool = False,\\n        include_httpx_metadata: bool = False,\\n    ) -> Data:\\n        method = method.upper()\\n        if method not in {\\"GET\\", \\"POST\\", \\"PATCH\\", \\"PUT\\", \\"DELETE\\"}:\\n            msg = f\\"Unsupported method: {method}\\"\\n            raise ValueError(msg)\\n\\n        processed_body = self._process_body(body)\\n        redirection_history = []\\n\\n        try:\\n            # Prepare request parameters\\n            request_params = {\\n                \\"method\\": method,\\n                \\"url\\": url,\\n                \\"headers\\": headers,\\n                \\"json\\": processed_body,\\n                \\"timeout\\": timeout,\\n                \\"follow_redirects\\": follow_redirects,\\n            }\\n            response = await client.request(**request_params)\\n\\n            redirection_history = [\\n                {\\n                    \\"url\\": redirect.headers.get(\\"Location\\", str(redirect.url)),\\n                    \\"status_code\\": redirect.status_code,\\n                }\\n                for redirect in response.history\\n            ]\\n\\n            is_binary, file_path = await self._response_info(response, with_file_path=save_to_file)\\n            response_headers = self._headers_to_dict(response.headers)\\n\\n            # Base metadata\\n            metadata = {\\n                \\"source\\": url,\\n                \\"status_code\\": response.status_code,\\n                \\"response_headers\\": response_headers,\\n            }\\n\\n            if redirection_history:\\n                metadata[\\"redirection_history\\"] = redirection_history\\n\\n            if save_to_file:\\n                mode = \\"wb\\" if is_binary else \\"w\\"\\n                encoding = response.encoding if mode == \\"w\\" else None\\n                if file_path:\\n                    await aiofiles_os.makedirs(file_path.parent, exist_ok=True)\\n                    if is_binary:\\n                        async with aiofiles.open(file_path, \\"wb\\") as f:\\n                            await f.write(response.content)\\n                            await f.flush()\\n                    else:\\n                        async with aiofiles.open(file_path, \\"w\\", encoding=encoding) as f:\\n                            await f.write(response.text)\\n                            await f.flush()\\n                    metadata[\\"file_path\\"] = str(file_path)\\n\\n                if include_httpx_metadata:\\n                    metadata.update({\\"headers\\": headers})\\n                return Data(data=metadata)\\n\\n            # Handle response content\\n            if is_binary:\\n                result = response.content\\n            else:\\n                try:\\n                    result = response.json()\\n                except json.JSONDecodeError:\\n                    self.log(\\"Failed to decode JSON response\\")\\n                    result = response.text.encode(\\"utf-8\\")\\n\\n            metadata[\\"result\\"] = result\\n\\n            if include_httpx_metadata:\\n                metadata.update({\\"headers\\": headers})\\n\\n            return Data(data=metadata)\\n        except (httpx.HTTPError, httpx.RequestError, httpx.TimeoutException) as exc:\\n            self.log(f\\"Error making request to {url}\\")\\n            return Data(\\n                data={\\n                    \\"source\\": url,\\n                    \\"headers\\": headers,\\n                    \\"status_code\\": 500,\\n                    \\"error\\": str(exc),\\n                    **({\\"redirection_history\\": redirection_history} if redirection_history else {}),\\n                },\\n            )\\n\\n    def add_query_params(self, url: str, params: dict) -> str:\\n        \\"\\"\\"Add query parameters to URL efficiently.\\"\\"\\"\\n        if not params:\\n            return url\\n        url_parts = list(urlparse(url))\\n        query = dict(parse_qsl(url_parts[4]))\\n        query.update(params)\\n        url_parts[4] = urlencode(query)\\n        return urlunparse(url_parts)\\n\\n    def _headers_to_dict(self, headers: httpx.Headers) -> dict[str, str]:\\n        \\"\\"\\"Convert HTTP headers to a dictionary with lowercased keys.\\"\\"\\"\\n        return {k.lower(): v for k, v in headers.items()}\\n\\n    def _process_headers(self, headers: Any) -> dict:\\n        \\"\\"\\"Process the headers input into a valid dictionary.\\"\\"\\"\\n        if headers is None:\\n            return {}\\n        if isinstance(headers, dict):\\n            return headers\\n        if isinstance(headers, list):\\n            return {item[\\"key\\"]: item[\\"value\\"] for item in headers if self._is_valid_key_value_item(item)}\\n        return {}\\n\\n    async def make_api_request(self) -> Data:\\n        \\"\\"\\"Make HTTP request with optimized parameter handling.\\"\\"\\"\\n        method = self.method\\n        url = self.url_input.strip() if isinstance(self.url_input, str) else \\"\\"\\n        headers = self.headers or {}\\n        body = self.body or {}\\n        timeout = self.timeout\\n        follow_redirects = self.follow_redirects\\n        save_to_file = self.save_to_file\\n        include_httpx_metadata = self.include_httpx_metadata\\n\\n        # if self.mode == \\"cURL\\" and self.curl_input:\\n        #     self._build_config = self.parse_curl(self.curl_input, dotdict())\\n        #     # After parsing curl, get the normalized URL\\n        #     url = self._build_config[\\"url_input\\"][\\"value\\"]\\n\\n        # Normalize URL before validation\\n        url = self._normalize_url(url)\\n\\n        # Validate URL\\n        if not validators.url(url):\\n            msg = f\\"Invalid URL provided: {url}\\"\\n            raise ValueError(msg)\\n\\n        # Process query parameters\\n        if isinstance(self.query_params, str):\\n            query_params = dict(parse_qsl(self.query_params))\\n        else:\\n            query_params = self.query_params.data if self.query_params else {}\\n\\n        # Process headers and body\\n        headers = self._process_headers(headers)\\n        body = self._process_body(body)\\n        url = self.add_query_params(url, query_params)\\n\\n        async with httpx.AsyncClient() as client:\\n            result = await self.make_request(\\n                client,\\n                method,\\n                url,\\n                headers,\\n                body,\\n                timeout,\\n                follow_redirects=follow_redirects,\\n                save_to_file=save_to_file,\\n                include_httpx_metadata=include_httpx_metadata,\\n            )\\n        self.status = result\\n        return result\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:\\n        \\"\\"\\"Update the build config based on the selected mode.\\"\\"\\"\\n        if field_name != \\"mode\\":\\n            if field_name == \\"curl_input\\" and self.mode == \\"cURL\\" and self.curl_input:\\n                return self.parse_curl(self.curl_input, build_config)\\n            return build_config\\n\\n        # print(f\\"Current mode: {field_value}\\")\\n        if field_value == \\"cURL\\":\\n            set_field_display(build_config, \\"curl_input\\", value=True)\\n            if build_config[\\"curl_input\\"][\\"value\\"]:\\n                build_config = self.parse_curl(build_config[\\"curl_input\\"][\\"value\\"], build_config)\\n        else:\\n            set_field_display(build_config, \\"curl_input\\", value=False)\\n\\n        return set_current_fields(\\n            build_config=build_config,\\n            action_fields=MODE_FIELDS,\\n            selected_action=field_value,\\n            default_fields=DEFAULT_FIELDS,\\n            func=set_field_advanced,\\n            default_value=True,\\n        )\\n\\n    async def _response_info(\\n        self, response: httpx.Response, *, with_file_path: bool = False\\n    ) -> tuple[bool, Path | None]:\\n        \\"\\"\\"Determine the file path and whether the response content is binary.\\n\\n        Args:\\n            response (Response): The HTTP response object.\\n            with_file_path (bool): Whether to save the response content to a file.\\n\\n        Returns:\\n            Tuple[bool, Path | None]:\\n                A tuple containing a boolean indicating if the content is binary and the full file path (if applicable).\\n        \\"\\"\\"\\n        content_type = response.headers.get(\\"Content-Type\\", \\"\\")\\n        is_binary = \\"application/octet-stream\\" in content_type or \\"application/binary\\" in content_type\\n\\n        if not with_file_path:\\n            return is_binary, None\\n\\n        component_temp_dir = Path(tempfile.gettempdir()) / self.__class__.__name__\\n\\n        # Create directory asynchronously\\n        await aiofiles_os.makedirs(component_temp_dir, exist_ok=True)\\n\\n        filename = None\\n        if \\"Content-Disposition\\" in response.headers:\\n            content_disposition = response.headers[\\"Content-Disposition\\"]\\n            filename_match = re.search(r'filename=\\"(.+?)\\"', content_disposition)\\n            if filename_match:\\n                extracted_filename = filename_match.group(1)\\n                filename = extracted_filename\\n\\n        # Step 3: Infer file extension or use part of the request URL if no filename\\n        if not filename:\\n            # Extract the last segment of the URL path\\n            url_path = urlparse(str(response.request.url) if response.request else \\"\\").path\\n            base_name = Path(url_path).name  # Get the last segment of the path\\n            if not base_name:  # If the path ends with a slash or is empty\\n                base_name = \\"response\\"\\n\\n            # Infer file extension\\n            content_type_to_extension = {\\n                \\"text/plain\\": \\".txt\\",\\n                \\"application/json\\": \\".json\\",\\n                \\"image/jpeg\\": \\".jpg\\",\\n                \\"image/png\\": \\".png\\",\\n                \\"application/octet-stream\\": \\".bin\\",\\n            }\\n            extension = content_type_to_extension.get(content_type, \\".bin\\" if is_binary else \\".txt\\")\\n            filename = f\\"{base_name}{extension}\\"\\n\\n        # Step 4: Define the full file path\\n        file_path = component_temp_dir / filename\\n\\n        # Step 5: Check if file exists asynchronously and handle accordingly\\n        try:\\n            # Try to create the file exclusively (x mode) to check existence\\n            async with aiofiles.open(file_path, \\"x\\") as _:\\n                pass  # File created successfully, we can use this path\\n        except FileExistsError:\\n            # If file exists, append a timestamp to the filename\\n            timestamp = datetime.now(timezone.utc).strftime(\\"%Y%m%d%H%M%S%f\\")\\n            file_path = component_temp_dir / f\\"{timestamp}-{filename}\\"\\n\\n        return is_binary, file_path\\n"}, "curl_input": {"_input_type": "MultilineInput", "advanced": true, "copy_field": false, "display_name": "cURL", "dynamic": false, "info": "Paste a curl command to populate the fields. This will fill in the dictionary fields for headers and body.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "curl_input", "placeholder": "", "real_time_refresh": true, "required": false, "show": false, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "follow_redirects": {"_input_type": "BoolInput", "advanced": true, "display_name": "Follow Redirects", "dynamic": false, "info": "Whether to follow http redirects.", "list": false, "list_add_label": "Add More", "name": "follow_redirects", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "headers": {"_input_type": "TableInput", "advanced": true, "display_name": "Headers", "dynamic": false, "info": "The headers to send with the request", "input_types": ["Data"], "is_list": true, "list_add_label": "Add More", "name": "headers", "placeholder": "", "required": false, "show": true, "table_icon": "Table", "table_schema": {"columns": [{"default": "None", "description": "Header name", "disable_edit": false, "display_name": "Header", "edit_mode": "popover", "filterable": true, "formatter": "text", "hidden": false, "name": "key", "sortable": true, "type": "str"}, {"default": "None", "description": "Header value", "disable_edit": false, "display_name": "Value", "edit_mode": "popover", "filterable": true, "formatter": "text", "hidden": false, "name": "value", "sortable": true, "type": "str"}]}, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "trigger_icon": "Table", "trigger_text": "Open table", "type": "table", "value": []}, "include_httpx_metadata": {"_input_type": "BoolInput", "advanced": true, "display_name": "Include HTTPx Metadata", "dynamic": false, "info": "Include properties such as headers, status_code, response_headers, and redirection_history in the output.", "list": false, "list_add_label": "Add More", "name": "include_httpx_metadata", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "method": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Method", "dynamic": false, "info": "The HTTP method to use.", "name": "method", "options": ["GET", "POST", "PATCH", "PUT", "DELETE"], "options_metadata": [], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "GET"}, "mode": {"_input_type": "TabInput", "advanced": false, "display_name": "