age"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "system_prompt", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "You are a helpful assistant that must use tools to answer questions and perform tasks regarding RTX Remix.\\n\\nBefore "}, "temperature": {"_input_type": "SliderInput", "advanced": true, "display_name": "Temperature", "dynamic": false, "info": "", "max_label": "", "max_label_icon": "", "min_label": "", "min_label_icon": "", "name": "temperature", "placeholder": "", "range_spec": {"max": 1, "min": 0, "step": 0.01, "step_type": "float"}, "required": false, "show": true, "slider_buttons": false, "slider_buttons_options": [], "slider_input": false, "title_case": false, "tool_mode": false, "type": "slider", "value": 0.1}, "template": {"_input_type": "MultilineInput", "advanced": true, "copy_field": false, "display_name": "Template", "dynamic": false, "info": "The template to use for formatting the data. It can contain the keys {text}, {sender} or any other key in the message data.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "{sender_name}: {text}"}, "timeout": {"_input_type": "IntInput", "advanced": true, "display_name": "Timeout", "dynamic": false, "info": "The timeout for requests to OpenAI completion API.", "list": false, "list_add_label": "Add More", "name": "timeout", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 700}, "tools": {"_input_type": "HandleInput", "advanced": false, "display_name": "Tools", "dynamic": false, "info": "These are the tools that the agent can use to help with tasks.", "input_types": ["Tool"], "list": true, "list_add_label": "Add More", "name": "tools", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "verbose": {"_input_type": "BoolInput", "advanced": true, "display_name": "Verbose", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "verbose", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}}, "tool_mode": false}, "showNode": true, "type": "Agent"}, "dragging": false, "id": "Agent-9dON7", "measured": {"height": 591, "width": 320}, "position": {"x": 78.6911094428821, "y": -159.83908350054932}, "selected": false, "type": "genericNode"}, {"data": {"id": "Prompt-PrjbV", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {"template": ["remix_documentation", "remix_mcp_server", "mcp_prompts"]}, "description": "Create a prompt template with dynamic variables.", "display_name": "Prompt", "documentation": "", "edited": false, "error": null, "field_order": ["template", "tool_placeholder"], "frozen": false, "full_path": null, "icon": "prompts", "is_composition": null, "is_input": null, "is_output": null, "legacy": false, "lf_version": "1.4.2", "metadata": {}, "minimized": false, "name": "", "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Prompt Message", "method": "build_prompt", "name": "prompt", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "priority": null, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.base.prompts.api_utils import process_prompt_template\\nfrom langflow.custom import Component\\nfrom langflow.inputs.inputs import DefaultPromptField\\nfrom langflow.io import MessageTextInput, Output, PromptInput\\nfrom langflow.schema.message import Message\\nfrom langflow.template.utils import update_template_values\\n\\n\\nclass PromptComponent(Component):\\n    display_name: str = \\"Prompt\\"\\n    description: str = \\"Create a prompt template with dynamic variables.\\"\\n    icon = \\"prompts\\"\\n    trace_type = \\"prompt\\"\\n    name = \\"Prompt\\"\\n\\n    inputs = [\\n        PromptInput(name=\\"template\\", display_name=\\"Template\\"),\\n        MessageTextInput(\\n            name=\\"tool_placeholder\\",\\n            display_name=\\"Tool Placeholder\\",\\n            tool_mode=True,\\n            advanced=True,\\n            info=\\"A placeholder input for tool mode.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Prompt Message\\", name=\\"prompt\\", method=\\"build_prompt\\"),\\n    ]\\n\\n    async def build_prompt(self) -> Message:\\n        prompt = Message.from_template(**self._attributes)\\n        self.status = prompt.text\\n        return prompt\\n\\n    def _update_template(self, frontend_node: dict):\\n        prompt_template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        custom_fields = frontend_node[\\"custom_fields\\"]\\n        frontend_node_template = frontend_node[\\"template\\"]\\n        _ = process_prompt_template(\\n            template=prompt_template,\\n            name=\\"template\\",\\n            custom_fields=custom_fields,\\n            frontend_node_template=frontend_node_template,\\n        )\\n        return frontend_node\\n\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict):\\n        \\"\\"\\"This function is called after the code validation is done.\\"\\"\\"\\n        frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        # Kept it duplicated for backwards compatibility\\n        _ = process_prompt_template(\\n            template=template,\\n            name=\\"template\\",\\n            custom_fields=frontend_node[\\"custom_fields\\"],\\n            frontend_node_template=frontend_node[\\"template\\"],\\n        )\\n        # Now that template is updated, we need to grab any values that were set in the current_frontend_node\\n        # and update the frontend_node with those values\\n        update_template_values(new_template=frontend_node, previous_template=current_frontend_node[\\"template\\"])\\n        return frontend_node\\n\\n    def _get_fallback_input(self, **kwargs):\\n        return DefaultPromptField(**kwargs)\\n"}, "mcp_prompts": {"advanced": false, "display_name": "mcp_prompts", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message"], "list": false, "load_from_db": false, "multiline": true, "name": "mcp_prompts", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": ""}, "remix_documentation": {"advanced": false, "display_name": "remix_documentation", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message"], "list": false, "load_from_db": false, "multiline": true, "name": "remix_documentation", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": "FAISS"}, "remix_mcp_server": {"advanced": false, "display_name": "remix_mcp_server", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message"], "list": false, "load_from_db": false, "multiline": true, "name": "remix_mcp_server", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": "RTX Remix Toolkit Connection"}, "template": {"_input_type": "PromptInput", "advanced": false, "display_name": "Template", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "type": "prompt", "value": "# Background\\n\\nYou are a helpful assistant that must use tools to answer questions and perform tasks regarding RTX Remix.\\n\\n# Procedure\\n\\n- You MUST ABSOLUTELY ALWAYS search through the documentation before responding to the user. Follow the instructions in the \\"Documentation Instructions\\" section for instruction on using the documentation.\\n- When the user asks how to do something, always assume they are asking about the RTX Remix Toolkit or Runtime Graphic User Interfaces unless specified otherwise (DO NOT mention the tools available to you).\\n- If the user requested you take an action or provide information about the current project, you may follow the instructions in the \\"RTX Remix Toolkit Instructions\\" section.\\n\\n# Documentation Instructions\\n\\n- DO NOT ATTEMPT, UNDER ANY CIRCUMSTANCES TO PROVIDE AN ANSWER BASED ON YOUR TRAINING DATA.\\n- Use the {remix_documentation} tool to fetch the requested information from the RTX Remix documentation.\\n- Always provide the source you used to get to the answer provided to the user.\\n- If the user asks a question that can be ambiguous, request that they provide more information.\\n- If the user asks a question that cannot be answered using the documentation, simply say so and don't attempt to answer the question.\\n\\n# RTX Remix Toolkit Instructions\\n\\n- Use the tools provided by the \\"{remix_mcp_server}\\" MCP Server to interact with the RTX Remix Toolkit.\\n- Always verify if a recipe provided in the \\"MCP Server Recipes\\" sub-section matches the current user request. \\n    - If a recipe matches, follow the instructions as closely as possible\\n    - If NO recipe matches the user request, try to use any combination of tools to complete the user's request\\n\\n## MCP Server Recipes\\n\\n{mcp_prompts}"}, "tool_placeholder": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Tool Placeholder", "dynamic": false, "info": "A placeholder input for tool mode.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "tool_placeholder", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "showNode": true, "type": "Prompt"}, "dragging": false, "id": "Prompt-PrjbV", "measured": {"height": 529, "width": 320}, "position": {"x": -338.00443250004696, "y": -753.7815399447686}, "selected": false, "type": "genericNode"}, {"data": {"id": "RemixDocumentation-DEIws", "node": {"base_classes": ["Data", "DataFrame"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Fetch information from the NVIDIA RTX Remix documentation", "display_name": "RTX Remix Documentation", "documentation": "https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/index.html", "edited": true, "field_order": ["exclude_paths"], "frozen": false, "icon": "NVIDIA", "legacy": false, "lf_version": "1.4.2", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "DataFrame", "hidden": false, "method": "fetch_documentation_dataframe", "name": "dataframe_output", "options": null, "required_inputs": null, "selected": "DataFrame", "tool_mode": true, "types": ["DataFrame"], "value": "__UNDEFINED__"}, {"allows_loop": false, "cache": true, "display_name": "Data", "hidden": null, "method": "fetch_documentation_data", "name": "data_output", "options": null, "required_inputs": null, "selected": "Data", "tool_mode": true, "types": ["Data"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import httpx\\r\\nimport json\\r\\nimport re\\r\\nfrom langflow.custom import Component\\r\\nfrom langflow.io import Output, MessageTextInput\\r\\nfrom langflow.schema import DataFrame, Data\\r\\n\\r\\n\\r\\nclass RemixDocumentation(Component):\\r\\n    display_name = \\"RTX Remix Documentation\\"\\r\\n    description = \\"Fetch information from the NVIDIA RTX Remix documentation\\"\\r\\n    documentation: str = (\\r\\n        \\"https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/index.html\\"\\r\\n    )\\r\\n    icon = \\"NVIDIA\\"\\r\\n    name = \\"RemixDocumentation\\"\\r\\n\\r\\n    inputs = [\\r\\n        MessageTextInput(\\r\\n            name=\\"exclude_paths\\",\\r\\n            display_name=\\"Exclude Paths\\",\\r\\n            info=(\\r\\n                \\"List of path prefixes to exclude from results. \\"\\r\\n                \\"Used to filter out sections of the documentation that are not typically relevant to user queries.\\"\\r\\n            ),\\r\\n            is_list=True,\\r\\n            value=[\\r\\n                \\"source\\",\\r\\n                \\"CHANGELOG.html\\",\\r\\n                \\"docs/changelog\\",\\r\\n                \\"docs/contributing/api.html\\",\\r\\n            ],\\r\\n        ),\\r\\n    ]\\r\\n\\r\\n    outputs = [\\r\\n        Output(\\r\\n            display_name=\\"DataFrame\\",\\r\\n            name=\\"dataframe_output\\",\\r\\n            method=\\"fetch_documentation_dataframe\\",\\r\\n        ),\\r\\n        Output(\\r\\n            display_name=\\"Data\\", name=\\"data_output\\", method=\\"fetch_documentation_data\\"\\r\\n        ),\\r\\n    ]\\r\\n\\r\\n    _BASE_URL = \\"https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/\\"\\r\\n\\r\\n    def _fetch_all_documentation(self) -> list[Data]:\\r\\n        \\"\\"\\"Fetch all documentation entries and return as list of Data objects.\\"\\"\\"\\r\\n        # URL for the search index JavaScript file\\r\\n        search_index_url = self._BASE_URL + \\"searchindex.js\\"\\r\\n\\r\\n        # Fetch the search index file\\r\\n        response = httpx.get(search_index_url, follow_redirects=True)\\r\\n        response.raise_for_status()\\r\\n\\r\\n        # Extract the JSON data from the JavaScript file\\r\\n        # The file contains: const searchData = {...};\\r\\n        js_content = response.text\\r\\n\\r\\n        # Extract the JSON part using regex\\r\\n        match = re.search(r\\"const searchData = ({.*});\\", js_content, re.DOTALL)\\r\\n        if not match:\\r\\n            raise ValueError(\\"Could not parse search index data\\")\\r\\n\\r\\n        # Parse the JSON data\\r\\n        search_data = json.loads(match.group(1))\\r\\n\\r\\n        # Get the data array which contains all searchable items\\r\\n        data_items = search_data.get(\\"data\\", [])\\r\\n\\r\\n        results = []\\r\\n        for item in data_items:\\r\\n            filename = item.get(\\"filename\\", \\"\\")\\r\\n            text = item.get(\\"content\\", \\"\\")\\r\\n\\r\\n            if not text:\\r\\n                continue\\r\\n\\r\\n            # Check if filename should be excluded\\r\\n            should_exclude = False\\r\\n            for exclude_path in self.exclude_paths:\\r\\n                if filename.startswith(exclude_path):\\r\\n                    should_exclude = True\\r\\n                    break\\r\\n\\r\\n            if should_exclude:\\r\\n                continue\\r\\n\\r\\n            # Build URL with proper handling of empty anchors\\r\\n            anchor = item.get(\\"anchor\\", \\"\\")\\r\\n            if anchor:\\r\\n                url = f\\"{self._BASE_URL}{filename}#{anchor}\\"\\r\\n            else:\\r\\n                url = f\\"{self._BASE_URL}{filename}\\"\\r\\n\\r\\n            results.append(\\r\\n                Data(\\r\\n                    title=item.get(\\"display_name\\", \\"\\"),\\r\\n                    text=text,\\r\\n                    url=url,\\r\\n                )\\r\\n            )\\r\\n\\r\\n        # If no results found, create a single entry indicating no results\\r\\n        if not results:\\r\\n            data = Data(\\r\\n                title=\\"No documentation found\\",\\r\\n                text=\\"No documentation entries were found in the search index\\",\\r\\n                url=search_index_url,\\r\\n            )\\r\\n            results.append(data)\\r\\n\\r\\n        return results\\r\\n\\r\\n    def fetch_documentation_dataframe(self) -> DataFrame:\\r\\n        \\"\\"\\"Fetch documentation and return as DataFrame.\\"\\"\\"\\r\\n        results = self._fetch_all_documentation()\\r\\n        data_frame = DataFrame(results)\\r\\n        self.status = data_frame\\r\\n        return data_frame\\r\\n\\r\\n    def fetch_documentation_data(self) -> list[Data]:\\r\\n        \\"\\"\\"Fetch documentation and return as list of Data objects.\\"\\"\\"\\r\\n        results = self._fetch_all_documentation()\\r\\n        self.status = results\\r\\n        return results\\r\\n"}, "exclude_paths": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "Exclude Paths", "dynamic": false, "info": "List of path prefixes to exclude from results. Used to filter out sections of the documentation that are not typically relevant to user queries.", "input_types": ["Message"], "list": true, "list_add_label": "Add More", "load_from_db": false, "name": "exclude_paths", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ["source", "docs/changelog", "CHANGELOG.html", "docs/contributing/api.html"]}}, "tool_mode": false}, "showNode": true, "type": "RemixDocumentation"}, "dragging": false, "id": "RemixDocumentation-DEIws", "measured": {"height": 373, "width": 320}, "position": {"x": -783.4316223978514, "y": -373.75276518828326}, "selected": false, "type": "genericNode"}, {"data": {"description": "Generate embeddings using a specified provider.", "display_name": "Embedding Model", "id": "EmbeddingModel-X6URU", "node": {"base_classes": ["Embeddings"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Generate embeddings using a specified provider.", "display_name": "Embedding Model", "documentation": "", "edited": false, "field_order": ["provider", "model", "api_key", "api_base", "dimensions", "chunk_size", "request_timeout", "max_retries", "show_progress_bar", "model_kwargs"], "frozen": false, "icon": "binary", "legacy": false, "lf_version": "1.4.2", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"types": ["Embeddings"], "selected": "Embeddings", "name": "embeddings", "display_name": "Embedding Model", "method": "build_embeddings", "value": "__UNDEFINED__", "cache": true, "allows_loop": false, "group_outputs": false, "tool_mode": true}], "pinned": false, "template": {"_type": "Component", "api_base": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "API Base URL", "dynamic": false, "info": "Base URL for the API. Leave empty for default.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "api_base", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "OpenAI API Key", "dynamic": false, "info": "Model Provider API key", "input_types": [], "load_from_db": false, "name": "api_key", "password": true, "placeholder": "", "real_time_refresh": true, "required": true, "show": true, "title_case": false, "type": "str", "value": ""}, "chunk_size": {"_input_type": "IntInput", "advanced": true, "display_name": "Chunk Size", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "chunk_size", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 1000}, "code": {"type": "code", "required": true, "placeholder": "", "list": false, "show": true, "multiline": true, "value": "from typing import Any\\n\\nfrom langchain_openai import OpenAIEmbeddings\\n\\nfrom langflow.base.embeddings.model import LCEmbeddingsModel\\nfrom langflow.base.models.openai_constants import OPENAI_EMBEDDING_MODEL_NAMES\\nfrom langflow.field_typing import Embeddings\\nfrom langflow.io import (\\n    BoolInput,\\n    DictInput,\\n    DropdownInput,\\n    FloatInput,\\n    IntInput,\\n    MessageTextInput,\\n    SecretStrInput,\\n)\\nfrom langflow.schema.dotdict import dotdict\\n\\n\\nclass EmbeddingModelComponent(LCEmbeddingsModel):\\n    display_name = \\"Embedding Model\\"\\n    description = \\"Generate embeddings using a specified provider.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-embedding-models\\"\\n    icon = \\"binary\\"\\n    name = \\"EmbeddingModel\\"\\n    category = \\"models\\"\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\"provider\\",\\n            display_name=\\"Model Provider\\",\\n            options=[\\"OpenAI\\"],\\n            value=\\"OpenAI\\",\\n            info=\\"Select the embedding model provider\\",\\n            real_time_refresh=True,\\n            options_metadata=[{\\"icon\\": \\"OpenAI\\"}],\\n        ),\\n        DropdownInput(\\n            name=\\"model\\",\\n            display_name=\\"Model Name\\",\\n            options=OPENAI_EMBEDDING_MODEL_NAMES,\\n            value=OPENAI_EMBEDDING_MODEL_NAMES[0],\\n            info=\\"Select the embedding model to use\\",\\n        ),\\n        SecretStrInput(\\n            name=\\"api_key\\",\\n            display_name=\\"OpenAI API Key\\",\\n            info=\\"Model Provider API key\\",\\n            required=True,\\n            show=True,\\n            real_time_refresh=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"api_base\\",\\n            display_name=\\"API Base URL\\",\\n            info=\\"Base URL for the API. Leave empty for default.\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\"dimensions\\",\\n            display_name=\\"Dimensions\\",\\n            info=\\"The number of dimensions the resulting output embeddings should have. \\"\\n            \\"Only supported by certain models.\\",\\n            advanced=True,\\n        ),\\n        IntInput(name=\\"chunk_size\\", display_name=\\"Chunk Size\\", advanced=True, value=1000),\\n        FloatInput(name=\\"request_timeout\\", display_name=\\"Request Timeout\\", advanced=True),\\n        IntInput(name=\\"max_retries\\", display_name=\\"Max Retries\\", advanced=True, value=3),\\n        BoolInput(name=\\"show_progress_bar\\", display_name=\\"Show Progress Bar\\", advanced=True),\\n        DictInput(\\n            name=\\"model_kwargs\\",\\n            display_name=\\"Model Kwargs\\",\\n            advanced=True,\\n            info=\\"Additional keyword arguments to pass to the model.\\",\\n        ),\\n    ]\\n\\n    def build_embeddings(self) -> Embeddings:\\n        provider = self.provider\\n        model = self.model\\n        api_key = self.api_key\\n        api_base = self.api_base\\n        dimensions = self.dimensions\\n        chunk_size = self.chunk_size\\n        request_timeout = self.request_timeout\\n        max_retries = self.max_retries\\n        show_progress_bar = self.show_progress_bar\\n        model_kwargs = self.model_kwargs or {}\\n\\n        if provider == \\"OpenAI\\":\\n            if not api_key:\\n                msg = \\"OpenAI API key is required when using OpenAI provider\\"\\n                raise ValueError(msg)\\n            return OpenAIEmbeddings(\\n                model=model,\\n                dimensions=dimensions or None,\\n                base_url=api_base or None,\\n                api_key=api_key,\\n                chunk_size=chunk_size,\\n                max_retries=max_retries,\\n                timeout=request_timeout or None,\\n                show_progress_bar=show_progress_bar,\\n                model_kwargs=model_kwargs,\\n            )\\n        msg = f\\"Unknown provider: {provider}\\"\\n        raise ValueError(msg)\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:\\n        if field_name == \\"provider\\" and field_value == \\"OpenAI\\":\\n            build_config[\\"model\\"][\\"options\\"] = OPENAI_EMBEDDING_MODEL_NAMES\\n            build_config[\\"model\\"][\\"value\\"] = OPENAI_EMBEDDING_MODEL_NAMES[0]\\n            build_config[\\"api_key\\"][\\"display_name\\"] = \\"OpenAI API Key\\"\\n            build_config[\\"api_base\\"][\\"display_name\\"] = \\"OpenAI API Base URL\\"\\n        return build_config\\n", "fileTypes": [], "file_path": "", "password": false, "name": "code", "advanced": true, "dynamic": true, "info": "", "load_from_db": false, "title_case": false}, "dimensions": {"_input_type": "IntInput", "advanced": true, "display_name": "Dimensions", "dynamic": false, "info": "The number of dimensions the resulting output embeddings should have. Only supported by certain models.", "list": false, "list_add_label": "Add More", "name": "dimensions", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": ""}, "max_retries": {"_input_type": "IntInput", "advanced": true, "display_name": "Max Retries", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "max_retries", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 3}, "model": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Name", "dynamic": false, "info": "Select the embedding model to use", "name": "model", "options": ["text-embedding-3-small", "text-embedding-3-large", "text-embedding-ada-002"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "text-embedding-3-small"}, "model_kwargs": {"_input_type": "DictInput", "advanced": true, "display_name": "Model Kwargs", "dynamic": false, "info": "Additional keyword arguments to pass to the model.", "list": false, "list_add_label": "Add More", "name": "model_kwargs", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "type": "dict", "value": {}}, "provider": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Provider", "dynamic": false, "info": "Select the embedding model provider", "name": "provider", "options": ["OpenAI"], "options_metadata": [{"icon": "OpenAI"}], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "OpenAI"}, "request_timeout": {"_input_type": "FloatInput", "advanced": true, "display_name": "Request Timeout", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "request_timeout", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "float", "value": ""}, "show_progress_bar": {"_input_type": "BoolInput", "ad