code": {"type": "code", "required": true, "placeholder": "", "list": false, "show": true, "multiline": true, "value": "from pathlib import Path\\n\\nfrom langchain_community.vectorstores import FAISS\\n\\nfrom langflow.base.vectorstores.model import LCVectorStoreComponent, check_cached_vector_store\\nfrom langflow.helpers.data import docs_to_data\\nfrom langflow.io import BoolInput, HandleInput, IntInput, StrInput\\nfrom langflow.schema.data import Data\\n\\n\\nclass FaissVectorStoreComponent(LCVectorStoreComponent):\\n    \\"\\"\\"FAISS Vector Store with search capabilities.\\"\\"\\"\\n\\n    display_name: str = \\"FAISS\\"\\n    description: str = \\"FAISS Vector Store with search capabilities\\"\\n    name = \\"FAISS\\"\\n    icon = \\"FAISS\\"\\n\\n    inputs = [\\n        StrInput(\\n            name=\\"index_name\\",\\n            display_name=\\"Index Name\\",\\n            value=\\"langflow_index\\",\\n        ),\\n        StrInput(\\n            name=\\"persist_directory\\",\\n            display_name=\\"Persist Directory\\",\\n            info=\\"Path to save the FAISS index. It will be relative to where Langflow is running.\\",\\n        ),\\n        *LCVectorStoreComponent.inputs,\\n        BoolInput(\\n            name=\\"allow_dangerous_deserialization\\",\\n            display_name=\\"Allow Dangerous Deserialization\\",\\n            info=\\"Set to True to allow loading pickle files from untrusted sources. \\"\\n            \\"Only enable this if you trust the source of the data.\\",\\n            advanced=True,\\n            value=True,\\n        ),\\n        HandleInput(name=\\"embedding\\", display_name=\\"Embedding\\", input_types=[\\"Embeddings\\"]),\\n        IntInput(\\n            name=\\"number_of_results\\",\\n            display_name=\\"Number of Results\\",\\n            info=\\"Number of results to return.\\",\\n            advanced=True,\\n            value=4,\\n        ),\\n    ]\\n\\n    @staticmethod\\n    def resolve_path(path: str) -> str:\\n        \\"\\"\\"Resolve the path relative to the Langflow root.\\n\\n        Args:\\n            path: The path to resolve\\n        Returns:\\n            str: The resolved path as a string\\n        \\"\\"\\"\\n        return str(Path(path).resolve())\\n\\n    def get_persist_directory(self) -> Path:\\n        \\"\\"\\"Returns the resolved persist directory path or the current directory if not set.\\"\\"\\"\\n        if self.persist_directory:\\n            return Path(self.resolve_path(self.persist_directory))\\n        return Path()\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self) -> FAISS:\\n        \\"\\"\\"Builds the FAISS object.\\"\\"\\"\\n        path = self.get_persist_directory()\\n        path.mkdir(parents=True, exist_ok=True)\\n\\n        # Convert DataFrame to Data if needed using parent's method\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                documents.append(_input)\\n\\n        faiss = FAISS.from_documents(documents=documents, embedding=self.embedding)\\n        faiss.save_local(str(path), self.index_name)\\n        return faiss\\n\\n    def search_documents(self) -> list[Data]:\\n        \\"\\"\\"Search for documents in the FAISS vector store.\\"\\"\\"\\n        path = self.get_persist_directory()\\n        index_path = path / f\\"{self.index_name}.faiss\\"\\n\\n        if not index_path.exists():\\n            vector_store = self.build_vector_store()\\n        else:\\n            vector_store = FAISS.load_local(\\n                folder_path=str(path),\\n                embeddings=self.embedding,\\n                index_name=self.index_name,\\n                allow_dangerous_deserialization=self.allow_dangerous_deserialization,\\n            )\\n\\n        if not vector_store:\\n            msg = \\"Failed to load the FAISS index.\\"\\n            raise ValueError(msg)\\n\\n        if self.search_query and isinstance(self.search_query, str) and self.search_query.strip():\\n            docs = vector_store.similarity_search(\\n                query=self.search_query,\\n                k=self.number_of_results,\\n            )\\n            return docs_to_data(docs)\\n        return []\\n", "fileTypes": [], "file_path": "", "password": false, "name": "code", "advanced": true, "dynamic": true, "info": "", "load_from_db": false, "title_case": false}, "embedding": {"_input_type": "HandleInput", "advanced": false, "display_name": "Embedding", "dynamic": false, "info": "", "input_types": ["Embeddings"], "list": false, "list_add_label": "Add More", "name": "embedding", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "index_name": {"_input_type": "StrInput", "advanced": false, "display_name": "Index Name", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "index_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "langflow_index"}, "ingest_data": {"_input_type": "HandleInput", "advanced": false, "display_name": "Ingest Data", "dynamic": false, "info": "", "input_types": ["Data", "DataFrame"], "list": true, "list_add_label": "Add More", "name": "ingest_data", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "number_of_results": {"_input_type": "IntInput", "advanced": true, "display_name": "Number of Results", "dynamic": false, "info": "Number of results to return.", "list": false, "list_add_label": "Add More", "name": "number_of_results", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 4}, "persist_directory": {"_input_type": "StrInput", "advanced": false, "display_name": "Persist Directory", "dynamic": false, "info": "Path to save the FAISS index. It will be relative to where Langflow is running.", "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "persist_directory", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": ""}, "search_query": {"_input_type": "QueryInput", "advanced": false, "display_name": "Search Query", "dynamic": false, "info": "Enter a query to run a similarity search.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "search_query", "placeholder": "Enter a query...", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "query", "value": ""}, "should_cache_vector_store": {"_input_type": "BoolInput", "advanced": true, "display_name": "Cache Vector Store", "dynamic": false, "info": "If True, the vector store will be cached for the current build of the component. This is useful for components that have multiple output methods and want to share the same vector store.", "list": false, "list_add_label": "Add More", "name": "should_cache_vector_store", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "tools_metadata": {"_input_type": "ToolsInput", "advanced": false, "display_name": "Actions", "dynamic": false, "info": "Modify tool names and descriptions to help agents understand when to use each tool.", "is_list": true, "list_add_label": "Add More", "name": "tools_metadata", "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tools", "value": [{"args": {"search_query": {"default": "", "description": "Enter a query to run a similarity search.", "title": "Search Query", "type": "string"}}, "description": "FAISS. search_documents - FAISS Vector Store with search capabilities", "display_description": "FAISS. search_documents - FAISS Vector Store with search capabilities", "display_name": "search_documents", "name": "search_documents", "readonly": false, "status": true, "tags": ["search_documents"]}, {"args": {"search_query": {"default": "", "description": "Enter a query to run a similarity search.", "title": "Search Query", "type": "string"}}, "description": "FAISS. as_dataframe - FAISS Vector Store with search capabilities", "display_description": "FAISS. as_dataframe - FAISS Vector Store with search capabilities", "display_name": "as_dataframe", "name": "as_dataframe", "readonly": false, "status": true, "tags": ["as_dataframe"]}]}}, "tool_mode": true}, "showNode": true, "type": "FAISS"}, "dragging": false, "id": "FAISS-Uz8O4", "measured": {"height": 503, "width": 320}, "position": {"x": -344.50128361428034, "y": -176.20680066416054}, "selected": false, "type": "genericNode"}, {"data": {"id": "note-HQL5D", "node": {"description": "# RTX Remix Langflow Integration\\n\\nThis Langflow project provides an integration for the NVIDIA RTX Remix Toolkit through its REST API.\\n\\n## Prerequisites\\n\\nBefore using this project, ensure you have completed the following steps:\\n\\n1. **Install RTX Remix Toolkit**\\n   You must have the RTX Remix Toolkit installed on your system. Follow the installation guide here:\\n   [Installing the RTX Remix Toolkit](https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/docs/installation/install-toolkit.html)\\n\\n2. **Run RTX Remix Toolkit**\\n   Make sure the RTX Remix Toolkit application is running before using this Langflow project.\\n\\n3. **Create/Open a Project**\\n   You must have an RTX Remix project opened within the Toolkit. Learn how to set up a project here:\\n   [Setting Up a Project with the RTX Remix Toolkit](https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/docs/gettingstarted/learning-toolkitsetup.html)\\n\\n### Quick Start Tutorial\\n\\nTo quickly get started with RTX Remix, follow the [Building Your First Mod for the RTX Remix Sample](https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/docs/tutorials/tutorial-remixtool.html) tutorial.\\n\\nIt goes through the process of installing the various required parts, setting them up and getting a project up and running.\\n\\n## Getting Started\\n\\nOnce all prerequisites are met, the Langflow project should work without additional configuration.\\n\\n### Testing the Connection\\n\\nTo verify everything is working correctly:\\n\\n1. Open the Langflow project\\n2. Locate the **RTX Remix MCP Connection** node\\n3. Click the **refresh button** on the node\\n4. Verify that the various REST API tools appear\\n\\nIf the REST API tools appear after refreshing, your connection to RTX Remix Toolkit is working properly and you can begin using the available tools.\\n\\n## Additional Resources\\n\\n- [RTX Remix Documentation](https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/)\\n- [RTX Remix MCP Documentation](https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/docs/howto/learning-mcp.html)\\n- [RTX Remix REST API Documentation](https://docs.omniverse.nvidia.com/kit/docs/rtx_remix/latest/docs/howto/learning-restapi.html)", "display_name": "", "documentation": "", "template": {"backgroundColor": "lime"}}, "type": "note"}, "dragging": false, "height": 1454, "id": "note-HQL5D", "measured": {"height": 1454, "width": 452}, "position": {"x": -1257.898918275863, "y": -634.0975399601093}, "resizing": false, "selected": false, "type": "noteNode", "width": 452}, {"data": {"id": "MCPTools-beHVJ", "node": {"base_classes": ["DataFrame"], "beta": false, "category": "data", "conditional_paths": [], "custom_fields": {}, "description": "Connect to an MCP server to use its tools.", "display_name": "MCP Connection", "documentation": "", "edited": false, "field_order": ["mode", "command", "env", "sse_url", "headers_input", "tool", "tool_placeholder"], "frozen": false, "icon": "Mcp", "key": "MCPTools", "legacy": false, "lf_version": "1.4.2", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Toolset", "hidden": false, "method": "to_toolkit", "name": "component_as_tool", "options": null, "required_inputs": null, "selected": "Tool", "tool_mode": true, "types": ["Tool"], "value": "__UNDEFINED__"}], "pinned": false, "score": 0.003932426697386162, "template": {"_type": "Component", "code": {"type": "code", "required": true, "placeholder": "", "list": false, "show": true, "multiline": true, "value": "from __future__ import annotations\\n\\nimport asyncio\\nimport uuid\\nfrom typing import Any\\n\\nfrom langchain_core.tools import StructuredTool  # noqa: TC002\\n\\nfrom langflow.api.v2.mcp import get_server\\nfrom langflow.base.agents.utils import maybe_unflatten_dict, safe_cache_get, safe_cache_set\\nfrom langflow.base.mcp.util import (\\n    MCPSseClient,\\n    MCPStdioClient,\\n    create_input_schema_from_json_schema,\\n    update_tools,\\n)\\nfrom langflow.custom.custom_component.component_with_cache import ComponentWithCache\\nfrom langflow.inputs.inputs import InputTypes  # noqa: TC001\\nfrom langflow.io import DropdownInput, McpInput, MessageTextInput, Output\\nfrom langflow.io.schema import flatten_schema, schema_to_langflow_inputs\\nfrom langflow.logging import logger\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.services.auth.utils import create_user_longterm_token\\n\\n# Import get_server from the backend API\\nfrom langflow.services.database.models.user.crud import get_user_by_id\\nfrom langflow.services.deps import get_session, get_settings_service, get_storage_service\\n\\n\\nclass MCPToolsComponent(ComponentWithCache):\\n    schema_inputs: list = []\\n    tools: list[StructuredTool] = []\\n    _not_load_actions: bool = False\\n    _tool_cache: dict = {}\\n    _last_selected_server: str | None = None  # Cache for the last selected server\\n\\n    def __init__(self, **data) -> None:\\n        super().__init__(**data)\\n        # Initialize cache keys to avoid CacheMiss when accessing them\\n        self._ensure_cache_structure()\\n\\n        # Initialize clients with access to the component cache\\n        self.stdio_client: MCPStdioClient = MCPStdioClient(component_cache=self._shared_component_cache)\\n        self.sse_client: MCPSseClient = MCPSseClient(component_cache=self._shared_component_cache)\\n\\n    def _ensure_cache_structure(self):\\n        \\"\\"\\"Ensure the cache has the required structure.\\"\\"\\"\\n        # Check if servers key exists and is not CacheMiss\\n        servers_value = safe_cache_get(self._shared_component_cache, \\"servers\\")\\n        if servers_value is None:\\n            safe_cache_set(self._shared_component_cache, \\"servers\\", {})\\n\\n        # Check if last_selected_server key exists and is not CacheMiss\\n        last_server_value = safe_cache_get(self._shared_component_cache, \\"last_selected_server\\")\\n        if last_server_value is None:\\n            safe_cache_set(self._shared_component_cache, \\"last_selected_server\\", \\"\\")\\n\\n    default_keys: list[str] = [\\n        \\"code\\",\\n        \\"_type\\",\\n        \\"tool_mode\\",\\n        \\"tool_placeholder\\",\\n        \\"mcp_server\\",\\n        \\"tool\\",\\n    ]\\n\\n    display_name = \\"MCP Tools\\"\\n    description = \\"Connect to an MCP server to use its tools.\\"\\n    documentation: str = \\"https://docs.langflow.org/mcp-client\\"\\n    icon = \\"Mcp\\"\\n    name = \\"MCPTools\\"\\n\\n    inputs = [\\n        McpInput(\\n            name=\\"mcp_server\\",\\n            display_name=\\"MCP Server\\",\\n            info=\\"Select the MCP Server that will be used by this component\\",\\n            real_time_refresh=True,\\n        ),\\n        DropdownInput(\\n            name=\\"tool\\",\\n            display_name=\\"Tool\\",\\n            options=[],\\n            value=\\"\\",\\n            info=\\"Select the tool to execute\\",\\n            show=False,\\n            required=True,\\n            real_time_refresh=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"tool_placeholder\\",\\n            display_name=\\"Tool Placeholder\\",\\n            info=\\"Placeholder for the tool\\",\\n            value=\\"\\",\\n            show=False,\\n            tool_mode=False,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Response\\", name=\\"response\\", method=\\"build_output\\"),\\n    ]\\n\\n    async def _validate_schema_inputs(self, tool_obj) -> list[InputTypes]:\\n        \\"\\"\\"Validate and process schema inputs for a tool.\\"\\"\\"\\n        try:\\n            if not tool_obj or not hasattr(tool_obj, \\"args_schema\\"):\\n                msg = \\"Invalid tool object or missing input schema\\"\\n                raise ValueError(msg)\\n\\n            flat_schema = flatten_schema(tool_obj.args_schema.schema())\\n            input_schema = create_input_schema_from_json_schema(flat_schema)\\n            if not input_schema:\\n                msg = f\\"Empty input schema for tool '{tool_obj.name}'\\"\\n                raise ValueError(msg)\\n\\n            schema_inputs = schema_to_langflow_inputs(input_schema)\\n            if not schema_inputs:\\n                msg = f\\"No input parameters defined for tool '{tool_obj.name}'\\"\\n                logger.warning(msg)\\n                return []\\n\\n        except Exception as e:\\n            msg = f\\"Error validating schema inputs: {e!s}\\"\\n            logger.exception(msg)\\n            raise ValueError(msg) from e\\n        else:\\n            return schema_inputs\\n\\n    async def update_tool_list(self, mcp_server_value=None):\\n        # Accepts mcp_server_value as dict {name, config} or uses self.mcp_server\\n        mcp_server = mcp_server_value if mcp_server_value is not None else getattr(self, \\"mcp_server\\", None)\\n        server_name = None\\n        server_config_from_value = None\\n        if isinstance(mcp_server, dict):\\n            server_name = mcp_server.get(\\"name\\")\\n            server_config_from_value = mcp_server.get(\\"config\\")\\n        else:\\n            server_name = mcp_server\\n        if not server_name:\\n            self.tools = []\\n            return [], {\\"name\\": server_name, \\"config\\": server_config_from_value}\\n\\n        # Use shared cache if available\\n        servers_cache = safe_cache_get(self._shared_component_cache, \\"servers\\", {})\\n        cached = servers_cache.get(server_name) if isinstance(servers_cache, dict) else None\\n\\n        if cached is not None:\\n            self.tools = cached[\\"tools\\"]\\n            self.tool_names = cached[\\"tool_names\\"]\\n            self._tool_cache = cached[\\"tool_cache\\"]\\n            server_config_from_value = cached[\\"config\\"]\\n            return self.tools, {\\"name\\": server_name, \\"config\\": server_config_from_value}\\n\\n        try:\\n            async for db in get_session():\\n                user_id, _ = await create_user_longterm_token(db)\\n                current_user = await get_user_by_id(db, user_id)\\n\\n                # Try to get server config from DB/API\\n                server_config = await get_server(\\n                    server_name,\\n                    current_user,\\n                    db,\\n                    storage_service=get_storage_service(),\\n                    settings_service=get_settings_service(),\\n                )\\n\\n                # If get_server returns empty but we have a config, use it\\n                if not server_config and server_config_from_value:\\n                    server_config = server_config_from_value\\n\\n                if not server_config:\\n                    self.tools = []\\n                    return [], {\\"name\\": server_name, \\"config\\": server_config}\\n\\n                _, tool_list, tool_cache = await update_tools(\\n                    server_name=server_name,\\n                    server_config=server_config,\\n                    mcp_stdio_client=self.stdio_client,\\n                    mcp_sse_client=self.sse_client,\\n                )\\n\\n                self.tool_names = [tool.name for tool in tool_list if hasattr(tool, \\"name\\")]\\n                self._tool_cache = tool_cache\\n                self.tools = tool_list\\n                # Cache the result using shared cache\\n                cache_data = {\\n                    \\"tools\\": tool_list,\\n                    \\"tool_names\\": self.tool_names,\\n                    \\"tool_cache\\": tool_cache,\\n                    \\"config\\": server_config,\\n                }\\n\\n                # Safely update the servers cache\\n                current_servers_cache = safe_cache_get(self._shared_component_cache, \\"servers\\", {})\\n                if isinstance(current_servers_cache, dict):\\n                    current_servers_cache[server_name] = cache_data\\n                    safe_cache_set(self._shared_component_cache, \\"servers\\", current_servers_cache)\\n\\n                return tool_list, {\\"name\\": server_name, \\"config\\": server_config}\\n        except (TimeoutError, asyncio.TimeoutError) as e:\\n            msg = f\\"Timeout updating tool list: {e!s}\\"\\n            logger.exception(msg)\\n            raise TimeoutError(msg) from e\\n        except Exception as e:\\n            msg = f\\"Error updating tool list: {e!s}\\"\\n            logger.exception(msg)\\n            raise ValueError(msg) from e\\n\\n    async def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None) -> dict:\\n        \\"\\"\\"Toggle the visibility of connection-specific fields based on the selected mode.\\"\\"\\"\\n        try:\\n            if field_name == \\"tool\\":\\n                try:\\n                    if len(self.tools) == 0:\\n                        try:\\n                            self.tools, build_config[\\"mcp_server\\"][\\"value\\"] = await self.update_tool_list()\\n                            build_config[\\"tool\\"][\\"options\\"] = [tool.name for tool in self.tools]\\n                            build_config[\\"tool\\"][\\"placeholder\\"] = \\"Select a tool\\"\\n                        except (TimeoutError, asyncio.TimeoutError) as e:\\n                            msg = f\\"Timeout updating tool list: {e!s}\\"\\n                            logger.exception(msg)\\n                            if not build_config[\\"tools_metadata\\"][\\"show\\"]:\\n                                build_config[\\"tool\\"][\\"show\\"] = True\\n                                build_config[\\"tool\\"][\\"options\\"] = []\\n                                build_config[\\"tool\\"][\\"value\\"] = \\"\\"\\n                                build_config[\\"tool\\"][\\"placeholder\\"] = \\"Timeout on MCP server\\"\\n                            else:\\n                                build_config[\\"tool\\"][\\"show\\"] = False\\n                        except ValueError:\\n                            if not build_config[\\"tools_metadata\\"][\\"show\\"]:\\n                                build_config[\\"tool\\"][\\"show\\"] = True\\n                                build_config[\\"tool\\"][\\"options\\"] = []\\n                                build_config[\\"tool\\"][\\"value\\"] = \\"\\"\\n                                build_config[\\"tool\\"][\\"placeholder\\"] = \\"Error on MCP Server\\"\\n                            else:\\n                                build_config[\\"tool\\"][\\"show\\"] = False\\n\\n                    if field_value == \\"\\":\\n                        return build_config\\n                    tool_obj = None\\n                    for tool in self.tools:\\n                        if tool.name == field_value:\\n                            tool_obj = tool\\n                            break\\n                    if tool_obj is None:\\n                        msg = f\\"Tool {field_value} not found in available tools: {self.tools}\\"\\n                        logger.warning(msg)\\n                        return build_config\\n                    await self._update_tool_config(build_config, field_value)\\n                except Exception as e:\\n                    build_config[\\"tool\\"][\\"options\\"] = []\\n                    msg = f\\"Failed to update tools: {e!s}\\"\\n                    raise ValueError(msg) from e\\n                else:\\n                    return build_config\\n            elif field_name == \\"mcp_server\\":\\n                if not field_value:\\n                    build_config[\\"tool\\"][\\"show\\"] = False\\n                    build_config[\\"tool\\"][\\"options\\"] = []\\n                    build_config[\\"tool\\"][\\"value\\"] = \\"\\"\\n                    build_config[\\"tool\\"][\\"placeholder\\"] = \\"\\"\\n                    build_config[\\"tool_placeholder\\"][\\"tool_mode\\"] = False\\n                    self.remove_non_default_keys(build_config)\\n                    return build_config\\n\\n                build_config[\\"tool_placeholder\\"][\\"tool_mode\\"] = True\\n\\n                current_server_name = field_value.get(\\"name\\") if isinstance(field_value, dict) else field_value\\n                _last_selected_server = safe_cache_get(self._shared_component_cache, \\"last_selected_server\\", \\"\\")\\n\\n                # To avoid unnecessary updates, only proceed if the server has actually changed\\n                if (_last_selected_server in (current_server_name, \\"\\")) and build_config[\\"tool\\"][\\"show\\"]:\\n                    return build_config\\n\\n        