ageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "clean_data": {"_input_type": "BoolInput", "advanced": true, "display_name": "Basic Clean Data", "dynamic": false, "info": "Whether to clean the data", "list": false, "list_add_label": "Add More", "name": "clean_data", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from collections.abc import Generator\\nfrom typing import Any\\n\\nimport orjson\\nfrom fastapi.encoders import jsonable_encoder\\n\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.inputs.inputs import BoolInput, DropdownInput, HandleInput, MessageTextInput\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.schema.properties import Source\\nfrom langflow.template.field.base import Output\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_AI,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatOutput(ChatComponent):\\n    display_name = \\"Chat Output\\"\\n    description = \\"Display a chat message in the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-output\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatOutput\\"\\n    minimized = True\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Inputs\\",\\n            info=\\"Message to be passed as output.\\",\\n            input_types=[\\"Data\\", \\"DataFrame\\", \\"Message\\"],\\n            required=True,\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_AI,\\n            advanced=True,\\n            info=\\"Type of sender.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_AI,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"data_template\\",\\n            display_name=\\"Data Template\\",\\n            value=\\"{text}\\",\\n            advanced=True,\\n            info=\\"Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"clean_data\\",\\n            display_name=\\"Basic Clean Data\\",\\n            value=True,\\n            info=\\"Whether to clean the data\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\"Output Message\\",\\n            name=\\"message\\",\\n            method=\\"message_response\\",\\n        ),\\n    ]\\n\\n    def _build_source(self, id_: str | None, display_name: str | None, source: str | None) -> Source:\\n        source_dict = {}\\n        if id_:\\n            source_dict[\\"id\\"] = id_\\n        if display_name:\\n            source_dict[\\"display_name\\"] = display_name\\n        if source:\\n            # Handle case where source is a ChatOpenAI object\\n            if hasattr(source, \\"model_name\\"):\\n                source_dict[\\"source\\"] = source.model_name\\n            elif hasattr(source, \\"model\\"):\\n                source_dict[\\"source\\"] = str(source.model)\\n            else:\\n                source_dict[\\"source\\"] = str(source)\\n        return Source(**source_dict)\\n\\n    async def message_response(self) -> Message:\\n        # First convert the input to string if needed\\n        text = self.convert_to_string()\\n\\n        # Get source properties\\n        source, icon, display_name, source_id = self.get_properties_from_source_component()\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        if self.chat_icon:\\n            icon = self.chat_icon\\n\\n        # Create or use existing Message object\\n        if isinstance(self.input_value, Message):\\n            message = self.input_value\\n            # Update message properties\\n            message.text = text\\n        else:\\n            message = Message(text=text)\\n\\n        # Set message properties\\n        message.sender = self.sender\\n        message.sender_name = self.sender_name\\n        message.session_id = self.session_id\\n        message.flow_id = self.graph.flow_id if hasattr(self, \\"graph\\") else None\\n        message.properties.source = self._build_source(source_id, display_name, source)\\n        message.properties.icon = icon\\n        message.properties.background_color = background_color\\n        message.properties.text_color = text_color\\n\\n        # Store message if needed\\n        if self.session_id and self.should_store_message:\\n            stored_message = await self.send_message(message)\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n\\n    def _serialize_data(self, data: Data) -> str:\\n        \\"\\"\\"Serialize Data object to JSON string.\\"\\"\\"\\n        # Convert data.data to JSON-serializable format\\n        serializable_data = jsonable_encoder(data.data)\\n        # Serialize with orjson, enabling pretty printing with indentation\\n        json_bytes = orjson.dumps(serializable_data, option=orjson.OPT_INDENT_2)\\n        # Convert bytes to string and wrap in Markdown code blocks\\n        return \\"```json\\\\n\\" + json_bytes.decode(\\"utf-8\\") + \\"\\\\n```\\"\\n\\n    def _validate_input(self) -> None:\\n        \\"\\"\\"Validate the input data and raise ValueError if invalid.\\"\\"\\"\\n        if self.input_value is None:\\n            msg = \\"Input data cannot be None\\"\\n            raise ValueError(msg)\\n        if isinstance(self.input_value, list) and not all(\\n            isinstance(item, Message | Data | DataFrame | str) for item in self.input_value\\n        ):\\n            invalid_types = [\\n                type(item).__name__\\n                for item in self.input_value\\n                if not isinstance(item, Message | Data | DataFrame | str)\\n            ]\\n            msg = f\\"Expected Data or DataFrame or Message or str, got {invalid_types}\\"\\n            raise TypeError(msg)\\n        if not isinstance(\\n            self.input_value,\\n            Message | Data | DataFrame | str | list | Generator | type(None),\\n        ):\\n            type_name = type(self.input_value).__name__\\n            msg = f\\"Expected Data or DataFrame or Message or str, Generator or None, got {type_name}\\"\\n            raise TypeError(msg)\\n\\n    def convert_to_string(self) -> str | Generator[Any, None, None]:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        self._validate_input()\\n        if isinstance(self.input_value, list):\\n            return \\"\\\\n\\".join([safe_convert(item, clean_data=self.clean_data) for item in self.input_value])\\n        if isinstance(self.input_value, Generator):\\n            return self.input_value\\n        return safe_convert(self.input_value)\\n"}, "data_template": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Data Template", "dynamic": false, "info": "Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "data_template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "{text}"}, "input_value": {"_input_type": "MessageInput", "advanced": false, "display_name": "Inputs", "dynamic": false, "info": "Message to be passed as output.", "input_types": ["Data", "DataFrame", "Message"], "list": false, "load_from_db": false, "name": "input_value", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Machine"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "AI"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "type": "ChatOutput"}, "dragging": false, "height": 234, "id": "ChatOutput-mm3yo", "measured": {"height": 234, "width": 320}, "position": {"x": 2742.72534045604, "y": 681.9098282545469}, "positionAbsolute": {"x": 2742.72534045604, "y": 681.9098282545469}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"id": "note-tC1fr", "node": {"description": "# Image Sentiment Analysis\\nClassify images uploaded to the Playground by sentiment.\\n\\n## Prerequisites\\n\\n* [OpenAI API Key](https://platform.openai.com/)\\n\\n## Quickstart\\n\\n1. In the **Language Model** component, add your OpenAI API key.\\n\\n2. Open the **Playground**, and then submit an image to the chat. \\n\\nThe LLM analyzes the image. The sentiment is output into a structured table according to the **Structured Output** component's Output Schema, and then parsed into a message for the Playground to display.", "display_name": "", "documentation": "", "template": {}}, "type": "note"}, "dragging": false, "height": 583, "id": "note-tC1fr", "measured": {"height": 583, "width": 391}, "position": {"x": 636.4409835338676, "y": 119.16831706772064}, "positionAbsolute": {"x": 791.7294511578832, "y": 340.1333942936967}, "resizing": false, "selected": false, "style": {"height": 583, "width": 324}, "type": "noteNode", "width": 391}, {"data": {"description": "Create a prompt template with dynamic variables.", "display_name": "Prompt", "id": "Prompt-9gGBt", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {"template": []}, "description": "Create a prompt template with dynamic variables.", "display_name": "Prompt", "documentation": "", "edited": false, "field_order": ["template"], "frozen": false, "icon": "braces", "legacy": false, "lf_version": "1.4.3", "metadata": {}, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Prompt", "group_outputs": false, "method": "build_prompt", "name": "prompt", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.base.prompts.api_utils import process_prompt_template\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.inputs.inputs import DefaultPromptField\\nfrom langflow.io import MessageTextInput, Output, PromptInput\\nfrom langflow.schema.message import Message\\nfrom langflow.template.utils import update_template_values\\n\\n\\nclass PromptComponent(Component):\\n    display_name: str = \\"Prompt\\"\\n    description: str = \\"Create a prompt template with dynamic variables.\\"\\n    icon = \\"braces\\"\\n    trace_type = \\"prompt\\"\\n    name = \\"Prompt\\"\\n\\n    inputs = [\\n        PromptInput(name=\\"template\\", display_name=\\"Template\\"),\\n        MessageTextInput(\\n            name=\\"tool_placeholder\\",\\n            display_name=\\"Tool Placeholder\\",\\n            tool_mode=True,\\n            advanced=True,\\n            info=\\"A placeholder input for tool mode.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Prompt\\", name=\\"prompt\\", method=\\"build_prompt\\"),\\n    ]\\n\\n    async def build_prompt(self) -> Message:\\n        prompt = Message.from_template(**self._attributes)\\n        self.status = prompt.text\\n        return prompt\\n\\n    def _update_template(self, frontend_node: dict):\\n        prompt_template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        custom_fields = frontend_node[\\"custom_fields\\"]\\n        frontend_node_template = frontend_node[\\"template\\"]\\n        _ = process_prompt_template(\\n            template=prompt_template,\\n            name=\\"template\\",\\n            custom_fields=custom_fields,\\n            frontend_node_template=frontend_node_template,\\n        )\\n        return frontend_node\\n\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict):\\n        \\"\\"\\"This function is called after the code validation is done.\\"\\"\\"\\n        frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        # Kept it duplicated for backwards compatibility\\n        _ = process_prompt_template(\\n            template=template,\\n            name=\\"template\\",\\n            custom_fields=frontend_node[\\"custom_fields\\"],\\n            frontend_node_template=frontend_node[\\"template\\"],\\n        )\\n        # Now that template is updated, we need to grab any values that were set in the current_frontend_node\\n        # and update the frontend_node with those values\\n        update_template_values(new_template=frontend_node, previous_template=current_frontend_node[\\"template\\"])\\n        return frontend_node\\n\\n    def _get_fallback_input(self, **kwargs):\\n        return DefaultPromptField(**kwargs)\\n"}, "template": {"_input_type": "PromptInput", "advanced": false, "display_name": "Template", "dynamic": false, "info": "", "list": false, "load_from_db": false, "name": "template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "type": "prompt", "value": "Classify the image into neutral, negative or positive. "}, "tool_placeholder": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Tool Placeholder", "dynamic": false, "info": "A placeholder input for tool mode.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "tool_placeholder", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "type": "Prompt"}, "dragging": false, "height": 260, "id": "Prompt-9gGBt", "measured": {"height": 260, "width": 320}, "position": {"x": 1262.0179832573751, "y": 632.1360181124842}, "positionAbsolute": {"x": 1262.0179832573751, "y": 632.1360181124842}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"id": "StructuredOutput-93GZ3", "node": {"base_classes": ["Data"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Uses an LLM to generate structured data. Ideal for extraction and consistency.", "display_name": "Structured Output", "documentation": "", "edited": false, "field_order": ["llm", "input_value", "system_prompt", "schema_name", "output_schema"], "frozen": false, "icon": "braces", "legacy": false, "lf_version": "1.4.3", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Structured Output", "group_outputs": false, "method": "build_structured_output", "name": "structured_output", "selected": "Data", "tool_mode": true, "types": ["Data"], "value": "__UNDEFINED__"}, {"allows_loop": false, "cache": true, "display_name": "Structured Output", "group_outputs": false, "method": "build_structured_dataframe", "name": "dataframe_output", "selected": "DataFrame", "tool_mode": true, "types": ["DataFrame"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from pydantic import BaseModel, Field, create_model\\nfrom trustcall import create_extractor\\n\\nfrom langflow.base.models.chat_result import get_chat_result\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.helpers.base_model import build_model_from_schema\\nfrom langflow.io import (\\n    HandleInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n    TableInput,\\n)\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.table import EditMode\\n\\n\\nclass StructuredOutputComponent(Component):\\n    display_name = \\"Structured Output\\"\\n    description = \\"Uses an LLM to generate structured data. Ideal for extraction and consistency.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-processing#structured-output\\"\\n    name = \\"StructuredOutput\\"\\n    icon = \\"braces\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"llm\\",\\n            display_name=\\"Language Model\\",\\n            info=\\"The language model to use to generate the structured output.\\",\\n            input_types=[\\"LanguageModel\\"],\\n            required=True,\\n        ),\\n        MultilineInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input Message\\",\\n            info=\\"The input message to the language model.\\",\\n            tool_mode=True,\\n            required=True,\\n        ),\\n        MultilineInput(\\n            name=\\"system_prompt\\",\\n            display_name=\\"Format Instructions\\",\\n            info=\\"The instructions to the language model for formatting the output.\\",\\n            value=(\\n                \\"You are an AI that extracts structured JSON objects from unstructured text. \\"\\n                \\"Use a predefined schema with expected types (str, int, float, bool, dict). \\"\\n                \\"Extract ALL relevant instances that match the schema - if multiple patterns exist, capture them all. \\"\\n                \\"Fill missing or ambiguous values with defaults: null for missing values. \\"\\n                \\"Remove exact duplicates but keep variations that have different field values. \\"\\n                \\"Always return valid JSON in the expected format, never throw errors. \\"\\n                \\"If multiple objects can be extracted, return them all in the structured format.\\"\\n            ),\\n            required=True,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"schema_name\\",\\n            display_name=\\"Schema Name\\",\\n            info=\\"Provide a name for the output data schema.\\",\\n            advanced=True,\\n        ),\\n        TableInput(\\n            name=\\"output_schema\\",\\n            display_name=\\"Output Schema\\",\\n            info=\\"Define the structure and data types for the model's output.\\",\\n            required=True,\\n            # TODO: remove deault value\\n            table_schema=[\\n                {\\n                    \\"name\\": \\"name\\",\\n                    \\"display_name\\": \\"Name\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Specify the name of the output field.\\",\\n                    \\"default\\": \\"field\\",\\n                    \\"edit_mode\\": EditMode.INLINE,\\n                },\\n                {\\n                    \\"name\\": \\"description\\",\\n                    \\"display_name\\": \\"Description\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Describe the purpose of the output field.\\",\\n                    \\"default\\": \\"description of field\\",\\n                    \\"edit_mode\\": EditMode.POPOVER,\\n                },\\n                {\\n                    \\"name\\": \\"type\\",\\n                    \\"display_name\\": \\"Type\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"edit_mode\\": EditMode.INLINE,\\n                    \\"description\\": (\\"Indicate the data type of the output field (e.g., str, int, float, bool, dict).\\"),\\n                    \\"options\\": [\\"str\\", \\"int\\", \\"float\\", \\"bool\\", \\"dict\\"],\\n                    \\"default\\": \\"str\\",\\n                },\\n                {\\n                    \\"name\\": \\"multiple\\",\\n                    \\"display_name\\": \\"As List\\",\\n                    \\"type\\": \\"boolean\\",\\n                    \\"description\\": \\"Set to True if this output field should be a list of the specified type.\\",\\n                    \\"default\\": \\"False\\",\\n                    \\"edit_mode\\": EditMode.INLINE,\\n                },\\n            ],\\n            value=[\\n                {\\n                    \\"name\\": \\"field\\",\\n                    \\"description\\": \\"description of field\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"multiple\\": \\"False\\",\\n                }\\n            ],\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            name=\\"structured_output\\",\\n            display_name=\\"Structured Output\\",\\n            method=\\"build_structured_output\\",\\n        ),\\n        Output(\\n            name=\\"dataframe_output\\",\\n            display_name=\\"Structured Output\\",\\n            method=\\"build_structured_dataframe\\",\\n        ),\\n    ]\\n\\n    def build_structured_output_base(self):\\n        schema_name = self.schema_name or \\"OutputModel\\"\\n\\n        if not hasattr(self.llm, \\"with_structured_output\\"):\\n            msg = \\"Language model does not support structured output.\\"\\n            raise TypeError(msg)\\n        if not self.output_schema:\\n            msg = \\"Output schema cannot be empty\\"\\n            raise ValueError(msg)\\n\\n        output_model_ = build_model_from_schema(self.output_schema)\\n\\n        output_model = create_model(\\n            schema_name,\\n            __doc__=f\\"A list of {schema_name}.\\",\\n            objects=(list[output_model_], Field(description=f\\"A list of {schema_name}.\\")),  # type: ignore[valid-type]\\n        )\\n\\n        try:\\n            llm_with_structured_output = create_extractor(self.llm, tools=[output_model])\\n        except NotImplementedError as exc:\\n            msg = f\\"{self.llm.__class__.__name__} does not support structured output.\\"\\n            raise TypeError(msg) from exc\\n\\n        config_dict = {\\n            \\"run_name\\": self.display_name,\\n            \\"project_name\\": self.get_project_name(),\\n            \\"callbacks\\": self.get_langchain_callbacks(),\\n        }\\n        result = get_chat_result(\\n            runnable=llm_with_structured_output,\\n            system_message=self.system_prompt,\\n            input_value=self.input_value,\\n            config=config_dict,\\n        )\\n\\n        # OPTIMIZATION NOTE: Simplified processing based on trustcall response structure\\n        # Handle non-dict responses (shouldn't happen with trustcall, but defensive)\\n        if not isinstance(result, dict):\\n            return result\\n\\n        # Extract first response and convert BaseModel to dict\\n        responses = result.get(\\"responses\\", [])\\n        if not responses:\\n            return result\\n\\n        # Convert BaseModel to dict (creates the \\"objects\\" key)\\n        first_response = responses[0]\\n        structured_data = first_response.model_dump() if isinstance(first_response, BaseModel) else first_response\\n\\n        # Extract the objects array (guaranteed to exist due to our Pydantic model structure)\\n        return structured_data.get(\\"objects\\", structured_data)\\n\\n    def build_structured_output(self) -> Data:\\n        output = self.build_structured_output_base()\\n        if not isinstance(output, list) or not output:\\n            # handle empty or unexpected type case\\n            msg = \\"No structured output returned\\"\\n            raise ValueError(msg)\\n        if len(output) == 1:\\n            return Data(data=output[0])\\n        if len(output) > 1:\\n            # Multiple outputs - wrap them in a results container\\n            return Data(data={\\"results\\": output})\\n        return Data()\\n\\n    def build_structured_dataframe(self) -> DataFrame:\\n        output = self.build_structured_output_base()\\n        if not isinstance(output, list) or not output:\\n            # handle empty or unexpected type case\\n            msg = \\"No structured output returned\\"\\n            raise ValueError(msg)\\n        data_list = [Data(data=output[0])] if len(output) == 1 else [Data(data=item) for item in output]\\n\\n        return DataFrame(data_list)\\n"}, "input_value": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "Input Message", "dynamic": false, "info": "The input message to the language model.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "input_value", "placeholder": "", "required": true, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "llm": {"_input_type": "HandleInput", "advanced": false, "display_name": "Language Model", "dynamic": false, "info": "The language model to use to generate the structured output.", "input_types": ["LanguageModel"], "list": false, "list_add_label": "Add More", "name": "llm", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "output_schema": {"_input_type": "TableInput", "advanced": false, "display_name": "Output Schema", "dynamic": false, "info": "Define the structure and data types for the model's output.", "is_list": true, "list_add_label": "Add More", "load_from_db": false, "name": "output_schema", "placeholder": "", "required": true, "show": true, "table_icon": "Table", "table_schema": {"columns": [{"default": "field", "description": "Specify the name of the output field.", "disable_edit": false, "display_name": "Name", "edit_mode": "inline", "filterable": true, "formatter": "text", "hidden": false, "name": "name", "sortable": true, "type": "str"}, {"default": "description of field", "description": "Describe the purpose of the output field.", "disable_edit": false, "display_name": "Description", "edit_mode": "popover", "filterable": true, "formatter": "text", "hidden": false, "name": "description", "sortable": true, "type": "str"}, {"default": "str", "description": "Indicate the data type of the output field (e.g., str, int, float, bool, dict).", "disable_edit": false, "display_name": "Type", "edit_mode": "inline", "filterable": true, "formatter": "text", "hidden": false, "name": "type", "options": ["str", "int", "float", "bool", "dict"], "sortable": true, "type": "str"}, {"default": false, "description": "Set to True if this output field should be a list of the specified type.", "disable_edit": false, "display_name": "As List", "edit_mode": "inline", "filterable": true, "formatter": "boolean", "hidden": false, "name": "multiple", "sortable": true, "type": "boolean"}]}, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "trigger_icon": "Table", "trigger_text": "Open table", "type": "table", "value": [{"description": "A Positive|Negative value that represents the image.", "multiple": "False", "name": "sentiment", "type": "str"}, {"description": "Brief Description of the image", "multiple": false, "name": "description", "type": "str"}]}, "schema_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Schema Name", "dynamic": false, "info": "Provide a name for the output data schema.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "schema_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "system_prompt": {"_input_type": "MultilineInput", "advanced": true, "copy_field": false, "display_name": "Format Instructions", "dynamic": false, "info": "The instructions to the language model for formatting the output.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "system_prompt", "placeholder": "", "required": true, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "You are an AI that extracts structured JSON objects from unstructured text. Use a predefined schema with expected types (str, int, float, bool, dict). Extract ALL relevant instances that match the schema - if multiple patterns exist, capture them all. Fill missing or ambiguous values with defaults: null for missing values. Remove exact duplicates but keep variations that have different field values. Always return valid JSON in the expected format, never throw errors. If multiple objects can be extracted, return them all in the structured format."}}, "tool_mode": false}, "showNode": true, "type": "StructuredOutput"}, "dragging": false, "id": "StructuredOutput-93GZ3", "measured": {"height": 348, "width": 320}, "position": {"x": 2021.6355491355362, "y": 373.20069656111025}, "selected": false, "type": "genericNode"}, {"data": {"id": "parser-Z6kPy", "node": {"base_classes": ["Message"], "beta": false, "category": "processing", "conditional_paths": [], "custom_fields": {}, "description": "Format a DataFrame or Data object into text using a template. Enable 'Stringify' to convert input into a readable string instead.", "display_name": "Parser", "documentation": "", "edited": false, "field_order": ["mode", "pattern", "input_data", "sep"], "frozen": false, "icon": "braces", "key": "parser", "legacy": false, "lf_version": "1.4.3", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Parsed Text", "method": "parse_combined_text", "name": "parsed_text", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 2.220446049250313e-16, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import json\\nfrom typing import Any\\n\\nfrom langflow.custom import Component\\nfrom langflow.io import (\\n    BoolInput,\\n    HandleInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n    TabInput,\\n)\\nfrom langflow.schema import Data, DataFrame\\nfrom langflow.schema.message import Message\\n\\n\\nclass ParserComponent(Component):\\n    name = \\"parser\\"\\n    display_name = \\"Parser\\"\\n    description = (\\n        \\"Format a DataFrame or Data object into text using a template. \\"\\n        \\"Enable 'Stringify' to convert input into a readable string instead.\\"\\n    )\\n    icon = \\"braces\\"\\n\\n    inputs = [\\n        TabInput(\\n            name=\\"mode\\",\\n            display_name=\\"Mode\\",\\n            options=[\\"Parser\\", \\"Stringify\\"],\\n            value=\\"Parser\\",\\n            info=\\"Convert into raw string instead of using a template.\\",\\n            real_time_refresh=True,\\n        ),\\n        MultilineInput(\\n            name=\\"pattern\\",\\n            display_name=\\"Template\\",\\n            info=(\\n                \\"Use variables within curly brackets to extract column values for DataFrames \\"\\n                \\"or key values for Data.\\"\\n                \\"For example: `Name: {Name}, Age: {Age}, Country: {Country}`\\"\\n            ),\\n            value=\\"Text: {text}\\",  # Example default\\n            dynamic=True,\\n            show=True,\\n            required=True,\\n        ),\\n        HandleInput(\\n            name=\\"input_data\\",\\n            display_name=\\"Data or DataFrame\\",\\n            input_types=[\\"DataFrame\\", \\"Data\\"],\\n            info=\\"Accepts either a DataFrame or a Data object.\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sep\\",\\n            display_name=\\"Separator\\",\\n            advanced=True,\\n            value=\\"\\\\n\\",\\n            info=\\"String used to separate rows/items.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\"Parsed Text\\",\\n            name=\\"parsed_text\\",\\n            info=\\"Formatted text output.\\",\\n            method=\\"parse_combined_text\\",\\n        ),\\n    ]\\n\\n    def update_build_config(self, build_config, field_value, field_name=None):\\n        \\"\\"\\"Dynamically hide/show `template` and enforce requirement based on `stringify`.\\"\\"\\"\\n        if field_name == \\"mode\\":\\n            build_config[\\"pattern\\"][\\"show\\"] = self.mode == \\"Parser\\"\\n            build_config[\\"pattern\\"][\\"required\\"] = self.mode == \\"Parser\\"\\n            if field_value:\\n                clean_data = BoolInput(\\n                    name=\\"clean_data\\",\\n                    display_name=\\"Clean Data\\",\\n                    info=(\\n                        \\"Enable to clean the data by removing empty rows and lines \\"\\n                        \\"in each cell of the DataFrame/ Data object.\\"\\n                    ),\\n                    value=True,\\n                    advanced=True,\\n                    required=False,\\n                )\\n                build_config[\\"clean_data\\"] = clean_data.to_dict()\\n            else:\\n                build_config.pop(\\"clean_data\\", None)\\n\\n        return build_config\\n\\n    def _clean_args(self):\\n        \\"\\"\\"Prepare arguments based on input type.\\"\\"\\"\\n        input_data = self.input_data\\n\\n        match input_data:\\n            case list() if all(isinstance(item, Data) for item in input_data):\\n                msg = \\"List of Data objects is not supported.\\"\\n                raise ValueError(msg)\\n            case DataFrame():\\n                return input_data, None\\n            case Data():\\n                return None, input_data\\n            case dict() if \\"data\\" in input_data:\\n                try:\\n                    if \\"columns\\" in input_data:  # Likely a DataFrame\\n                        return DataFrame.from_dict(input_data), None\\n                    # Likely a Data object\\n                    return None, Data(**input_data)\\n                except (TypeError, ValueError, KeyError) as e:\\n                    msg = f\\"Invalid structured input provided: {e!s}\\"\\n                    raise ValueError(msg) from e\\n            case _:\\n                msg = f\\"Unsupported input type: {type(input_data)}. Expected DataFrame or Data.\\"\\n                raise ValueError(msg)\\n\\n    def parse_combined_text(self) -> Message:\\n        \\"\\"\\"Parse all rows/items into a single text or convert input to string if `stringify` is enabled.\\"\\"\\"\\n        # Early return for stringify option\\n        if self.mode == \\"Stringify\\":\\n            return self.convert_to_string()\\n\\n        df, data = self._clean_args()\\n\\n        lines = []\\n        if df is not None:\\n            for _, row in df.iterrows():\\n                formatted_text = self.pattern.format(**row.to_dict())\\n                lines.append(formatted_text)\\n        elif data is not None:\\n            formatted_text = self.pattern.format(**data.data)\\n            lines.append(formatted_text)\\n\\n        combined_text = self.sep.join(lines)\\n        self.status = combined_text\\n        return Message(text=combined_text)\\n\\n    def _safe_convert(self, data: Any) -> str:\\n        \\"\\"\\"Safely convert input data to string.\\"\\"\\"\\n        try:\\n            if isinstance(data, str):\\n                return data\\n            if isinstance(data, Message):\\n                return data.get_text()\\n            if isinstance(data, Data):\\n                return json.dumps(data.data)\\n            if isinstance(data, DataFrame):\\n                if hasattr(self, \\"clean_data\\") and self.clean_data:\\n                    # Remove empty rows\\n                    data = data.dropna(how=\\"all\\")\\n                    # Remove empty lines in each cell\\n                    data = data.replace(r\\"^\\\\s*$\\", \\"\\", regex=True)\\n                    # Replace multiple newlines with a single newline\\n                    data = data.replace(r\\"\\\\n+\\", \\"\\\\n\\", regex=True)\\n                return data.to_markdown(index=False)\\n            return str(data)\\n        except (ValueError, TypeError, AttributeError) as e:\\n            msg = f\\"Error converting data: {e!s}\\"\\n            raise ValueError(msg) from e\\n\\n    def convert_to_string(self) -> Message:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        result = \\"\\"\\n        if isinstance(self.input_data, list):\\n            result = \\"\\\\n\\".join([self._safe_convert(item) for item in self.input_data])\\n        else:\\n            result = self._safe_convert(self.input_data)\\n        self.log(f\\"Converted to string with length: {len(result)}\\")\\n\\n        message = Message(text=result)\\n        self.status = message\\n        return message\\n"}, "input_data": {"_input_type": "HandleInput", "advanced": false, "display_name": "Data or DataFrame", "dynamic": false, "info": "Accepts either a DataFrame or a Data object.", "input_types": ["DataFrame", "Data"], "list": false, "list_add_label": "Add More", "name": "input_data", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "mode": {"_input_type": "TabInput", "advanced": false, "display_name": "Mode", "dynamic": false, "info": "Convert into raw string instead of using a template.", "name": "mode", "options": ["Parser", "Stringify"], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tab", "value": "Parser"}, "pattern": {"_input_type": "MultilineInput", "advanced": false, "copy_field": false, "display_name": "Template", "dynamic": true, "info": "Use variables within curly brackets to extract column values for DataFrames or key values for Data.For example: `Name: {Name}, Age: {Age}, Country: {Country}`", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "pattern", "placeholder": "", "required": true, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "Sentiment: {sentiment}, Description: {description}"}, "sep": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Separator", "dynamic": false, "info": "String used to separate rows/items.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sep", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "\\n"}}, "tool_mode": false}, "showNode": true, "type": "parser"}, "dragging": false, "id": "parser-Z6kPy", "measured": {"height": 360, "width": 320}, "position": {"x": 2381.0436064002697, "y": 353.98212620918343}, "selected": false, "type": "genericNode"}, {"data": {"id": "LanguageModelComponent-t4Dhl", "node": {"base_classes": ["LanguageModel", "Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Runs a language model given a specified provider. ", "display_name": "Language Model", "documentation": "", "edited": false, "field_order": ["provider", "model_name", "api_key", "input_value", "system_message", "stream", "temperature"], "frozen": false, "icon": "brain-circuit", "legacy": false, "lf_version": "1.4.3", "metadata": {"keywords": ["model", "llm", "language model", "large language model"]}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Model Response", "group_outputs": false, "method": "text_response", "name": "text_output", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}, {"allows_loop": false, "cache": true, "display_name": "Language Model", "group_outputs": false, "method": "build_model", "name": "model_output", "selected": "LanguageModel", "tool_mode": true, "types": ["LanguageModel"], "value": "__UNDEFINED__"}], "pinned": false, "priority": 0, "template": {"_type": "Component", "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "OpenAI API Key", "dynamic": false, "info": "Model Provider API key", "input_types": [], "load_from_db": true, "name": "api_key", "password": true, "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "type": "str", "value": "OPENAI_API_KEY"}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from typing import Any\\n\\nfrom langchain_anthropic import ChatAnthropic\\nfrom langchain_google_genai import ChatGoogleGenerativeAI\\nfrom langchain_openai import ChatOpenAI\\n\\nfrom langflow.base.models.anthropic_constants import ANTHROPIC_MODELS\\nfrom langflow.base.models.google_generative_ai_constants import GOOGLE_GENERATIVE_AI_MODELS\\nfrom langflow.base.models.model import LCModelComponent\\nfrom langflow.base.models.openai_constants import OPENAI_CHAT_MODEL_NAMES, OPENAI_REASONING_MODEL_NAMES\\nfrom langflow.field_typing import LanguageModel\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.inputs.inputs import BoolInput\\nfrom langflow.io import DropdownInput, MessageInput, MultilineInput, SecretStrInput, SliderInput\\nfrom langflow.schema.dotdict import dotdict\\n\\n\\nclass LanguageModelComponent(LCModelComponent):\\n    display_name = \\"Language Model\\"\\n    description = \\"Runs a language model given a specified provider.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-models\\"\\n    icon = \\"brain-circuit\\"\\n    category = \\"models\\"\\n    priority = 0  # Set priority to 0 to make it appear first\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\"provider\\",\\n            display_name=\\"Model Provider\\",\\n            options=[\\"OpenAI\\", \\"Anthropic\\", \\"Google\\"],\\n            value=\\"OpenAI\\",\\n            info=\\"Select the model provider\\",\\n            real_time_refresh=True,\\n            options_metadata=[{\\"icon\\": \\"OpenAI\\"}, {\\"icon\\": \\"Anthropic\\"}, {\\"icon\\": \\"GoogleGenerativeAI\\"}],\\n        ),\\n        DropdownInput(\\n            name=\\"model_name\\",\\n            display_name=\\"Model Name\\",\\n            options=OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES,\\n            value=OPENAI_CHAT_MODEL_NAMES[0],\\n            info=\\"Select the model to use\\",\\n            real_time_refresh=True,\\n        ),\\n        SecretStrInput(\\n            name=\\"api_key\\",\\n            display_name=\\"OpenAI API Key\\",\\n            info=\\"Model Provider API key\\",\\n            required=False,\\n            show=True,\\n            real_time_refresh=True,\\n        ),\\n        MessageInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input\\",\\n            info=\\"The input text to send to the model\\",\\n        ),\\n        MultilineInput(\\n            name=\\"system_message\\",\\n            display_name=\\"System Message\\",\\n            info=\\"A system message that helps set the behavior of the assistant\\",\\n            advanced=False,\\n        ),\\n        BoolInput(\\n            name=\\"stream\\",\\n            display_name=\\"Stream\\",\\n            info=\\"Whether to stream the response\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n        SliderInput(\\n            name=\\"temperature\\",\\n            display_name=\\"Temperature\\",\\n            value=0.1,\\n            info=\\"Controls randomness in responses\\",\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:\\n        provider = self.provider\\n        model_name = self.model_name\\n        temperature = self.temperature\\n        stream = self.stream\\n\\n        if provider == \\"OpenAI\\":\\n            if not self.api_key:\\n                msg = \\"OpenAI API key is required when using OpenAI provider\\"\\n                raise ValueError(msg)\\n\\n            if model_name in OPENAI_REASONING_MODEL_NAMES:\\n                # reasoning models do not support temperature (yet)\\n                temperature = None\\n\\n            return ChatOpenAI(\\n                model_name=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                openai_api_key=self.api_key,\\n            )\\n        if provider == \\"Anthropic\\":\\n            if not self.api_key:\\n                msg = \\"Anthropic API key is required when using Anthropic provider\\"\\n                raise ValueError(msg)\\n            return ChatAnthropic(\\n                model=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                anthropic_api_key=self.api_key,\\n            )\\n        if provider == \\"Google\\":\\n            if not self.api_key:\\n                msg = \\"Google API key is required when using Google provider\\"\\n                raise ValueError(msg)\\n            return ChatGoogleGenerativeAI(\\n                model=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                google_api_key=self.api_key,\\n            )\\n        msg = f\\"Unknown provider: {provider}\\"\\n        raise ValueError(msg)\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:\\n        if field_name == \\"provider\\":\\n            if field_value == \\"OpenAI\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES\\n                build_config[\\"model_name\\"][\\"value\\"] = OPENAI_CHAT_MODEL_NAMES[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"OpenAI API Key\\"\\n            elif field_value == \\"Anthropic\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = ANTHROPIC_MODELS\\n                build_config[\\"model_name\\"][\\"value\\"] = ANTHROPIC_MODELS[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"Anthropic API Key\\"\\n            elif field_value == \\"Google\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = GOOGLE_GENERATIVE_AI_MODELS\\n                build_config[\\"model_name\\"][\\"value\\"] = GOOGLE_GENERATIVE_AI_MODELS[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"Google API Key\\"\\n        elif field_name == \\"model_name\\" and field_value.startswith(\\"o1\\") and self.provider == \\"OpenAI\\":\\n            # Hide system_message for o1 models - currently unsupported\\n            if \\"system_message\\" in build_config:\\n                build_config[\\"system_message\\"][\\"show\\"] = False\\n        elif field_name == \\"model_name\\" and not field_value.startswith(\\"o1\\") and \\"system_message\\" in build_config:\\n            build_config[\\"system_message\\"][\\"show\\"] = True\\n        return build_config\\n"}, "input_value": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "Input", "dynamic": false, "info": "The input text to send to the model", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "model_name": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Name", "dynamic": false, "info": "Select the model to use", "name": "model_name", "options": ["gpt-4o-mini", "gpt-4o", "gpt-4.1", "gpt-4.1-mini", "gpt-4.1-nano", "gpt-4.5-preview", "gpt-4-turbo", "gpt-4-turbo-preview", "gpt-4", "gpt-3.5-turbo"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "gpt-4o-mini"}, "provider": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Provider", "dynamic": false, "info": "Select the model provider", "name": "provider", "options": ["OpenAI", "Anthropic", "Google"], "options_metadata": [{"icon": "OpenAI"}, {"icon": "Anthropic"}, {"icon": "Google"}], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "OpenAI"}, "stream": {"_input_type": "BoolInput", "advanced": true, "display_name": "Stream", "dynamic": false, "info": "Whether to stream the response", "list": fal