data": true, "type": "str", "value": ""}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.base.data.utils import IMG_FILE_TYPES, TEXT_FILE_TYPES\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.inputs.inputs import BoolInput\\nfrom langflow.io import (\\n    DropdownInput,\\n    FileInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n)\\nfrom langflow.schema.message import Message\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_USER,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatInput(ChatComponent):\\n    display_name = \\"Chat Input\\"\\n    description = \\"Get chat inputs from the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-input\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatInput\\"\\n    minimized = True\\n\\n    inputs = [\\n        MultilineInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input Text\\",\\n            value=\\"\\",\\n            info=\\"Message to be passed as input.\\",\\n            input_types=[],\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_USER,\\n            info=\\"Type of sender.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_USER,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        FileInput(\\n            name=\\"files\\",\\n            display_name=\\"Files\\",\\n            file_types=TEXT_FILE_TYPES + IMG_FILE_TYPES,\\n            info=\\"Files to be sent with the message.\\",\\n            advanced=True,\\n            is_list=True,\\n            temp_file=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(display_name=\\"Chat Message\\", name=\\"message\\", method=\\"message_response\\"),\\n    ]\\n\\n    async def message_response(self) -> Message:\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        icon = self.chat_icon\\n\\n        message = await Message.create(\\n            text=self.input_value,\\n            sender=self.sender,\\n            sender_name=self.sender_name,\\n            session_id=self.session_id,\\n            files=self.files,\\n            properties={\\n                \\"background_color\\": background_color,\\n                \\"text_color\\": text_color,\\n                \\"icon\\": icon,\\n            },\\n        )\\n        if self.session_id and isinstance(message, Message) and self.should_store_message:\\n            stored_message = await self.send_message(\\n                message,\\n            )\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n"}, "files": {"_input_type": "FileInput", "advanced": true, "display_name": "Files", "dynamic": false, "fileTypes": ["txt", "md", "mdx", "csv", "json", "yaml", "yml", "xml", "html", "htm", "pdf", "docx", "py", "sh", "sql", "js", "ts", "tsx", "jpg", "jpeg", "png", "bmp", "image"], "file_path": "", "info": "Files to be sent with the message.", "list": true, "name": "files", "placeholder": "", "required": false, "show": true, "temp_file": true, "title_case": false, "trace_as_metadata": true, "type": "file", "value": ""}, "input_value": {"_input_type": "MultilineInput", "advanced": false, "display_name": "Input Text", "dynamic": false, "info": "Message to be passed as input.", "input_types": [], "list": false, "load_from_db": false, "multiline": true, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "Create a travel itinerary for a trip from S\\u00e3o Paulo to Uberl\\u00e2ndia, MG on August 23, 2024. The traveler enjoys drinking beer, eating p\\u00e3o de queijo, and drinking special coffee."}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "str", "value": "User"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "User"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}}, "selected_output": "message", "type": "ChatInput"}, "dragging": false, "height": 262, "id": "ChatInput-hRyEJ", "measured": {"height": 262, "width": 360}, "position": {"x": 1731.3224944651397, "y": 595.5715252590742}, "positionAbsolute": {"x": 1756.77096149088, "y": 292.73476765276695}, "selected": false, "type": "genericNode", "width": 360}, {"data": {"description": "Display a chat message in the Playground.", "display_name": "Chat Output", "id": "ChatOutput-TzFZY", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Display a chat message in the Playground.", "display_name": "Chat Output", "documentation": "", "edited": false, "field_order": ["input_value", "should_store_message", "sender", "sender_name", "session_id", "data_template", "background_color", "chat_icon", "text_color"], "frozen": false, "icon": "MessagesSquare", "legacy": false, "lf_version": "1.2.0", "metadata": {}, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Output Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "background_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Background Color", "dynamic": false, "info": "The background color of the icon.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "background_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "chat_icon": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "clean_data": {"_input_type": "BoolInput", "advanced": true, "display_name": "Basic Clean Data", "dynamic": false, "info": "Whether to clean the data", "list": false, "list_add_label": "Add More", "name": "clean_data", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from collections.abc import Generator\\nfrom typing import Any\\n\\nimport orjson\\nfrom fastapi.encoders import jsonable_encoder\\n\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.inputs.inputs import BoolInput, DropdownInput, HandleInput, MessageTextInput\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.schema.properties import Source\\nfrom langflow.template.field.base import Output\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_AI,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatOutput(ChatComponent):\\n    display_name = \\"Chat Output\\"\\n    description = \\"Display a chat message in the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-output\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatOutput\\"\\n    minimized = True\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Inputs\\",\\n            info=\\"Message to be passed as output.\\",\\n            input_types=[\\"Data\\", \\"DataFrame\\", \\"Message\\"],\\n            required=True,\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_AI,\\n            advanced=True,\\n            info=\\"Type of sender.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_AI,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"data_template\\",\\n            display_name=\\"Data Template\\",\\n            value=\\"{text}\\",\\n            advanced=True,\\n            info=\\"Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"clean_data\\",\\n            display_name=\\"Basic Clean Data\\",\\n            value=True,\\n            info=\\"Whether to clean the data\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\"Output Message\\",\\n            name=\\"message\\",\\n            method=\\"message_response\\",\\n        ),\\n    ]\\n\\n    def _build_source(self, id_: str | None, display_name: str | None, source: str | None) -> Source:\\n        source_dict = {}\\n        if id_:\\n            source_dict[\\"id\\"] = id_\\n        if display_name:\\n            source_dict[\\"display_name\\"] = display_name\\n        if source:\\n            # Handle case where source is a ChatOpenAI object\\n            if hasattr(source, \\"model_name\\"):\\n                source_dict[\\"source\\"] = source.model_name\\n            elif hasattr(source, \\"model\\"):\\n                source_dict[\\"source\\"] = str(source.model)\\n            else:\\n                source_dict[\\"source\\"] = str(source)\\n        return Source(**source_dict)\\n\\n    async def message_response(self) -> Message:\\n        # First convert the input to string if needed\\n        text = self.convert_to_string()\\n\\n        # Get source properties\\n        source, icon, display_name, source_id = self.get_properties_from_source_component()\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        if self.chat_icon:\\n            icon = self.chat_icon\\n\\n        # Create or use existing Message object\\n        if isinstance(self.input_value, Message):\\n            message = self.input_value\\n            # Update message properties\\n            message.text = text\\n        else:\\n            message = Message(text=text)\\n\\n        # Set message properties\\n        message.sender = self.sender\\n        message.sender_name = self.sender_name\\n        message.session_id = self.session_id\\n        message.flow_id = self.graph.flow_id if hasattr(self, \\"graph\\") else None\\n        message.properties.source = self._build_source(source_id, display_name, source)\\n        message.properties.icon = icon\\n        message.properties.background_color = background_color\\n        message.properties.text_color = text_color\\n\\n        # Store message if needed\\n        if self.session_id and self.should_store_message:\\n            stored_message = await self.send_message(message)\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n\\n    def _serialize_data(self, data: Data) -> str:\\n        \\"\\"\\"Serialize Data object to JSON string.\\"\\"\\"\\n        # Convert data.data to JSON-serializable format\\n        serializable_data = jsonable_encoder(data.data)\\n        # Serialize with orjson, enabling pretty printing with indentation\\n        json_bytes = orjson.dumps(serializable_data, option=orjson.OPT_INDENT_2)\\n        # Convert bytes to string and wrap in Markdown code blocks\\n        return \\"```json\\\\n\\" + json_bytes.decode(\\"utf-8\\") + \\"\\\\n```\\"\\n\\n    def _validate_input(self) -> None:\\n        \\"\\"\\"Validate the input data and raise ValueError if invalid.\\"\\"\\"\\n        if self.input_value is None:\\n            msg = \\"Input data cannot be None\\"\\n            raise ValueError(msg)\\n        if isinstance(self.input_value, list) and not all(\\n            isinstance(item, Message | Data | DataFrame | str) for item in self.input_value\\n        ):\\n            invalid_types = [\\n                type(item).__name__\\n                for item in self.input_value\\n                if not isinstance(item, Message | Data | DataFrame | str)\\n            ]\\n            msg = f\\"Expected Data or DataFrame or Message or str, got {invalid_types}\\"\\n            raise TypeError(msg)\\n        if not isinstance(\\n            self.input_value,\\n            Message | Data | DataFrame | str | list | Generator | type(None),\\n        ):\\n            type_name = type(self.input_value).__name__\\n            msg = f\\"Expected Data or DataFrame or Message or str, Generator or None, got {type_name}\\"\\n            raise TypeError(msg)\\n\\n    def convert_to_string(self) -> str | Generator[Any, None, None]:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        self._validate_input()\\n        if isinstance(self.input_value, list):\\n            return \\"\\\\n\\".join([safe_convert(item, clean_data=self.clean_data) for item in self.input_value])\\n        if isinstance(self.input_value, Generator):\\n            return self.input_value\\n        return safe_convert(self.input_value)\\n"}, "data_template": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Data Template", "dynamic": false, "info": "Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "data_template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "{text}"}, "input_value": {"_input_type": "MessageInput", "advanced": false, "display_name": "Inputs", "dynamic": false, "info": "Message to be passed as output.", "input_types": ["Data", "DataFrame", "Message"], "list": false, "load_from_db": false, "name": "input_value", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Machine"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "AI"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "type": "ChatOutput"}, "dragging": false, "height": 262, "id": "ChatOutput-TzFZY", "measured": {"height": 262, "width": 360}, "position": {"x": 4349.229697347143, "y": 620.5490494265098}, "positionAbsolute": {"x": 4349.229697347143, "y": 620.5490494265098}, "selected": false, "type": "genericNode", "width": 360}, {"data": {"id": "note-j1Nu2", "node": {"description": "# \\ud83d\\udcd6 README\\n\\nThe travel planning system is a smart setup that uses several specialized \\"agents\\" to help plan incredible trips. Imagine each agent as a travel expert focusing on a part of your journey. Here's how it works:\\n\\n## Quickstart\\n1. Add your **OpenAI API Key** to each Agent.\\n2. Add your **Search API** key to the Search API component.\\n2. Run the flow in the **Playground**.", "display_name": "", "documentation": "", "template": {}}, "type": "note"}, "dragging": false, "height": 453, "id": "note-j1Nu2", "measured": {"height": 453, "width": 371}, "position": {"x": 1708.5674196681368, "y": 75.74701473340798}, "positionAbsolute": {"x": 1076.3710803600266, "y": 92.06058855045646}, "resizing": false, "selected": false, "style": {"height": 636, "width": 324}, "type": "noteNode", "width": 371}, {"data": {"description": "Load and retrieve data from specified URLs. Supports output in plain text, raw HTML, or JSON, with options for cleaning and separating multiple outputs.", "display_name": "URL", "id": "URL-zTFcy", "node": {"base_classes": ["Data", "DataFrame", "Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Fetch content from one or more web pages, following links recursively.", "display_name": "URL", "documentation": "", "edited": false, "field_order": ["urls", "format", "separator", "clean_extra_whitespace"], "frozen": false, "icon": "layout-template", "legacy": false, "lf_version": "1.2.0", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Toolset", "group_outputs": false, "hidden": false, "method": "to_toolkit", "name": "component_as_tool", "options": null, "required_inputs": null, "selected": "Tool", "tool_mode": true, "types": ["Tool"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "autoset_encoding": {"_input_type": "BoolInput", "advanced": true, "display_name": "Autoset Encoding", "dynamic": false, "info": "If enabled, automatically sets the encoding of the request.", "list": false, "list_add_label": "Add More", "name": "autoset_encoding", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "check_response_status": {"_input_type": "BoolInput", "advanced": true, "display_name": "Check Response Status", "dynamic": false, "info": "If enabled, checks the response status of the request.", "list": false, "list_add_label": "Add More", "name": "check_response_status", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import re\\n\\nimport requests\\nfrom bs4 import BeautifulSoup\\nfrom langchain_community.document_loaders import RecursiveUrlLoader\\nfrom loguru import logger\\n\\nfrom langflow.custom import Component\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.io import BoolInput, DropdownInput, IntInput, MessageTextInput, Output, SliderInput, TableInput\\nfrom langflow.schema import DataFrame, Message\\nfrom langflow.services.deps import get_settings_service\\n\\n# Constants\\nDEFAULT_TIMEOUT = 30\\nDEFAULT_MAX_DEPTH = 1\\nDEFAULT_FORMAT = \\"Text\\"\\nURL_REGEX = re.compile(\\n    r\\"^(https?:\\\\/\\\\/)?\\" r\\"(www\\\\.)?\\" r\\"([a-zA-Z0-9.-]+)\\" r\\"(\\\\.[a-zA-Z]{2,})?\\" r\\"(:\\\\d+)?\\" r\\"(\\\\/[^\\\\s]*)?$\\",\\n    re.IGNORECASE,\\n)\\n\\n\\nclass URLComponent(Component):\\n    \\"\\"\\"A component that loads and parses content from web pages recursively.\\n\\n    This component allows fetching content from one or more URLs, with options to:\\n    - Control crawl depth\\n    - Prevent crawling outside the root domain\\n    - Use async loading for better performance\\n    - Extract either raw HTML or clean text\\n    - Configure request headers and timeouts\\n    \\"\\"\\"\\n\\n    display_name = \\"URL\\"\\n    description = \\"Fetch content from one or more web pages, following links recursively.\\"\\n    icon = \\"layout-template\\"\\n    name = \\"URLComponent\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\"urls\\",\\n            display_name=\\"URLs\\",\\n            info=\\"Enter one or more URLs to crawl recursively, by clicking the '+' button.\\",\\n            is_list=True,\\n            tool_mode=True,\\n            placeholder=\\"Enter a URL...\\",\\n            list_add_label=\\"Add URL\\",\\n            input_types=[],\\n        ),\\n        SliderInput(\\n            name=\\"max_depth\\",\\n            display_name=\\"Depth\\",\\n            info=(\\n                \\"Controls how many 'clicks' away from the initial page the crawler will go:\\\\n\\"\\n                \\"- depth 1: only the initial page\\\\n\\"\\n                \\"- depth 2: initial page + all pages linked directly from it\\\\n\\"\\n                \\"- depth 3: initial page + direct links + links found on those direct link pages\\\\n\\"\\n                \\"Note: This is about link traversal, not URL path depth.\\"\\n            ),\\n            value=DEFAULT_MAX_DEPTH,\\n            range_spec=RangeSpec(min=1, max=5, step=1),\\n            required=False,\\n            min_label=\\" \\",\\n            max_label=\\" \\",\\n            min_label_icon=\\"None\\",\\n            max_label_icon=\\"None\\",\\n            # slider_input=True\\n        ),\\n        BoolInput(\\n            name=\\"prevent_outside\\",\\n            display_name=\\"Prevent Outside\\",\\n            info=(\\n                \\"If enabled, only crawls URLs within the same domain as the root URL. \\"\\n                \\"This helps prevent the crawler from going to external websites.\\"\\n            ),\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"use_async\\",\\n            display_name=\\"Use Async\\",\\n            info=(\\n                \\"If enabled, uses asynchronous loading which can be significantly faster \\"\\n                \\"but might use more system resources.\\"\\n            ),\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"format\\",\\n            display_name=\\"Output Format\\",\\n            info=\\"Output Format. Use 'Text' to extract the text from the HTML or 'HTML' for the raw HTML content.\\",\\n            options=[\\"Text\\", \\"HTML\\"],\\n            value=DEFAULT_FORMAT,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\"timeout\\",\\n            display_name=\\"Timeout\\",\\n            info=\\"Timeout for the request in seconds.\\",\\n            value=DEFAULT_TIMEOUT,\\n            required=False,\\n            advanced=True,\\n        ),\\n        TableInput(\\n            name=\\"headers\\",\\n            display_name=\\"Headers\\",\\n            info=\\"The headers to send with the request\\",\\n            table_schema=[\\n                {\\n                    \\"name\\": \\"key\\",\\n                    \\"display_name\\": \\"Header\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Header name\\",\\n                },\\n                {\\n                    \\"name\\": \\"value\\",\\n                    \\"display_name\\": \\"Value\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Header value\\",\\n                },\\n            ],\\n            value=[{\\"key\\": \\"User-Agent\\", \\"value\\": get_settings_service().settings.user_agent}],\\n            advanced=True,\\n            input_types=[\\"DataFrame\\"],\\n        ),\\n        BoolInput(\\n            name=\\"filter_text_html\\",\\n            display_name=\\"Filter Text/HTML\\",\\n            info=\\"If enabled, filters out text/css content type from the results.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"continue_on_failure\\",\\n            display_name=\\"Continue on Failure\\",\\n            info=\\"If enabled, continues crawling even if some requests fail.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"check_response_status\\",\\n            display_name=\\"Check Response Status\\",\\n            info=\\"If enabled, checks the response status of the request.\\",\\n            value=False,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"autoset_encoding\\",\\n            display_name=\\"Autoset Encoding\\",\\n            info=\\"If enabled, automatically sets the encoding of the request.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Result\\", name=\\"page_results\\", method=\\"fetch_content\\"),\\n        Output(display_name=\\"Raw Result\\", name=\\"raw_results\\", method=\\"as_message\\"),\\n    ]\\n\\n    @staticmethod\\n    def validate_url(url: str) -> bool:\\n        \\"\\"\\"Validates if the given string matches URL pattern.\\n\\n        Args:\\n            url: The URL string to validate\\n\\n        Returns:\\n            bool: True if the URL is valid, False otherwise\\n        \\"\\"\\"\\n        return bool(URL_REGEX.match(url))\\n\\n    def ensure_url(self, url: str) -> str:\\n        \\"\\"\\"Ensures the given string is a valid URL.\\n\\n        Args:\\n            url: The URL string to validate and normalize\\n\\n        Returns:\\n            str: The normalized URL\\n\\n        Raises:\\n            ValueError: If the URL is invalid\\n        \\"\\"\\"\\n        url = url.strip()\\n        if not url.startswith((\\"http://\\", \\"https://\\")):\\n            url = \\"https://\\" + url\\n\\n        if not self.validate_url(url):\\n            msg = f\\"Invalid URL: {url}\\"\\n            raise ValueError(msg)\\n\\n        return url\\n\\n    def _create_loader(self, url: str) -> RecursiveUrlLoader:\\n        \\"\\"\\"Creates a RecursiveUrlLoader instance with the configured settings.\\n\\n        Args:\\n            url: The URL to load\\n\\n        Returns:\\n            RecursiveUrlLoader: Configured loader instance\\n        \\"\\"\\"\\n        headers_dict = {header[\\"key\\"]: header[\\"value\\"] for header in self.headers}\\n        extractor = (lambda x: x) if self.format == \\"HTML\\" else (lambda x: BeautifulSoup(x, \\"lxml\\").get_text())\\n\\n        return RecursiveUrlLoader(\\n            url=url,\\n            max_depth=self.max_depth,\\n            prevent_outside=self.prevent_outside,\\n            use_async=self.use_async,\\n            extractor=extractor,\\n            timeout=self.timeout,\\n            headers=headers_dict,\\n            check_response_status=self.check_response_status,\\n            continue_on_failure=self.continue_on_failure,\\n            base_url=url,  # Add base_url to ensure consistent domain crawling\\n            autoset_encoding=self.autoset_encoding,  # Enable automatic encoding detection\\n            exclude_dirs=[],  # Allow customization of excluded directories\\n            link_regex=None,  # Allow customization of link filtering\\n        )\\n\\n    def fetch_url_contents(self) -> list[dict]:\\n        \\"\\"\\"Load documents from the configured URLs.\\n\\n        Returns:\\n            List[Data]: List of Data objects containing the fetched content\\n\\n        Raises:\\n            ValueError: If no valid URLs are provided or if there's an error loading documents\\n        \\"\\"\\"\\n        try:\\n            urls = list({self.ensure_url(url) for url in self.urls if url.strip()})\\n            logger.info(f\\"URLs: {urls}\\")\\n            if not urls:\\n                msg = \\"No valid URLs provided.\\"\\n                raise ValueError(msg)\\n\\n            all_docs = []\\n            for url in urls:\\n                logger.info(f\\"Loading documents from {url}\\")\\n\\n                try:\\n                    loader = self._create_loader(url)\\n                    docs = loader.load()\\n\\n                    if not docs:\\n                        logger.warning(f\\"No documents found for {url}\\")\\n                        continue\\n\\n                    logger.info(f\\"Found {len(docs)} documents from {url}\\")\\n                    all_docs.extend(docs)\\n\\n                except requests.exceptions.RequestException as e:\\n                    logger.exception(f\\"Error loading documents from {url}: {e}\\")\\n                    continue\\n\\n            if not all_docs:\\n                msg = \\"No documents were successfully loaded from any URL\\"\\n                raise ValueError(msg)\\n\\n            # data = [Data(text=doc.page_content, **doc.metadata) for doc in all_docs]\\n            data = [\\n                {\\n                    \\"text\\": safe_convert(doc.page_content, clean_data=True),\\n                    \\"url\\": doc.metadata.get(\\"source\\", \\"\\"),\\n                    \\"title\\": doc.metadata.get(\\"title\\", \\"\\"),\\n                    \\"description\\": doc.metadata.get(\\"description\\", \\"\\"),\\n                    \\"content_type\\": doc.metadata.get(\\"content_type\\", \\"\\"),\\n                    \\"language\\": doc.metadata.get(\\"language\\", \\"\\"),\\n                }\\n                for doc in all_docs\\n            ]\\n        except Exception as e:\\n            error_msg = e.message if hasattr(e, \\"message\\") else e\\n            msg = f\\"Error loading documents: {error_msg!s}\\"\\n            logger.exception(msg)\\n            raise ValueError(msg) from e\\n        return data\\n\\n    def fetch_content(self) -> DataFrame:\\n        \\"\\"\\"Convert the documents to a DataFrame.\\"\\"\\"\\n        return DataFrame(data=self.fetch_url_contents())\\n\\n    def as_message(self) -> Message:\\n        \\"\\"\\"Convert the documents to a Message.\\"\\"\\"\\n        url_contents = self.fetch_url_contents()\\n        return Message(text=\\"\\\\n\\\\n\\".join([x[\\"text\\"] for x in url_contents]), data={\\"data\\": url_contents})\\n"}, "continue_on_failure": {"_input_type": "BoolInput", "advanced": true, "display_name": "Continue on Failure", "dynamic": false, "info": "If enabled, continues crawling even if some requests fail.", "list": false, "list_add_label": "Add More", "name": "continue_on_failure", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "filter_text_html": {"_input_type": "BoolInput", "advanced": true, "display_name": "Filter Text/HTML", "dynamic": false, "info": "If enabled, filters out text/css content type from the results.", "list": false, "list_add_label": "Add More", "name": "filter_text_html", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "format": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Output Format", "dynamic": false, "info": "Output Format. Use 'Text' to extract the text from the HTML or 'HTML' for the raw HTML content.", "name": "format", "options": ["Text", "HTML"], "options_metadata": [], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Text"}, "headers": {"_input_type": "TableInput", "advanced": true, "display_name": "Headers", "dynamic": false, "info": "The headers to send with the request", "input_types": ["DataFrame"], "is_list": true, "list_add_label": "Add More", "name": "headers", "placeholder": "", "required": false, "show": true, "table_icon": "Table", "table_schema": {"columns": [{"default": "None", "description": "Header name", "disable_edit": false, "display_name": "Header", "edit_mode": "popover", "filterable": true, "formatter": "text", "hidden": false, "name": "key", "sortable": true, "type": "str"}, {"default": "None", "description": "Header value", "disable_edit": false, "display_name": "Value", "edit_mode": "popover", "filterable": true, "formatter": "text", "hidden": false, "name": "value", "sortable": true, "type": "str"}]}, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "trigger_icon": "Table", "trigger_text": "Open table", "type": "table", "value": [{"key": "User-Agent", "value": "langflow"}]}, "max_depth": {"_input_type": "SliderInput", "advanced": false, "display_name": "Depth", "dynamic": false, "info": "Controls how many 'clicks' away from the initial page the crawler will go:\\n- depth 1: only the initial page\\n- depth 2: initial page + all pages linked directly from it\\n- depth 3: initial page + direct links + links found on those direct link pages\\nNote: This is about link traversal, not URL path depth.", "max_label": " ", "max_label_icon": "None", "min_label": " ", "min_label_icon": "None", "name": "max_depth", "placeholder": "", "range_spec": {"max": 5, "min": 1, "step": 1, "step_type": "float"}, "required": false, "show": true, "slider_buttons": false, "slider_buttons_options": [], "slider_input": false, "title_case": false, "tool_mode": false, "type": "slider", "value": 1}, "prevent_outside": {"_input_type": "BoolInput", "advanced": true, "display_name": "Prevent Outside", "dynamic": false, "info": "If enabled, only crawls URLs within the same domain as the root URL. This helps prevent the crawler from going to external websites.", "list": false, "list_add_label": "Add More", "name": "prevent_outside", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "timeout": {"_input_type": "IntInput", "advanced": true, "display_name": "Timeout", "dynamic": false, "info": "Timeout for the request in seconds.", "list": false, "list_add_label": "Add More", "name": "timeout", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 30}, "tools_metadata": {"_input_type": "ToolsInput", "advanced": false, "display_name": "Actions", "dynamic": false, "info": "Modify tool names and descriptions to help agents understand when to use each tool.", "is_list": true, "list_add_label": "Add More", "name": "tools_metadata", "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tools", "value": [{"args": {"urls": {"default": "", "description": "Enter one or more URLs to crawl recursively, by clicking the '+' button.", "items": {"type": "string"}, "title": "Urls", "type": "array"}}, "description": "Fetch content from one or more web pages, following links recursively.", "display_description": "Fetch content from one or more web pages, following links recursively.", "display_name": "fetch_content", "name": "fetch_content", "readonly": false, "status": true, "tags": ["fetch_content"]}, {"args": {"urls": {"default": "", "description": "Enter one or more URLs to crawl recursively, by clicking the '+' button.", "items": {"type": "string"}, "title": "Urls", "type": "array"}}, "description": "Fetch content from one or more web pages, following links recursively.", "display_description": "Fetch content from one or more web pages, following links recursively.", "display_name": "as_message", "name": "as_message", "readonly": false, "status": true, "tags": ["as_message"]}]}, "urls": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "URLs", "dynamic": false, "info": "Enter one or more URLs to crawl recursively, by clicking the '+' button.", "input_types": [], "list": true, "list_add_label": "Add URL", "load_from_db": false, "name": "urls", "placeholder": "Enter a URL...", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "use_async": {"_input_type": "BoolInput", "advanced": true, "display_name": "Use Async", "dynamic": false, "info": "If enabled, uses asynchronous loading which can be significantly faster but might use more system resources.", "list": false, "list_add_label": "Add More", "name": "use_async", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}}, "tool_mode": true}, "selected_output": "component_as_tool", "showNode": true, "type": "URL"}, "dragging": false, "id": "URL-zTFcy", "measured": {"height": 290, "width": 320}, "position": {"x": 2815.5187953791974, "y": 949.802524756467}, "selected": false, "type": "genericNode"}, {"data": {"id": "CalculatorComponent-FyfwW", "node": {"base_classes": ["Data"], "beta": false, "category": "tools", "conditional_paths": [], "custom_fields": {}, "description": "Perform basic arithmetic operations on a given expression.", "display_name": "Calculator", "documentation": "", "edited": false, "field_order": ["expression"], "frozen": false, "icon": "calculator", "key": "CalculatorComponent", "legacy": false, "lf_version": "1.2.0", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Toolset", "group_outputs": false, "hidden": false, "method": "to_toolkit", "name": "component_as_tool", "options": null, "required_inputs": null, "selected": "Tool", "tool_mode": true, "types": ["Tool"], "value": "__UNDEFINED__"}], "pinned": false, "score": 0.001, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import ast\\nimport operator\\nfrom collections.abc import Callable\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.inputs.inputs import MessageTextInput\\nfrom langflow.io import Output\\nfrom langflow.schema.data import Data\\n\\n\\nclass CalculatorComponent(Component):\\n    display_name = \\"Calculator\\"\\n    description = \\"Perform basic arithmetic operations on a given expression.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-helpers#calculator\\"\\n    icon = \\"calculator\\"\\n\\n    # Cache operators dictionary as a class variable\\n    OPERATORS: dict[type[ast.operator], Callable] = {\\n        ast.Add: operator.add,\\n        ast.Sub: operator.sub,\\n        ast.Mult: operator.mul,\\n        ast.Div: operator.truediv,\\n        ast.Pow: operator.pow,\\n    }\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\"expression\\",\\n            display_name=\\"Expression\\",\\n            info=\\"The arithmetic expression to evaluate (e.g., '4*4*(33/22)+12-20').\\",\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Data\\", name=\\"result\\", type_=Data, method=\\"evaluate_expression\\"),\\n    ]\\n\\n    def _eval_expr(self, node: ast.AST) -> float:\\n        \\"\\"\\"Evaluate an AST node recursively.\\"\\"\\"\\n        if isinstance(node, ast.Constant):\\n            if isinstance(node.value, int | float):\\n                return float(node.value)\\n            error_msg = f\\"Unsupported constant type: {type(node.value).__name__}\\"\\n            raise TypeError(error_msg)\\n        if isinstance(node, ast.Num):  # For backwards compatibility\\n            if isinstance(node.n, int | float):\\n                return float(node.n)\\n            error_msg = f\\"Unsupported number type: {type(node.n).__name__}\\"\\n            raise TypeError(error_msg)\\n\\n        if isinstance(node, ast.BinOp):\\n            op_type = type(node.op)\\n            if op_type not in self.OPERATORS:\\n                error_msg = f\\"Unsupported binary operator: {op_type.__name__}\\"\\n                raise TypeError(error_msg)\\n\\n            left = self._eval_expr(node.left)\\n            right = self._eval_expr(node.right)\\n            return self.OPERATORS[op_type](left, right)\\n\\n        error_msg = f\\"Unsupported operation or expression type: {type(node).__name__}\\"\\n        raise TypeError(error_msg)\\n\\n    def evaluate_expression(self) -> Data:\\n        \\"\\"\\"Evaluate the mathematical expression and return the result.\\"\\"\\"\\n        try:\\n            tree = ast.parse(self.expression, mode=\\"eval\\")\\n            result = self._eval_expr(tree.body)\\n\\n            formatted_result = f\\"{float(result):.6f}\\".rstrip(\\"0\\").rstrip(\\".\\")\\n            self.log(f\\"Calculation result: {formatted_result}\\")\\n\\n            self.status = formatted_result\\n            return Data(data={\\"result\\": formatted_result})\\n\\n        except ZeroDivisionError:\\n            error_message = \\"Error: Division by zero\\"\\n            self.status = error_message\\n            return Data(data={\\"error\\": error_message, \\"input\\": self.expression})\\n\\n        except (SyntaxError, TypeError, KeyError, ValueError, AttributeError, OverflowError) as e:\\n            error_message = f\\"Invalid expression: {e!s}\\"\\n            self.status = error_message\\n            return Data(data={\\"error\\": error_message, \\"input\\": self.expression})\\n\\n    def build(self):\\n        \\"\\"\\"Return the main evaluation function.\\"\\"\\"\\n        return self.evaluate_expression\\n"}, "expression": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "Expression", "dynamic": false, "info": "The arithmetic expression to evaluate (e.g., '4*4*(33/22)+12-20').", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "expression", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "tools_metadata": {"_input_type": "ToolsInput", "advanced": false, "display_name": "Actions", "dynamic": false, "info": "Modify tool names and descriptions to help agents understand when to use each tool.", "is_list": true, "list_add_label": "Add More", "name": "tools_metadata", "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tools", "value": [{"args": {"expression": {"default": "", "description": "The arithmetic expression to evaluate (e.g., '4*4*(33/22)+12-20').", "title": "Expression", "type": "string"}}, "description": "CalculatorComponent. evaluate_expression() - Perform basic arithmetic operations on a given expression.", "display_description": "CalculatorComponent. evaluate_expression() - Perform basic arithmetic operations on a given expression.", "display_name": "evaluate_expression", "name": "evaluate_expression", "status": true, "tags": ["evaluate_expression"]}]}}, "tool_mode": true}, "selected_output": "component_as_tool", "showNode": true, "type": "CalculatorComponent"}, "dragging": false, "id": "CalculatorComponent-FyfwW", "measured": {"height": 218, "width": 320}, "position": {"x": 3540.356346381247, "y": 989.3563951826354}, "selected": false, "type": "genericNode"}, {"data": {"description": "Call the searchapi.io API with result limiting", "display_name": "Search API", "id": "SearchComponent-mY1Fv", "node": {"base_classes": ["Data", "DataFrame", "Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Call the searchapi.io API with result limiting", "display_name": "Search API", "documentation": "https://www.searchapi.io/docs/google", "edited": false, "field_order": ["engine", "api_key", "input_value", "search_params", "max_results", "max_snippet_length"], "frozen": false, "icon": "SearchAPI", "legacy": false, "lf_version": "1.2.0", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Toolset", "group_outputs": false, "hidden": null, "method": "to_toolkit", "name": "component_as_tool", "options": null, "required_inputs": null, "selected": "Tool", "tool_mode": true, "types": ["Tool"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "SearchAPI API Key", "dynamic": false, "info": "", "input_types": [], "load_from_db": false, "name": "api_key", "password": true, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "str", "value": null}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from typing import Any\\n\\nfrom langchain_community.utilities.searchapi import SearchApiAPIWrapper\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.inputs.inputs import DictInput, DropdownInput, IntInput, MultilineInput, SecretStrInput\\nfrom langflow.io import Output\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\n\\n\\nclass SearchComponent(Component):\\n    display_name: str = \\"Search API\\"\\n    description: str = \\"Call the searchapi.io API with result limiting\\"\\n    documentation: str = \\"https://www.searchapi.io/docs/google\\"\\n    icon = \\"SearchAPI\\"\\n\\n    inputs = [\\n        DropdownInput(name=\\"engine\\", display_name=\\"Engine\\", value=\\"google\\", options=[\\"google\\", \\"bing\\", \\"duckduckgo\\"]),\\n        SecretStrInput(name=\\"api_key\\", display_name=\\"SearchAPI API Key\\", required=True),\\n        MultilineInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input\\",\\n            tool_mode=True,\\n        ),\\n        DictInput(name=\\"search_params\\", display_name=\\"Search parameters\\", advanced=True, is_list=True),\\n        IntInput(name=\\"max_results\\", display_name=\\"Max Results\\", value=5, advanced=True),\\n        IntInput(name=\\"max_snippet_length\\", display_name=\\"Max Snippet Length\\", value=100, advanced=True),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"DataFrame\\", name=\\"dataframe\\", method=\\"fetch_content_dataframe\\"),\\n    ]\\n\\n    def _build_wrapper(self):\\n        return SearchApiAPIWrapper(engine=self.engine, searchapi_api_key=self.api_key)\\n\\n    def run_model(self) -> DataFrame:\\n        return self.fetch_content_dataframe()\\n\\n    def fetch_content(self) -> list[Data]:\\n        wrapper = self._build_wrapper()\\n\\n        def search_func(\\n            query: str, params: dict[str, Any] | None = None, max_results: int = 5, max_snippet_length: int = 100\\n        ) -> list[Data]:\\n            params = params or {}\\n            full_results = wrapper.results(query=query, **params)\\n            organic_results = full_results.get(\\"organic_results\\", [])[:max_results]\\n\\n            return [\\n                Data(\\n                    text=result.get(\\"snippet\\", \\"\\"),\\n                    data={\\n                        \\"title\\": result.get(\\"title\\", \\"\\")[:max_snippet_length],\\n                        \\"link\\": result.get(\\"link\\", \\"\\"),\\n                        \\"snippet\\": result.get(\\"snippet\\", \\"\\")[:max_snippet_length],\\n                    },\\n                )\\n                for result in organic_results\\n            ]\\n\\n        results = search_func(\\n            self.input_value,\\n            self.search_params or {},\\n            self.max_results,\\n            self.max_snippet_length,\\n        )\\n        self.status = results\\n        return results\\n\\n    def fetch_content_dataframe(self) -> DataFrame:\\n        \\"\\"\\"Convert the search results to a DataFrame.\\n\\n        Returns:\\n            DataFrame: A DataFrame containing the search results.\\n        \\"\\"\\"\\n        data = self.fetch_content()\\n        return DataFrame(data)\\n"}, "engine": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Engine", "dynamic": false, "info": "", "name": "engine", "options": ["google", "bing", "duckduckgo"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "google"}, "input_value": {"_input_type": "MultilineInput", "advanced": false, "copy_field": false, "display_name": "Input", "dynamic": false, "info": "", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "max_results": {"_input_type": "IntInput", "advanced": true, "display_name": "Max Results", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "max_results", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 5}, "max_snippet_length": {"_input_type": "IntInput", "advanced": true, "display_name": "Max Snippet Length", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "max_snippet_length", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 100}, "search_params": {"_input_type": "DictInput", "advanced": true, "display_name": "Search parameters", "dynamic": false, "info": "", "list": true, "list_add_label": "Add More", "name": "search_params", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "type": "dict", "value": {}}, "tools_metadata": {"_input_type": "ToolsInput", "advanced": false, "display_name": "Actions", "dynamic": false, "info": "Modify tool names and descriptions to help agents understand when to use each tool.", "is_list": true, "list_add_label": "Add More", "name": "tools_metadata", "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tools", "value": [{"args": {"input_value": {"default": "", "description": "", "title": "Input Value", "type": "string"}}, "description": "Call the searchapi.io API with result limiting", "display_description": "Call the searchapi.io API with result limiting", "display_name": "fetch_content_dataframe", "name": "fetch_content_dataframe", "readonly": false, "status": true, "tags": ["fetch_content_dataframe"]}]}}, "tool_mode": true}, "selected_output": "component_as_tool", "showNode": true, "type": "SearchComponent"}, "dragging": false, "id": "SearchComponent-mY1Fv", "measured": {"height": 367, "width": 320}, "position": {"x": 2089.0393126914205, "y": 894.9349094163676}, "selected": false, "type": "genericNode"}, {"data": {"id": "Agent-RTpIN", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Define the agent's instructions, then enter a task to complete using tools.", "display_name": "City Selection Agent", "documentation": "", "edited": false, "field_order": ["agent_llm", "max_tokens", "model_kwargs", "json_mode", "model_name", "openai_api_base", "api_key", "temperature", "seed", "max_retries", "timeout", "system_prompt", "n_messages", "tools", "input_value", "handle_parsing_errors", "verbose", "max_iterations", "agent_description", "add_current_date_tool"], "frozen": false, "icon": "bot", "legacy": false, "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Response", "group_outputs": false, "hidden": null, "method": "message_response", "name": "response", "options": null, "required_inputs": null, "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "add_current_date_tool": {"_input_type": "BoolInput", "advanced": true, "display_name": "Current Date", "dynamic": false, "info": "If true, will add a tool to the agent that returns the current date.", "list": false, "list_add_label": "Add More", "name": "add_current_date_tool", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "agent_description": {"_input_type": "MultilineInput", "advanced": true, "copy_field": false, "display_name": "Agent Description [Deprecated]", "dynamic": false, "info": "The description of the agent. This is only used when in Tool Mode. Defaults to 'A helpful assistant with access to the following tools:' and tools are added dynamically. This feature is deprecated and will be removed in future versions.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "agent_description", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "A helpful assistant with access to the following tools:"}, "agent_llm": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Provider", "dynamic": false, "info": "The provider of the language model that the agent will use to generate responses.", "input_types": [], "name": "agent_llm", "options": ["Anthropic", "Google Generative AI", "Groq", "OpenAI", "Custom"], "options_metadata": [{"icon": "Anthropic"}, {"icon": "GoogleGenerativeAI"}, {"icon": "Groq"}, {"icon": "OpenAI"}, {"icon": "brain"}], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "OpenAI"}, "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "OpenAI API Key", "dynamic": false, "info": "The OpenAI API Key to use for the OpenAI model.", "input_types": [], "load_from_db": true, "name": "api_key", "password": true, "placeholder": "", "real_time_refresh": true, "required": true, "show": true, "title_case": false, "type": "str", "value": "OPENAI_API_KEY"}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langchain_core.tools import StructuredTool\\n\\nfrom langflow.base.agents.agent import LCToolsAgentComponent\\nfrom langflow.base.agents.events import ExceptionWithMessageError\\nfrom langflow.base.models.model_input_constants import (\\n    ALL_PROVIDER_FIELDS,\\n    MODEL_DYNAMIC_UPDATE_FIELDS,\\n    MODEL_PROVIDERS,\\n    MODEL_PROVIDERS_DICT,\\n    MODELS_METADATA,\\n)\\nfrom langflow.base.models.model_utils import get_model_name\\nfrom langflow.components.helpers.current_date import CurrentDateComponent\\nfrom langflow.components.helpers.memory import MemoryComponent\\nfrom langflow.components.langchain_utilities.tool_calling import ToolCallingAgentComponent\\nfrom langflow.custom.custom_component.component import _get_component_toolkit\\nfrom langflow.custom.utils import update_component_build_config\\nfrom langflow.field_typing import Tool\\nfrom langflow.io import BoolInput, DropdownInput, IntInput, MultilineInput, Output\\nfrom langflow.logging import logger\\nfrom langflow.schema.dotdict import dotdict\\nfrom langflow.schema.message import Message\\n\\n\\ndef set_advanced_true(component_input):\\n    component_input.advanced = True\\n    return component_input\\n\\n\\nMODEL_PROVIDERS_LIST = [\\"Anthropic\\", \\"Google Generative AI\\", \\"Groq\\", \\"OpenAI\\"]\\n\\n\\nclass AgentComponent(ToolCallingAgentComponent):\\n    display_name: str = \\"Agent\\"\\n    description: str = \\"Define the agent's instructions, then enter a task to complete using tools.\\"\\n    documentation: str = \\"https://docs.langflow.org/agents\\"\\n    icon = \\"bot\\"\\n    beta = False\\n    name = \\"Agent\\"\\n\\n    memory_inputs = [set_advanced_true(component_input) for component_input in MemoryComponent().inputs]\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\"agent_llm\\",\\n            display_name=\\"Model Provider\\",\\n            info=\\"The provider of the language model that the agent will use to generate responses.\\",\\n            options=[*MODEL_PROVIDERS_LIST, \\"Custom\\"],\\n            value=\\"OpenAI\\",\\n            real_time_refresh=True,\\n            input_types=[],\\n            options_metadata=[MODELS_METADATA[key] for key in MODEL_PROVIDERS_LIST] + [{\\"icon\\": \\"brain\\"}],\\n        ),\\n        *MODEL_PROVIDERS_DICT[\\"OpenAI\\"][\\"inputs\\"],\\n        MultilineInput(\\n            name=\\"system_prompt\\",\\n            display_name=\\"Agent Instructions\\",\\n            info=\\"System Prompt: Initial instructions and context provided to guide the agent's behavior.\\",\\n            value=\\"You are a helpful assistant that can use tools to answer questions and perform tasks.\\",\\n            advanced=False,\\n        ),\\n        IntInput(\\n            name=\\"n_messages\\",\\n            display_name=\\"Number of Chat History Messages\\",\\n            value=100,\\n            info=\\"Number of chat history messages to retrieve.\\",\\n            advanced=True,\\n            show=True,\\n        ),\\n        *LCToolsAgentComponent._base_inputs,\\n        # removed memory inputs from agent component\\n        # *memory_inputs,\\n        BoolInput(\\n            name=\\"add_current_date_tool\\",\\n            display_name=\\"Current Date\\",\\n            advanced=True,\\n            info=\\"If true, will add a tool to the agent that returns the current date.\\",\\n            value=True,\\n        ),\\n    ]\\n    outputs = [Output(name=\\"response\\", display_name=\\"Response\\", method=\\"message_response\\")]\\n\\n    async def message_response(self) -> Message:\\n        try:\\n            # Get LLM model and validate\\n            llm_model, display_name = self.get_llm()\\n            if llm_model is None:\\n                msg = \\"No language model selected. Please choose a model to proceed.\\"\\n                raise ValueError(msg)\\n            self.model_name = get_model_name(llm_model, display_name=display_name)\\n\\n            # Get memory data\\n            self.chat_history = await self.get_memory_data()\\n            if isinstance(self.chat_history, Message):\\n                self.chat_history = [self.chat_history]\\n\\n            # Add current date tool if enabled\\n            if self.add_current_date_tool:\\n                if not isinstance(self.tools, list):  # type: ignore[has-type]\\n                    self.tools = []\\n                current_date_tool = (await CurrentDateComponent(**self.get_base_args()).to_toolkit()).pop(0)\\n                if not isinstance(current_date_tool, StructuredTool):\\n                    msg = \\"CurrentDateComponent must be converted to a StructuredTool\\"\\n                    raise TypeError(msg)\\n                self.tools.append(current_date_tool)\\n            # note the tools are not required to run the agent, hence the validation removed.\\n\\n            # Set up and run agent\\n            self.set(\\n                llm=llm_model,\\n                tools=self.tools or [],\\n                chat_history=self.chat_history,\\n                input_value=self.input_value,\\n                system_prompt=self.system_prompt,\\n            )\\n            agent = self.create_agent_runnable()\\n            return await self.run_agent(agent)\\n\\n        except (ValueError, TypeError, KeyError) as e:\\n            logger.error(f\\"{type(e).__name__}: {e!s}\\")\\n            raise\\n        except ExceptionWithMessageError as e:\\n            logger.error(f\\"ExceptionWithMessageError occurred: {e}\\")\\n            raise\\n        except Exception as e:\\n            logger.error(f\\"Unexpected error: {e!s}\\")\\n            raise\\n\\n    async def get_memory_data(self):\\n        # TODO: This is a temporary fix to avoid message duplication. We should develop a function for this.\\n        messages = (\\n            await MemoryComponent(**self.get_base_args())\\n            .set(session_id=self.graph.session_id, order=\\"Ascending\\", n_messages=self.n_messages)\\n            .retrieve_messages()\\n        )\\n        return [\\n            message for message in messages if getattr(message, \\"id\\", None) != getattr(self.input_value, \\"id\\", None)\\n        ]\\n\\n    def get_llm(self):\\n        if not isinstance(self.agent_llm, str):\\n            return self.agent_llm, None\\n\\n        try:\\n            provider_info = MODEL_PROVIDERS_DICT.get(self.agent_llm)\\n            if not provider_info:\\n                msg = f\\"Invalid model provider: {self.agent_llm}\\"\\n                raise ValueError(msg)\\n\\n            component_class = provider_info.get(\\"component_class\\")\\n            display_name = component_class.display_name\\n            inputs = provider_info.get(\\"inputs\\")\\n            prefix = provider_info.get(\\"prefix\\", \\"\\")\\n\\n            return self._build_llm_model(component_class, inputs, prefix), display_name\\n\\n        except Exception as e:\\n            logger.error(f\\"Error building {self.agent_llm} language model: {e!s}\\")\\n            msg = f\\"Failed to initialize language model: {e!s}\\"\\n            raise ValueError(msg) from e\\n\\n    def _build_llm_model(self, component, inputs, prefix=\\"\\"):\\n        model_kwargs = {}\\n        for input_ in inputs:\\n            if hasattr(self, f\\"{prefix}{input_.name}\\"):\\n                model_kwargs[input_.name] = getattr(self, f\\"{prefix}{input_.name}\\")\\n        return component.set(**model_kwargs).build_model()\\n\\n    def set_component_params(self, component):\\n        provider_info = MODEL_PROVIDERS_DICT.get(self.agent_llm)\\n        if provider_info:\\n            inputs = provider_info.get(\\"inputs\\")\\n            prefix = provider_info.get(\\"prefix\\")\\n            model_kwargs = {input_.name: getattr(self, f\\"{prefix}{input_.name}\\") for input_ in inputs}\\n\\n            return component.set(**model_kwargs)\\n        return component\\n\\n    def delete_fields(self, build_config: dotdict, fields: dict | list[str]) -> None:\\n        \\"\\"\\"Delete specified fields from build_config.\\"\\"\\"\\n        for field in fields:\\n            build_config.pop(field, None)\\n\\n    def update_input_types(self, build_config: dotdict) -> dotdict:\\n        \\"\\"\\"Update input types for all fields in build_config.\\"\\"\\"\\n        for key, value in build_config.items():\\n            if isinstance(value, dict):\\n                if value.get(\\"input_types\\") is None:\\n                    build_config[key][\\"input_types\\"] = []\\n            elif hasattr(value, \\"input_types\\") and value.input_types is None:\\n                value.input_types = []\\n        return build_config\\n\\n    async def update_build_config(\\n        self, build_config: dotdict, field_value: str, field_name: str | None = None\\n    ) -> dotdict:\\n        # Iterate over all providers in the MODEL_PROVIDERS_DICT\\n        # Existing logic for updating build_config\\n        if field_name in (\\"agent_llm\\",):\\n            build_config[\\"agent_llm\\"][\\"value\\"] = field_value\\n            provider_info = MODEL_PROVIDERS_DICT.get(field_value)\\n            if provider_info:\\n                component_class = provider_info.get(\\"component_class\\")\\n                if component_class and hasattr(component_class, \\"update_build_config\\"):\\n                    # Call the component class's update_build_config method\\n                    build_config = await update_component_build_config(\\n                        component_class, build_config, field_value, \\"model_name\\"\\n                    )\\n\\n            provider_configs: dict[str, tuple[dict, list[dict]]] = {\\n                provider: (\\n                    MODEL_PROVIDERS_DICT[provider][\\"fields\\"],\\n                    [\\n                        MODEL_PROVIDERS_DICT[other_provider][\\"fields\\"]\\n                        for other_provider in MODEL_PROVIDERS_DICT\\n                        if other_provider != provider\\n                    ],\\n                )\\n                for provider in MODEL_PROVIDERS_DICT\\n            }\\n            if field_value in provider_configs:\\n                fields_to_add, fields_to_delete = provider_configs[field_value]\\n\\n                # Delete fields from other providers\\n                for fields in fields_to_delete:\\n                    self.delete_fields(build_config, fields)\\n\\n                # Add provider-specific fields\\n                if field_value == \\"OpenAI\\" and not any(field in build_config for field in fields_to_add):\\n                    build_config.update(fields_to_add)\\n                else:\\n                    build_config.update(fields_to_add)\\n                # Reset input types for agent_llm\\n                build_config[\\"agent_llm\\"][\\"input_types\\"] = []\\n            elif field_value == \\"Custom\\":\\n                # Delete all provider fields\\n                self.delete_fields(build_config, ALL_PROVIDER_FIELDS)\\n                # Update with custom component\\n                custom_component = DropdownInput(\\n                    name=\\"agent_llm\\",\\n                    display_name=\\"Language Model\\",\\n                    options=[*sorted(MODEL_PROVIDERS), \\"Custom\\"],\\n                    value=\\"Custom\\",\\n                    real_time_refresh=True,\\n                    input_types=[\\"LanguageModel\\"],\\n                    options_metadata=[MODELS_METADATA[key] for key in sorted(MODELS_METADATA.keys())]\\n                    + [{\\"icon\\": \\"brain\\"}],\\n                )\\n                build_config.update({\\"agent_llm\\": custom_component.to_dict()})\\n            # Update input types for all fields\\n            build_config = self.update_input_types(build_config)\\n\\n            # Validate required keys\\n            default_keys = [\\n                \\"code\\",\\n                \\"_type\\",\\n                \\"agent_llm\\",\\n                \\"tools\\",\\n                \\"input_value\\",\\n                \\"add_current_date_tool\\",\\n                \\"system_prompt\\",\\n                \\"agent_description\\",\\n                \\"max_iterations\\",\\n                \\"handle_parsing_errors\\",\\n                \\"verbose\\",\\n            ]\\n            missing_keys = [key for key in default_keys if key not in build_config]\\n            if missing_keys:\\n                msg = f\\"Missing required keys in build_config: {missing_keys}\\"\\n                raise ValueError(msg)\\n        if (\\n            isinstance(self.agent_llm, str)\\n            and self.agent_llm in MODEL_PROVIDERS_DICT\\n            and field_name in MODEL_DYNAMIC_UPDATE_FIELDS\\n        ):\\n            provider_info = MODEL_PROVIDERS_DICT.get(self.agent_llm)\\n            if provider_info:\\n                component_class = provider_info.get(\\"component_class\\")\\n                component_class = self.set_component_params(component_class)\\n                prefix = provider_info.get(\\"prefix\\")\\n                if component_class and hasattr(component_class, \\"update_build_config\\"):\\n                    # Call each component class's update_build_config method\\n                    # remove the prefix from the field_name\\n                    if isinstance(field_name, str) and isinstance(prefix, str):\\n                        field_name = field_name.replace(prefix, \\"\\")\\n                    build_config = await update_component_build_config(\\n                        component_class, build_config, field_value, \\"model_name\\"\\n                    )\\n        return dotdict({k: v.to_dict() if hasattr(v, \\"to_dict\\") else v for k, v in build_config.items()})\\n\\n    async def _get_tools(self) -> list[Tool]:\\n        component_toolkit = _get_component_toolkit()\\n        tools_names = self._build_tools_names()\\n        agent_description = self.get_tool_description()\\n        # TODO: Agent Description Depreciated Feature to be removed\\n        description = f\\"{agent_description}{tools_names}\\"\\n        tools = component_toolkit(component=self).get_tools(\\n            tool_name=\\"Call_Agent\\", tool_description=description, callbacks=self.get_langchain_callbacks()\\n        )\\n        if hasattr(self, \\"tools_metadata\\"):\\n            tools = component_toolkit(component=self, metadata=self.tools_metadata).update_tools_metadata(tools=tools)\\n        return tools\\n"}, "handle_parsing_errors": {"_input_type": "BoolInput", "advanced": true, "display_name": "Handle Parse Errors", "dynamic": false, "info": "Should the Agent fix errors when reading user input for better processing?", "list": false, "list_add_label": "Add More", "name": "handle_parsing_errors", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "input_value": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "Input", "dynamic": false, "info": "The input provided by the user for the agent to process.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "json_mode": {"_input_type": "BoolInput", "advanced": true, "display_name": "JSON Mode", "dynamic": false, "info": "If True, it will output JSON regardless of passing a schema.", "list": false, "list_add_label": "Add More", "name": "json_mode", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "max_iterations": {"_input_type": "IntInput", "advanced": true, "display_name": "Max Iterations", "dynamic": false, "info": "The maximum number of attempts the agent can make to complete its task before it stops.", "list": false, "list_add_label": "Add More", "name": "max_iterations", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 15}, "max_retries": {"_input_type": "IntInput", "advanced": true, "display_name": "Max Retries", "dynamic": false, "info": "The maximum number of retries to make when generating.", "list": false, "list_add_label": "Add More", "name": "max_retries", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_