lse, "show": true, "slider_buttons": false, "slider_buttons_options": [], "slider_input": false, "title_case": false, "tool_mode": false, "type": "slider", "value": 0.1}, "timeout": {"_input_type": "IntInput", "advanced": true, "display_name": "Timeout", "dynamic": false, "info": "The timeout for requests to OpenAI completion API.", "list": false, "list_add_label": "Add More", "name": "timeout", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 700}, "tools": {"_input_type": "HandleInput", "advanced": false, "display_name": "Tools", "dynamic": false, "info": "These are the tools that the agent can use to help with tasks.", "input_types": ["Tool"], "list": true, "list_add_label": "Add More", "name": "tools", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "verbose": {"_input_type": "BoolInput", "advanced": true, "display_name": "Verbose", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "verbose", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}}, "tool_mode": false}, "selected_output": "response", "showNode": true, "type": "Agent"}, "dragging": false, "id": "Agent-9tDeE", "measured": {"height": 594, "width": 320}, "position": {"x": 3168.5639981397626, "y": 342.7862450828752}, "selected": false, "type": "genericNode"}, {"data": {"id": "Agent-C8zRS", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Define the agent's instructions, then enter a task to complete using tools.", "display_name": "Travel Concierge Agent", "documentation": "", "edited": false, "field_order": ["agent_llm", "max_tokens", "model_kwargs", "json_mode", "model_name", "openai_api_base", "api_key", "temperature", "seed", "max_retries", "timeout", "system_prompt", "n_messages", "tools", "input_value", "handle_parsing_errors", "verbose", "max_iterations", "agent_description", "add_current_date_tool"], "frozen": false, "icon": "bot", "legacy": false, "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Response", "group_outputs": false, "hidden": null, "method": "message_response", "name": "response", "options": null, "required_inputs": null, "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "add_current_date_tool": {"_input_type": "BoolInput", "advanced": true, "display_name": "Current Date", "dynamic": false, "info": "If true, will add a tool to the agent that returns the current date.", "list": false, "list_add_label": "Add More", "name": "add_current_date_tool", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "agent_description": {"_input_type": "MultilineInput", "advanced": true, "copy_field": false, "display_name": "Agent Description [Deprecated]", "dynamic": false, "info": "The description of the agent. This is only used when in Tool Mode. Defaults to 'A helpful assistant with access to the following tools:' and tools are added dynamically. This feature is deprecated and will be removed in future versions.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "agent_description", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "A helpful assistant with access to the following tools:"}, "agent_llm": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Provider", "dynamic": false, "info": "The provider of the language model that the agent will use to generate responses.", "input_types": [], "name": "agent_llm", "options": ["Anthropic", "Google Generative AI", "Groq", "OpenAI", "Custom"], "options_metadata": [{"icon": "Anthropic"}, {"icon": "GoogleGenerativeAI"}, {"icon": "Groq"}, {"icon": "OpenAI"}, {"icon": "brain"}], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "OpenAI"}, "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "OpenAI API Key", "dynamic": false, "info": "The OpenAI API Key to use for the OpenAI model.", "input_types": [], "load_from_db": true, "name": "api_key", "password": true, "placeholder": "", "real_time_refresh": true, "required": true, "show": true, "title_case": false, "type": "str", "value": "OPENAI_API_KEY"}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langchain_core.tools import StructuredTool\\n\\nfrom langflow.base.agents.agent import LCToolsAgentComponent\\nfrom langflow.base.agents.events import ExceptionWithMessageError\\nfrom langflow.base.models.model_input_constants import (\\n    ALL_PROVIDER_FIELDS,\\n    MODEL_DYNAMIC_UPDATE_FIELDS,\\n    MODEL_PROVIDERS,\\n    MODEL_PROVIDERS_DICT,\\n    MODELS_METADATA,\\n)\\nfrom langflow.base.models.model_utils import get_model_name\\nfrom langflow.components.helpers.current_date import CurrentDateComponent\\nfrom langflow.components.helpers.memory import MemoryComponent\\nfrom langflow.components.langchain_utilities.tool_calling import ToolCallingAgentComponent\\nfrom langflow.custom.custom_component.component import _get_component_toolkit\\nfrom langflow.custom.utils import update_component_build_config\\nfrom langflow.field_typing import Tool\\nfrom langflow.io import BoolInput, DropdownInput, IntInput, MultilineInput, Output\\nfrom langflow.logging import logger\\nfrom langflow.schema.dotdict import dotdict\\nfrom langflow.schema.message import Message\\n\\n\\ndef set_advanced_true(component_input):\\n    component_input.advanced = True\\n    return component_input\\n\\n\\nMODEL_PROVIDERS_LIST = [\\"Anthropic\\", \\"Google Generative AI\\", \\"Groq\\", \\"OpenAI\\"]\\n\\n\\nclass AgentComponent(ToolCallingAgentComponent):\\n    display_name: str = \\"Agent\\"\\n    description: str = \\"Define the agent's instructions, then enter a task to complete using tools.\\"\\n    documentation: str = \\"https://docs.langflow.org/agents\\"\\n    icon = \\"bot\\"\\n    beta = False\\n    name = \\"Agent\\"\\n\\n    memory_inputs = [set_advanced_true(component_input) for component_input in MemoryComponent().inputs]\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\"agent_llm\\",\\n            display_name=\\"Model Provider\\",\\n            info=\\"The provider of the language model that the agent will use to generate responses.\\",\\n            options=[*MODEL_PROVIDERS_LIST, \\"Custom\\"],\\n            value=\\"OpenAI\\",\\n            real_time_refresh=True,\\n            input_types=[],\\n            options_metadata=[MODELS_METADATA[key] for key in MODEL_PROVIDERS_LIST] + [{\\"icon\\": \\"brain\\"}],\\n        ),\\n        *MODEL_PROVIDERS_DICT[\\"OpenAI\\"][\\"inputs\\"],\\n        MultilineInput(\\n            name=\\"system_prompt\\",\\n            display_name=\\"Agent Instructions\\",\\n            info=\\"System Prompt: Initial instructions and context provided to guide the agent's behavior.\\",\\n            value=\\"You are a helpful assistant that can use tools to answer questions and perform tasks.\\",\\n            advanced=False,\\n        ),\\n        IntInput(\\n            name=\\"n_messages\\",\\n            display_name=\\"Number of Chat History Messages\\",\\n            value=100,\\n            info=\\"Number of chat history messages to retrieve.\\",\\n            advanced=True,\\n            show=True,\\n        ),\\n        *LCToolsAgentComponent._base_inputs,\\n        # removed memory inputs from agent component\\n        # *memory_inputs,\\n        BoolInput(\\n            name=\\"add_current_date_tool\\",\\n            display_name=\\"Current Date\\",\\n            advanced=True,\\n            info=\\"If true, will add a tool to the agent that returns the current date.\\",\\n            value=True,\\n        ),\\n    ]\\n    outputs = [Output(name=\\"response\\", display_name=\\"Response\\", method=\\"message_response\\")]\\n\\n    async def message_response(self) -> Message:\\n        try:\\n            # Get LLM model and validate\\n            llm_model, display_name = self.get_llm()\\n            if llm_model is None:\\n                msg = \\"No language model selected. Please choose a model to proceed.\\"\\n                raise ValueError(msg)\\n            self.model_name = get_model_name(llm_model, display_name=display_name)\\n\\n            # Get memory data\\n            self.chat_history = await self.get_memory_data()\\n            if isinstance(self.chat_history, Message):\\n                self.chat_history = [self.chat_history]\\n\\n            # Add current date tool if enabled\\n            if self.add_current_date_tool:\\n                if not isinstance(self.tools, list):  # type: ignore[has-type]\\n                    self.tools = []\\n                current_date_tool = (await CurrentDateComponent(**self.get_base_args()).to_toolkit()).pop(0)\\n                if not isinstance(current_date_tool, StructuredTool):\\n                    msg = \\"CurrentDateComponent must be converted to a StructuredTool\\"\\n                    raise TypeError(msg)\\n                self.tools.append(current_date_tool)\\n            # note the tools are not required to run the agent, hence the validation removed.\\n\\n            # Set up and run agent\\n            self.set(\\n                llm=llm_model,\\n                tools=self.tools or [],\\n                chat_history=self.chat_history,\\n                input_value=self.input_value,\\n                system_prompt=self.system_prompt,\\n            )\\n            agent = self.create_agent_runnable()\\n            return await self.run_agent(agent)\\n\\n        except (ValueError, TypeError, KeyError) as e:\\n            logger.error(f\\"{type(e).__name__}: {e!s}\\")\\n            raise\\n        except ExceptionWithMessageError as e:\\n            logger.error(f\\"ExceptionWithMessageError occurred: {e}\\")\\n            raise\\n        except Exception as e:\\n            logger.error(f\\"Unexpected error: {e!s}\\")\\n            raise\\n\\n    async def get_memory_data(self):\\n        # TODO: This is a temporary fix to avoid message duplication. We should develop a function for this.\\n        messages = (\\n            await MemoryComponent(**self.get_base_args())\\n            .set(session_id=self.graph.session_id, order=\\"Ascending\\", n_messages=self.n_messages)\\n            .retrieve_messages()\\n        )\\n        return [\\n            message for message in messages if getattr(message, \\"id\\", None) != getattr(self.input_value, \\"id\\", None)\\n        ]\\n\\n    def get_llm(self):\\n        if not isinstance(self.agent_llm, str):\\n            return self.agent_llm, None\\n\\n        try:\\n            provider_info = MODEL_PROVIDERS_DICT.get(self.agent_llm)\\n            if not provider_info:\\n                msg = f\\"Invalid model provider: {self.agent_llm}\\"\\n                raise ValueError(msg)\\n\\n            component_class = provider_info.get(\\"component_class\\")\\n            display_name = component_class.display_name\\n            inputs = provider_info.get(\\"inputs\\")\\n            prefix = provider_info.get(\\"prefix\\", \\"\\")\\n\\n            return self._build_llm_model(component_class, inputs, prefix), display_name\\n\\n        except Exception as e:\\n            logger.error(f\\"Error building {self.agent_llm} language model: {e!s}\\")\\n            msg = f\\"Failed to initialize language model: {e!s}\\"\\n            raise ValueError(msg) from e\\n\\n    def _build_llm_model(self, component, inputs, prefix=\\"\\"):\\n        model_kwargs = {}\\n        for input_ in inputs:\\n            if hasattr(self, f\\"{prefix}{input_.name}\\"):\\n                model_kwargs[input_.name] = getattr(self, f\\"{prefix}{input_.name}\\")\\n        return component.set(**model_kwargs).build_model()\\n\\n    def set_component_params(self, component):\\n        provider_info = MODEL_PROVIDERS_DICT.get(self.agent_llm)\\n        if provider_info:\\n            inputs = provider_info.get(\\"inputs\\")\\n            prefix = provider_info.get(\\"prefix\\")\\n            model_kwargs = {input_.name: getattr(self, f\\"{prefix}{input_.name}\\") for input_ in inputs}\\n\\n            return component.set(**model_kwargs)\\n        return component\\n\\n    def delete_fields(self, build_config: dotdict, fields: dict | list[str]) -> None:\\n        \\"\\"\\"Delete specified fields from build_config.\\"\\"\\"\\n        for field in fields:\\n            build_config.pop(field, None)\\n\\n    def update_input_types(self, build_config: dotdict) -> dotdict:\\n        \\"\\"\\"Update input types for all fields in build_config.\\"\\"\\"\\n        for key, value in build_config.items():\\n            if isinstance(value, dict):\\n                if value.get(\\"input_types\\") is None:\\n                    build_config[key][\\"input_types\\"] = []\\n            elif hasattr(value, \\"input_types\\") and value.input_types is None:\\n                value.input_types = []\\n        return build_config\\n\\n    async def update_build_config(\\n        self, build_config: dotdict, field_value: str, field_name: str | None = None\\n    ) -> dotdict:\\n        # Iterate over all providers in the MODEL_PROVIDERS_DICT\\n        # Existing logic for updating build_config\\n        if field_name in (\\"agent_llm\\",):\\n            build_config[\\"agent_llm\\"][\\"value\\"] = field_value\\n            provider_info = MODEL_PROVIDERS_DICT.get(field_value)\\n            if provider_info:\\n                component_class = provider_info.get(\\"component_class\\")\\n                if component_class and hasattr(component_class, \\"update_build_config\\"):\\n                    # Call the component class's update_build_config method\\n                    build_config = await update_component_build_config(\\n                        component_class, build_config, field_value, \\"model_name\\"\\n                    )\\n\\n            provider_configs: dict[str, tuple[dict, list[dict]]] = {\\n                provider: (\\n                    MODEL_PROVIDERS_DICT[provider][\\"fields\\"],\\n                    [\\n                        MODEL_PROVIDERS_DICT[other_provider][\\"fields\\"]\\n                        for other_provider in MODEL_PROVIDERS_DICT\\n                        if other_provider != provider\\n                    ],\\n                )\\n                for provider in MODEL_PROVIDERS_DICT\\n            }\\n            if field_value in provider_configs:\\n                fields_to_add, fields_to_delete = provider_configs[field_value]\\n\\n                # Delete fields from other providers\\n                for fields in fields_to_delete:\\n                    self.delete_fields(build_config, fields)\\n\\n                # Add provider-specific fields\\n                if field_value == \\"OpenAI\\" and not any(field in build_config for field in fields_to_add):\\n                    build_config.update(fields_to_add)\\n                else:\\n                    build_config.update(fields_to_add)\\n                # Reset input types for agent_llm\\n                build_config[\\"agent_llm\\"][\\"input_types\\"] = []\\n            elif field_value == \\"Custom\\":\\n                # Delete all provider fields\\n                self.delete_fields(build_config, ALL_PROVIDER_FIELDS)\\n                # Update with custom component\\n                custom_component = DropdownInput(\\n                    name=\\"agent_llm\\",\\n                    display_name=\\"Language Model\\",\\n                    options=[*sorted(MODEL_PROVIDERS), \\"Custom\\"],\\n                    value=\\"Custom\\",\\n                    real_time_refresh=True,\\n                    input_types=[\\"LanguageModel\\"],\\n                    options_metadata=[MODELS_METADATA[key] for key in sorted(MODELS_METADATA.keys())]\\n                    + [{\\"icon\\": \\"brain\\"}],\\n                )\\n                build_config.update({\\"agent_llm\\": custom_component.to_dict()})\\n            # Update input types for all fields\\n            build_config = self.update_input_types(build_config)\\n\\n            # Validate required keys\\n            default_keys = [\\n                \\"code\\",\\n                \\"_type\\",\\n                \\"agent_llm\\",\\n                \\"tools\\",\\n                \\"input_value\\",\\n                \\"add_current_date_tool\\",\\n                \\"system_prompt\\",\\n                \\"agent_description\\",\\n                \\"max_iterations\\",\\n                \\"handle_parsing_errors\\",\\n                \\"verbose\\",\\n            ]\\n            missing_keys = [key for key in default_keys if key not in build_config]\\n            if missing_keys:\\n                msg = f\\"Missing required keys in build_config: {missing_keys}\\"\\n                raise ValueError(msg)\\n        if (\\n            isinstance(self.agent_llm, str)\\n            and self.agent_llm in MODEL_PROVIDERS_DICT\\n            and field_name in MODEL_DYNAMIC_UPDATE_FIELDS\\n        ):\\n            provider_info = MODEL_PROVIDERS_DICT.get(self.agent_llm)\\n            if provider_info:\\n                component_class = provider_info.get(\\"component_class\\")\\n                component_class = self.set_component_params(component_class)\\n                prefix = provider_info.get(\\"prefix\\")\\n                if component_class and hasattr(component_class, \\"update_build_config\\"):\\n                    # Call each component class's update_build_config method\\n                    # remove the prefix from the field_name\\n                    if isinstance(field_name, str) and isinstance(prefix, str):\\n                        field_name = field_name.replace(prefix, \\"\\")\\n                    build_config = await update_component_build_config(\\n                        component_class, build_config, field_value, \\"model_name\\"\\n                    )\\n        return dotdict({k: v.to_dict() if hasattr(v, \\"to_dict\\") else v for k, v in build_config.items()})\\n\\n    async def _get_tools(self) -> list[Tool]:\\n        component_toolkit = _get_component_toolkit()\\n        tools_names = self._build_tools_names()\\n        agent_description = self.get_tool_description()\\n        # TODO: Agent Description Depreciated Feature to be removed\\n        description = f\\"{agent_description}{tools_names}\\"\\n        tools = component_toolkit(component=self).get_tools(\\n            tool_name=\\"Call_Agent\\", tool_description=description, callbacks=self.get_langchain_callbacks()\\n        )\\n        if hasattr(self, \\"tools_metadata\\"):\\n            tools = component_toolkit(component=self, metadata=self.tools_metadata).update_tools_metadata(tools=tools)\\n        return tools\\n"}, "handle_parsing_errors": {"_input_type": "BoolInput", "advanced": true, "display_name": "Handle Parse Errors", "dynamic": false, "info": "Should the Agent fix errors when reading user input for better processing?", "list": false, "list_add_label": "Add More", "name": "handle_parsing_errors", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "input_value": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "Input", "dynamic": false, "info": "The input provided by the user for the agent to process.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "json_mode": {"_input_type": "BoolInput", "advanced": true, "display_name": "JSON Mode", "dynamic": false, "info": "If True, it will output JSON regardless of passing a schema.", "list": false, "list_add_label": "Add More", "name": "json_mode", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "max_iterations": {"_input_type": "IntInput", "advanced": true, "display_name": "Max Iterations", "dynamic": false, "info": "The maximum number of attempts the agent can make to complete its task before it stops.", "list": false, "list_add_label": "Add More", "name": "max_iterations", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 15}, "max_retries": {"_input_type": "IntInput", "advanced": true, "display_name": "Max Retries", "dynamic": false, "info": "The maximum number of retries to make when generating.", "list": false, "list_add_label": "Add More", "name": "max_retries", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 5}, "max_tokens": {"_input_type": "IntInput", "advanced": true, "display_name": "Max Tokens", "dynamic": false, "info": "The maximum number of tokens to generate. Set to 0 for unlimited tokens.", "list": false, "list_add_label": "Add More", "name": "max_tokens", "placeholder": "", "range_spec": {"max": 128000, "min": 0, "step": 0.1, "step_type": "float"}, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": ""}, "model_kwargs": {"_input_type": "DictInput", "advanced": true, "display_name": "Model Kwargs", "dynamic": false, "info": "Additional keyword arguments to pass to the model.", "list": false, "list_add_label": "Add More", "name": "model_kwargs", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "type": "dict", "value": {}}, "model_name": {"_input_type": "DropdownInput", "advanced": false, "combobox": true, "dialog_inputs": {}, "display_name": "Model Name", "dynamic": false, "info": "To see the model names, first choose a provider. Then, enter your API key and click the refresh button next to the model name.", "load_from_db": false, "name": "model_name", "options": ["gpt-4o-mini", "gpt-4o", "gpt-4.1", "gpt-4.1-mini", "gpt-4.1-nano", "gpt-4.5-preview", "gpt-4-turbo", "gpt-4-turbo-preview", "gpt-4", "gpt-3.5-turbo", "o1"], "options_metadata": [], "placeholder": "", "real_time_refresh": false, "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "gpt-4.1"}, "n_messages": {"_input_type": "IntInput", "advanced": true, "display_name": "Number of Chat History Messages", "dynamic": false, "info": "Number of chat history messages to retrieve.", "list": false, "list_add_label": "Add More", "name": "n_messages", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 100}, "openai_api_base": {"_input_type": "StrInput", "advanced": true, "display_name": "OpenAI API Base", "dynamic": false, "info": "The base URL of the OpenAI API. Defaults to https://api.openai.com/v1. You can change this to use other APIs like JinaChat, LocalAI and Prem.", "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "openai_api_base", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": ""}, "seed": {"_input_type": "IntInput", "advanced": true, "display_name": "Seed", "dynamic": false, "info": "The seed controls the reproducibility of the job.", "list": false, "list_add_label": "Add More", "name": "seed", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 1}, "system_prompt": {"_input_type": "MultilineInput", "advanced": false, "copy_field": false, "display_name": "Agent Instructions", "dynamic": false, "info": "System Prompt: Initial instructions and context provided to guide the agent's behavior.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "system_prompt", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "You are an Amazing Travel Concierge, a specialist in travel planning and logistics with decades of experience. Your goal is to create the most amazing travel itineraries with budget and packing suggestions for the city. Expand the city guide into a full 7-day travel itinerary with detailed per-day plans. Include weather forecasts, places to eat, packing suggestions, and a budget breakdown. Suggest actual places to visit, hotels to stay, and restaurants to go to. Your final output should be a complete expanded travel plan, formatted as markdown, encompassing a daily schedule, anticipated weather conditions, recommended clothing and items to pack, and a detailed budget."}, "temperature": {"_input_type": "SliderInput", "advanced": true, "display_name": "Temperature", "dynamic": false, "info": "", "max_label": "", "max_label_icon": "", "min_label": "", "min_label_icon": "", "name": "temperature", "placeholder": "", "range_spec": {"max": 1, "min": 0, "step": 0.01, "step_type": "float"}, "required": false, "show": true, "slider_buttons": false, "slider_buttons_options": [], "slider_input": false, "title_case": false, "tool_mode": false, "type": "slider", "value": 0.1}, "timeout": {"_input_type": "IntInput", "advanced": true, "display_name": "Timeout", "dynamic": false, "info": "The timeout for requests to OpenAI completion API.", "list": false, "list_add_label": "Add More", "name": "timeout", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 700}, "tools": {"_input_type": "HandleInput", "advanced": false, "display_name": "Tools", "dynamic": false, "info": "These are the tools that the agent can use to help with tasks.", "input_types": ["Tool"], "list": true, "list_add_label": "Add More", "name": "tools", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "verbose": {"_input_type": "BoolInput", "advanced": true, "display_name": "Verbose", "dynamic": false, "info": "", "list": false, "list_add_label": "Add More", "name": "verbose", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}}, "tool_mode": false}, "selected_output": "response", "showNode": true, "type": "Agent"}, "dragging": false, "id": "Agent-C8zRS", "measured": {"height": 594, "width": 320}, "position": {"x": 3936.123532016018, "y": 356.3534774464019}, "selected": false, "type": "genericNode"}], "viewport": {"x": -700.2707036326251, "y": 138.91846301898352, "zoom": 0.4425927036021963}}	Travel Planning Agents	Create a travel plan