false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Model Response", "group_outputs": false, "hidden": null, "method": "text_response", "name": "text_output", "options": null, "required_inputs": null, "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}, {"allows_loop": false, "cache": true, "display_name": "Language Model", "group_outputs": false, "hidden": null, "method": "build_model", "name": "model_output", "options": null, "required_inputs": null, "selected": "LanguageModel", "tool_mode": true, "types": ["LanguageModel"], "value": "__UNDEFINED__"}], "pinned": false, "priority": 0, "template": {"_type": "Component", "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "OpenAI API Key", "dynamic": false, "info": "Model Provider API key", "input_types": [], "load_from_db": true, "name": "api_key", "password": true, "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "type": "str", "value": "OPENAI_API_KEY"}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from typing import Any\\n\\nfrom langchain_anthropic import ChatAnthropic\\nfrom langchain_google_genai import ChatGoogleGenerativeAI\\nfrom langchain_openai import ChatOpenAI\\n\\nfrom langflow.base.models.anthropic_constants import ANTHROPIC_MODELS\\nfrom langflow.base.models.google_generative_ai_constants import GOOGLE_GENERATIVE_AI_MODELS\\nfrom langflow.base.models.model import LCModelComponent\\nfrom langflow.base.models.openai_constants import OPENAI_CHAT_MODEL_NAMES, OPENAI_REASONING_MODEL_NAMES\\nfrom langflow.field_typing import LanguageModel\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.inputs.inputs import BoolInput\\nfrom langflow.io import DropdownInput, MessageInput, MultilineInput, SecretStrInput, SliderInput\\nfrom langflow.schema.dotdict import dotdict\\n\\n\\nclass LanguageModelComponent(LCModelComponent):\\n    display_name = \\"Language Model\\"\\n    description = \\"Runs a language model given a specified provider.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-models\\"\\n    icon = \\"brain-circuit\\"\\n    category = \\"models\\"\\n    priority = 0  # Set priority to 0 to make it appear first\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\"provider\\",\\n            display_name=\\"Model Provider\\",\\n            options=[\\"OpenAI\\", \\"Anthropic\\", \\"Google\\"],\\n            value=\\"OpenAI\\",\\n            info=\\"Select the model provider\\",\\n            real_time_refresh=True,\\n            options_metadata=[{\\"icon\\": \\"OpenAI\\"}, {\\"icon\\": \\"Anthropic\\"}, {\\"icon\\": \\"GoogleGenerativeAI\\"}],\\n        ),\\n        DropdownInput(\\n            name=\\"model_name\\",\\n            display_name=\\"Model Name\\",\\n            options=OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES,\\n            value=OPENAI_CHAT_MODEL_NAMES[0],\\n            info=\\"Select the model to use\\",\\n            real_time_refresh=True,\\n        ),\\n        SecretStrInput(\\n            name=\\"api_key\\",\\n            display_name=\\"OpenAI API Key\\",\\n            info=\\"Model Provider API key\\",\\n            required=False,\\n            show=True,\\n            real_time_refresh=True,\\n        ),\\n        MessageInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input\\",\\n            info=\\"The input text to send to the model\\",\\n        ),\\n        MultilineInput(\\n            name=\\"system_message\\",\\n            display_name=\\"System Message\\",\\n            info=\\"A system message that helps set the behavior of the assistant\\",\\n            advanced=False,\\n        ),\\n        BoolInput(\\n            name=\\"stream\\",\\n            display_name=\\"Stream\\",\\n            info=\\"Whether to stream the response\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n        SliderInput(\\n            name=\\"temperature\\",\\n            display_name=\\"Temperature\\",\\n            value=0.1,\\n            info=\\"Controls randomness in responses\\",\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:\\n        provider = self.provider\\n        model_name = self.model_name\\n        temperature = self.temperature\\n        stream = self.stream\\n\\n        if provider == \\"OpenAI\\":\\n            if not self.api_key:\\n                msg = \\"OpenAI API key is required when using OpenAI provider\\"\\n                raise ValueError(msg)\\n\\n            if model_name in OPENAI_REASONING_MODEL_NAMES:\\n                # reasoning models do not support temperature (yet)\\n                temperature = None\\n\\n            return ChatOpenAI(\\n                model_name=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                openai_api_key=self.api_key,\\n            )\\n        if provider == \\"Anthropic\\":\\n            if not self.api_key:\\n                msg = \\"Anthropic API key is required when using Anthropic provider\\"\\n                raise ValueError(msg)\\n            return ChatAnthropic(\\n                model=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                anthropic_api_key=self.api_key,\\n            )\\n        if provider == \\"Google\\":\\n            if not self.api_key:\\n                msg = \\"Google API key is required when using Google provider\\"\\n                raise ValueError(msg)\\n            return ChatGoogleGenerativeAI(\\n                model=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                google_api_key=self.api_key,\\n            )\\n        msg = f\\"Unknown provider: {provider}\\"\\n        raise ValueError(msg)\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:\\n        if field_name == \\"provider\\":\\n            if field_value == \\"OpenAI\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES\\n                build_config[\\"model_name\\"][\\"value\\"] = OPENAI_CHAT_MODEL_NAMES[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"OpenAI API Key\\"\\n            elif field_value == \\"Anthropic\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = ANTHROPIC_MODELS\\n                build_config[\\"model_name\\"][\\"value\\"] = ANTHROPIC_MODELS[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"Anthropic API Key\\"\\n            elif field_value == \\"Google\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = GOOGLE_GENERATIVE_AI_MODELS\\n                build_config[\\"model_name\\"][\\"value\\"] = GOOGLE_GENERATIVE_AI_MODELS[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"Google API Key\\"\\n        elif field_name == \\"model_name\\" and field_value.startswith(\\"o1\\") and self.provider == \\"OpenAI\\":\\n            # Hide system_message for o1 models - currently unsupported\\n            if \\"system_message\\" in build_config:\\n                build_config[\\"system_message\\"][\\"show\\"] = False\\n        elif field_name == \\"model_name\\" and not field_value.startswith(\\"o1\\") and \\"system_message\\" in build_config:\\n            build_config[\\"system_message\\"][\\"show\\"] = True\\n        return build_config\\n"}, "input_value": {"_input_type": "MessageInput", "advanced": false, "display_name": "Input", "dynamic": false, "info": "The input text to send to the model", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "model_name": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Name", "dynamic": false, "info": "Select the model to use", "name": "model_name", "options": ["gpt-4o-mini", "gpt-4o", "gpt-4.1", "gpt-4.1-mini", "gpt-4.1-nano", "gpt-4.5-preview", "gpt-4-turbo", "gpt-4-turbo-preview", "gpt-4", "gpt-3.5-turbo"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "gpt-4o-mini"}, "provider": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Provider", "dynamic": false, "info": "Select the model provider", "name": "provider", "options": ["OpenAI", "Anthropic", "Google"], "options_metadata": [{"icon": "OpenAI"}, {"icon": "Anthropic"}, {"icon": "GoogleGenerativeAI"}], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "OpenAI"}, "stream": {"_input_type": "BoolInput", "advanced": true, "display_name": "Stream", "dynamic": false, "info": "Whether to stream the response", "list": false, "list_add_label": "Add More", "name": "stream", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "system_message": {"_input_type": "MultilineInput", "advanced": false, "copy_field": false, "display_name": "System Message", "dynamic": false, "info": "A system message that helps set the behavior of the assistant", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "system_message", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "temperature": {"_input_type": "SliderInput", "advanced": true, "display_name": "Temperature", "dynamic": false, "info": "Controls randomness in responses", "max_label": "", "max_label_icon": "", "min_label": "", "min_label_icon": "", "name": "temperature", "placeholder": "", "range_spec": {"max": 1, "min": 0, "step": 0.01, "step_type": "float"}, "required": false, "show": true, "slider_buttons": false, "slider_buttons_options": [], "slider_input": false, "title_case": false, "tool_mode": false, "type": "slider", "value": 0.1}}, "tool_mode": false}, "selected_output": "text_output", "showNode": true, "type": "LanguageModelComponent"}, "dragging": false, "id": "LanguageModelComponent-kBOja", "measured": {"height": 534, "width": 320}, "position": {"x": 1085.7542386472996, "y": 795.0399905192078}, "selected": true, "type": "genericNode"}], "viewport": {"x": -171.73930599141136, "y": -281.4054320344371, "zoom": 0.7267911009473667}}	Basic Prompting	Perform basic prompting with an OpenAI model.	7bf2d7a9-e41f-4401-9b6f-87f3f22ccc8c	\N	f	2025-08-21 21:14:34.362992	\N	\N	dfa61cb0-f7c5-4926-b103-2742d9184e44	\N	f	\N	["chatbots"]	f	\N	PRIVATE	f	\N	\N
