"Message"], "list": false, "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "selected_output": "message", "type": "ChatInput"}, "dragging": false, "height": 234, "id": "ChatInput-xLWhw", "measured": {"height": 234, "width": 320}, "position": {"x": 2321.5543981677606, "y": 374.0457826421628}, "positionAbsolute": {"x": 2321.5543981677606, "y": 374.0457826421628}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"description": "Display a chat message in the Playground.", "display_name": "Chat Output", "id": "ChatOutput-2ljRT", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Display a chat message in the Playground.", "display_name": "Chat Output", "documentation": "", "edited": false, "field_order": ["input_value", "should_store_message", "sender", "sender_name", "session_id", "data_template", "background_color", "chat_icon", "text_color"], "frozen": false, "icon": "MessagesSquare", "legacy": false, "lf_version": "1.4.3", "metadata": {}, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Output Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "background_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Background Color", "dynamic": false, "info": "The background color of the icon.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "background_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "chat_icon": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "clean_data": {"_input_type": "BoolInput", "advanced": true, "display_name": "Basic Clean Data", "dynamic": false, "info": "Whether to clean the data", "list": false, "list_add_label": "Add More", "name": "clean_data", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from collections.abc import Generator\\nfrom typing import Any\\n\\nimport orjson\\nfrom fastapi.encoders import jsonable_encoder\\n\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.inputs.inputs import BoolInput, DropdownInput, HandleInput, MessageTextInput\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.schema.properties import Source\\nfrom langflow.template.field.base import Output\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_AI,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatOutput(ChatComponent):\\n    display_name = \\"Chat Output\\"\\n    description = \\"Display a chat message in the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-output\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatOutput\\"\\n    minimized = True\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Inputs\\",\\n            info=\\"Message to be passed as output.\\",\\n            input_types=[\\"Data\\", \\"DataFrame\\", \\"Message\\"],\\n            required=True,\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_AI,\\n            advanced=True,\\n            info=\\"Type of sender.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_AI,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"data_template\\",\\n            display_name=\\"Data Template\\",\\n            value=\\"{text}\\",\\n            advanced=True,\\n            info=\\"Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"clean_data\\",\\n            display_name=\\"Basic Clean Data\\",\\n            value=True,\\n            info=\\"Whether to clean the data\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\"Output Message\\",\\n            name=\\"message\\",\\n            method=\\"message_response\\",\\n        ),\\n    ]\\n\\n    def _build_source(self, id_: str | None, display_name: str | None, source: str | None) -> Source:\\n        source_dict = {}\\n        if id_:\\n            source_dict[\\"id\\"] = id_\\n        if display_name:\\n            source_dict[\\"display_name\\"] = display_name\\n        if source:\\n            # Handle case where source is a ChatOpenAI object\\n            if hasattr(source, \\"model_name\\"):\\n                source_dict[\\"source\\"] = source.model_name\\n            elif hasattr(source, \\"model\\"):\\n                source_dict[\\"source\\"] = str(source.model)\\n            else:\\n                source_dict[\\"source\\"] = str(source)\\n        return Source(**source_dict)\\n\\n    async def message_response(self) -> Message:\\n        # First convert the input to string if needed\\n        text = self.convert_to_string()\\n\\n        # Get source properties\\n        source, icon, display_name, source_id = self.get_properties_from_source_component()\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        if self.chat_icon:\\n            icon = self.chat_icon\\n\\n        # Create or use existing Message object\\n        if isinstance(self.input_value, Message):\\n            message = self.input_value\\n            # Update message properties\\n            message.text = text\\n        else:\\n            message = Message(text=text)\\n\\n        # Set message properties\\n        message.sender = self.sender\\n        message.sender_name = self.sender_name\\n        message.session_id = self.session_id\\n        message.flow_id = self.graph.flow_id if hasattr(self, \\"graph\\") else None\\n        message.properties.source = self._build_source(source_id, display_name, source)\\n        message.properties.icon = icon\\n        message.properties.background_color = background_color\\n        message.properties.text_color = text_color\\n\\n        # Store message if needed\\n        if self.session_id and self.should_store_message:\\n            stored_message = await self.send_message(message)\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n\\n    def _serialize_data(self, data: Data) -> str:\\n        \\"\\"\\"Serialize Data object to JSON string.\\"\\"\\"\\n        # Convert data.data to JSON-serializable format\\n        serializable_data = jsonable_encoder(data.data)\\n        # Serialize with orjson, enabling pretty printing with indentation\\n        json_bytes = orjson.dumps(serializable_data, option=orjson.OPT_INDENT_2)\\n        # Convert bytes to string and wrap in Markdown code blocks\\n        return \\"```json\\\\n\\" + json_bytes.decode(\\"utf-8\\") + \\"\\\\n```\\"\\n\\n    def _validate_input(self) -> None:\\n        \\"\\"\\"Validate the input data and raise ValueError if invalid.\\"\\"\\"\\n        if self.input_value is None:\\n            msg = \\"Input data cannot be None\\"\\n            raise ValueError(msg)\\n        if isinstance(self.input_value, list) and not all(\\n            isinstance(item, Message | Data | DataFrame | str) for item in self.input_value\\n        ):\\n            invalid_types = [\\n                type(item).__name__\\n                for item in self.input_value\\n                if not isinstance(item, Message | Data | DataFrame | str)\\n            ]\\n            msg = f\\"Expected Data or DataFrame or Message or str, got {invalid_types}\\"\\n            raise TypeError(msg)\\n        if not isinstance(\\n            self.input_value,\\n            Message | Data | DataFrame | str | list | Generator | type(None),\\n        ):\\n            type_name = type(self.input_value).__name__\\n            msg = f\\"Expected Data or DataFrame or Message or str, Generator or None, got {type_name}\\"\\n            raise TypeError(msg)\\n\\n    def convert_to_string(self) -> str | Generator[Any, None, None]:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        self._validate_input()\\n        if isinstance(self.input_value, list):\\n            return \\"\\\\n\\".join([safe_convert(item, clean_data=self.clean_data) for item in self.input_value])\\n        if isinstance(self.input_value, Generator):\\n            return self.input_value\\n        return safe_convert(self.input_value)\\n"}, "data_template": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Data Template", "dynamic": false, "info": "Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "data_template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "{text}"}, "input_value": {"_input_type": "MessageInput", "advanced": false, "display_name": "Inputs", "dynamic": false, "info": "Message to be passed as output.", "input_types": ["Data", "DataFrame", "Message"], "list": false, "load_from_db": false, "name": "input_value", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Machine"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "AI"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "type": "ChatOutput"}, "dragging": true, "height": 234, "id": "ChatOutput-2ljRT", "measured": {"height": 234, "width": 320}, "position": {"x": 3113.9880204333917, "y": 769.7618411016429}, "positionAbsolute": {"x": 3101.965731391458, "y": 776.4408905693839}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"id": "note-hLqzd", "node": {"description": "# Memory Chatbot\\n\\nThis flow extends the basic prompting flow with a Message history component that stores up to 100 previous chat messages and uses them to provide context for the current conversation.\\n\\n## Prerequisites\\n\\n* [OpenAI API Key](https://platform.openai.com/)\\n\\n## Quickstart\\n\\n1. In the **Language Model** component, add your OpenAI API Key.\\n\\n2. Open the **Playground**. Tell the chat your name.\\n\\n3. Start a new chat session in the Playground, and ask, `what is my name`. The Prompt component will still remember your name, because it's connected to the Message History component.\\n\\n", "display_name": "", "documentation": "", "template": {}}, "type": "note"}, "dragging": false, "height": 666, "id": "note-hLqzd", "measured": {"height": 666, "width": 383}, "position": {"x": 1462.894231659186, "y": 345.8660745626851}, "positionAbsolute": {"x": 1512.8976594415833, "y": 312.9558305744385}, "resizing": false, "selected": false, "style": {"height": 736, "width": 324}, "type": "noteNode", "width": 383}, {"data": {"id": "Prompt-9wc4j", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {"template": ["memory"]}, "description": "Create a prompt template with dynamic variables.", "display_name": "Prompt", "documentation": "", "edited": false, "error": null, "field_order": ["template"], "frozen": false, "full_path": null, "icon": "braces", "is_composition": null, "is_input": null, "is_output": null, "legacy": false, "lf_version": "1.4.3", "metadata": {}, "name": "", "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Prompt", "group_outputs": false, "method": "build_prompt", "name": "prompt", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.base.prompts.api_utils import process_prompt_template\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.inputs.inputs import DefaultPromptField\\nfrom langflow.io import MessageTextInput, Output, PromptInput\\nfrom langflow.schema.message import Message\\nfrom langflow.template.utils import update_template_values\\n\\n\\nclass PromptComponent(Component):\\n    display_name: str = \\"Prompt\\"\\n    description: str = \\"Create a prompt template with dynamic variables.\\"\\n    icon = \\"braces\\"\\n    trace_type = \\"prompt\\"\\n    name = \\"Prompt\\"\\n\\n    inputs = [\\n        PromptInput(name=\\"template\\", display_name=\\"Template\\"),\\n        MessageTextInput(\\n            name=\\"tool_placeholder\\",\\n            display_name=\\"Tool Placeholder\\",\\n            tool_mode=True,\\n            advanced=True,\\n            info=\\"A placeholder input for tool mode.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Prompt\\", name=\\"prompt\\", method=\\"build_prompt\\"),\\n    ]\\n\\n    async def build_prompt(self) -> Message:\\n        prompt = Message.from_template(**self._attributes)\\n        self.status = prompt.text\\n        return prompt\\n\\n    def _update_template(self, frontend_node: dict):\\n        prompt_template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        custom_fields = frontend_node[\\"custom_fields\\"]\\n        frontend_node_template = frontend_node[\\"template\\"]\\n        _ = process_prompt_template(\\n            template=prompt_template,\\n            name=\\"template\\",\\n            custom_fields=custom_fields,\\n            frontend_node_template=frontend_node_template,\\n        )\\n        return frontend_node\\n\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict):\\n        \\"\\"\\"This function is called after the code validation is done.\\"\\"\\"\\n        frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        # Kept it duplicated for backwards compatibility\\n        _ = process_prompt_template(\\n            template=template,\\n            name=\\"template\\",\\n            custom_fields=frontend_node[\\"custom_fields\\"],\\n            frontend_node_template=frontend_node[\\"template\\"],\\n        )\\n        # Now that template is updated, we need to grab any values that were set in the current_frontend_node\\n        # and update the frontend_node with those values\\n        update_template_values(new_template=frontend_node, previous_template=current_frontend_node[\\"template\\"])\\n        return frontend_node\\n\\n    def _get_fallback_input(self, **kwargs):\\n        return DefaultPromptField(**kwargs)\\n"}, "memory": {"advanced": false, "display_name": "memory", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message", "Text"], "list": false, "load_from_db": false, "multiline": true, "name": "memory", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": ""}, "template": {"_input_type": "PromptInput", "advanced": false, "display_name": "Template", "dynamic": false, "info": "", "list": false, "name": "template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "type": "prompt", "value": "You are a helpful assistant that answer questions.\\n\\nUse markdown to format your answer, properly embedding images and urls.\\n\\nHistory: \\n\\n{memory}\\n"}, "tool_placeholder": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Tool Placeholder", "dynamic": false, "info": "A placeholder input for tool mode.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "tool_placeholder", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "selected_output": "prompt", "type": "Prompt"}, "dragging": false, "height": 347, "id": "Prompt-9wc4j", "measured": {"height": 347, "width": 320}, "position": {"x": 2351.863651394379, "y": 636.2759646634735}, "positionAbsolute": {"x": 2327.422938009026, "y": 675.992123914672}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"id": "Memory-MKGtC", "node": {"base_classes": ["DataFrame"], "beta": false, "category": "helpers", "conditional_paths": [], "custom_fields": {}, "description": "Stores or retrieves stored chat messages from Langflow tables or an external memory.", "display_name": "Message History", "documentation": "", "edited": false, "field_order": ["mode", "message", "memory", "sender", "sender_name", "n_messages", "session_id", "order", "template"], "frozen": false, "icon": "message-square-more", "key": "Memory", "legacy": false, "lf_version": "1.4.3", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Message", "group_outputs": false, "method": "retrieve_messages_as_text", "name": "messages_text", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}, {"allows_loop": false, "cache": true, "display_name": "Dataframe", "group_outputs": false, "method": "retrieve_messages_dataframe", "name": "dataframe", "selected": null, "tool_mode": true, "types": ["DataFrame"], "value": "__UNDEFINED__"}], "pinned": false, "score": 0.007568328950209746, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from typing import Any, cast\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.helpers.data import data_to_text\\nfrom langflow.inputs.inputs import DropdownInput, HandleInput, IntInput, MessageTextInput, MultilineInput, TabInput\\nfrom langflow.memory import aget_messages, astore_message\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.dotdict import dotdict\\nfrom langflow.schema.message import Message\\nfrom langflow.template.field.base import Output\\nfrom langflow.utils.component_utils import set_current_fields, set_field_display\\nfrom langflow.utils.constants import MESSAGE_SENDER_AI, MESSAGE_SENDER_NAME_AI, MESSAGE_SENDER_USER\\n\\n\\nclass MemoryComponent(Component):\\n    display_name = \\"Message History\\"\\n    description = \\"Stores or retrieves stored chat messages from Langflow tables or an external memory.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-helpers#message-history\\"\\n    icon = \\"message-square-more\\"\\n    name = \\"Memory\\"\\n    default_keys = [\\"mode\\", \\"memory\\"]\\n    mode_config = {\\n        \\"Store\\": [\\"message\\", \\"memory\\", \\"sender\\", \\"sender_name\\", \\"session_id\\"],\\n        \\"Retrieve\\": [\\"n_messages\\", \\"order\\", \\"template\\", \\"memory\\"],\\n    }\\n\\n    inputs = [\\n        TabInput(\\n            name=\\"mode\\",\\n            display_name=\\"Mode\\",\\n            options=[\\"Retrieve\\", \\"Store\\"],\\n            value=\\"Retrieve\\",\\n            info=\\"Operation mode: Store messages or Retrieve messages.\\",\\n            real_time_refresh=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"message\\",\\n            display_name=\\"Message\\",\\n            info=\\"The chat message to be stored.\\",\\n            tool_mode=True,\\n            dynamic=True,\\n            show=False,\\n        ),\\n        HandleInput(\\n            name=\\"memory\\",\\n            display_name=\\"External Memory\\",\\n            input_types=[\\"Memory\\"],\\n            info=\\"Retrieve messages from an external memory. If empty, it will use the Langflow tables.\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender_type\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER, \\"Machine and User\\"],\\n            value=\\"Machine and User\\",\\n            info=\\"Filter by sender type.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender\\",\\n            info=\\"The sender of the message. Might be Machine or User. \\"\\n            \\"If empty, the current sender parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Filter by sender name.\\",\\n            advanced=True,\\n            show=False,\\n        ),\\n        IntInput(\\n            name=\\"n_messages\\",\\n            display_name=\\"Number of Messages\\",\\n            value=100,\\n            info=\\"Number of messages to retrieve.\\",\\n            advanced=True,\\n            show=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            value=\\"\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"order\\",\\n            display_name=\\"Order\\",\\n            options=[\\"Ascending\\", \\"Descending\\"],\\n            value=\\"Ascending\\",\\n            info=\\"Order of the messages.\\",\\n            advanced=True,\\n            tool_mode=True,\\n            required=True,\\n        ),\\n        MultilineInput(\\n            name=\\"template\\",\\n            display_name=\\"Template\\",\\n            info=\\"The template to use for formatting the data. \\"\\n            \\"It can contain the keys {text}, {sender} or any other key in the message data.\\",\\n            value=\\"{sender_name}: {text}\\",\\n            advanced=True,\\n            show=False,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Message\\", name=\\"messages_text\\", method=\\"retrieve_messages_as_text\\", dynamic=True),\\n        Output(display_name=\\"Dataframe\\", name=\\"dataframe\\", method=\\"retrieve_messages_dataframe\\", dynamic=True),\\n    ]\\n\\n    def update_outputs(self, frontend_node: dict, field_name: str, field_value: Any) -> dict:\\n        \\"\\"\\"Dynamically show only the relevant output based on the selected output type.\\"\\"\\"\\n        if field_name == \\"mode\\":\\n            # Start with empty outputs\\n            frontend_node[\\"outputs\\"] = []\\n            if field_value == \\"Store\\":\\n                frontend_node[\\"outputs\\"] = [\\n                    Output(\\n                        display_name=\\"Stored Messages\\",\\n                        name=\\"stored_messages\\",\\n                        method=\\"store_message\\",\\n                        hidden=True,\\n                        dynamic=True,\\n                    )\\n                ]\\n            if field_value == \\"Retrieve\\":\\n                frontend_node[\\"outputs\\"] = [\\n                    Output(\\n                        display_name=\\"Messages\\", name=\\"messages_text\\", method=\\"retrieve_messages_as_text\\", dynamic=True\\n                    ),\\n                    Output(\\n                        display_name=\\"Dataframe\\", name=\\"dataframe\\", method=\\"retrieve_messages_dataframe\\", dynamic=True\\n                    ),\\n                ]\\n        return frontend_node\\n\\n    async def store_message(self) -> Message:\\n        message = Message(text=self.message) if isinstance(self.message, str) else self.message\\n\\n        message.session_id = self.session_id or message.session_id\\n        message.sender = self.sender or message.sender or MESSAGE_SENDER_AI\\n        message.sender_name = self.sender_name or message.sender_name or MESSAGE_SENDER_NAME_AI\\n\\n        stored_messages: list[Message] = []\\n\\n        if self.memory:\\n            self.memory.session_id = message.session_id\\n            lc_message = message.to_lc_message()\\n            await self.memory.aadd_messages([lc_message])\\n\\n            stored_messages = await self.memory.aget_messages() or []\\n\\n            stored_messages = [Message.from_lc_message(m) for m in stored_messages] if stored_messages else []\\n\\n            if message.sender:\\n                stored_messages = [m for m in stored_messages if m.sender == message.sender]\\n        else:\\n            await astore_message(message, flow_id=self.graph.flow_id)\\n            stored_messages = (\\n                await aget_messages(\\n                    session_id=message.session_id, sender_name=message.sender_name, sender=message.sender\\n                )\\n                or []\\n            )\\n\\n        if not stored_messages:\\n            msg = \\"No messages were stored. Please ensure that the session ID and sender are properly set.\\"\\n            raise ValueError(msg)\\n\\n        stored_message = stored_messages[0]\\n        self.status = stored_message\\n        return stored_message\\n\\n    async def retrieve_messages(self) -> Data:\\n        sender_type = self.sender_type\\n        sender_name = self.sender_name\\n        session_id = self.session_id\\n        n_messages = self.n_messages\\n        order = \\"DESC\\" if self.order == \\"Descending\\" else \\"ASC\\"\\n\\n        if sender_type == \\"Machine and User\\":\\n            sender_type = None\\n\\n        if self.memory and not hasattr(self.memory, \\"aget_messages\\"):\\n            memory_name = type(self.memory).__name__\\n            err_msg = f\\"External Memory object ({memory_name}) must have 'aget_messages' method.\\"\\n            raise AttributeError(err_msg)\\n        # Check if n_messages is None or 0\\n        if n_messages == 0:\\n            stored = []\\n        elif self.memory:\\n            # override session_id\\n            self.memory.session_id = session_id\\n\\n            stored = await self.memory.aget_messages()\\n            # langchain memories are supposed to return messages in ascending order\\n\\n            if order == \\"DESC\\":\\n                stored = stored[::-1]\\n            if n_messages:\\n                stored = stored[-n_messages:] if order == \\"ASC\\" else stored[:n_messages]\\n            stored = [Message.from_lc_message(m) for m in stored]\\n            if sender_type:\\n                expected_type = MESSAGE_SENDER_AI if sender_type == MESSAGE_SENDER_AI else MESSAGE_SENDER_USER\\n                stored = [m for m in stored if m.type == expected_type]\\n        else:\\n            # For internal memory, we always fetch the last N messages by ordering by DESC\\n            stored = await aget_messages(\\n                sender=sender_type,\\n                sender_name=sender_name,\\n                session_id=session_id,\\n                limit=10000,\\n                order=order,\\n            )\\n            if n_messages:\\n                stored = stored[-n_messages:] if order == \\"ASC\\" else stored[:n_messages]\\n\\n        # self.status = stored\\n        return cast(Data, stored)\\n\\n    async def retrieve_messages_as_text(self) -> Message:\\n        stored_text = data_to_text(self.template, await self.retrieve_messages())\\n        # self.status = stored_text\\n        return Message(text=stored_text)\\n\\n    async def retrieve_messages_dataframe(self) -> DataFrame:\\n        \\"\\"\\"Convert the retrieved messages into a DataFrame.\\n\\n        Returns:\\n            DataFrame: A DataFrame containing the message data.\\n        \\"\\"\\"\\n        messages = await self.retrieve_messages()\\n        return DataFrame(messages)\\n\\n    def update_build_config(\\n        self,\\n        build_config: dotdict,\\n        field_value: Any,  # noqa: ARG002\\n        field_name: str | None = None,  # noqa: ARG002\\n    ) -> dotdict:\\n        return set_current_fields(\\n            build_config=build_config,\\n            action_fields=self.mode_config,\\n            selected_action=build_config[\\"mode\\"][\\"value\\"],\\n            default_fields=self.default_keys,\\n            func=set_field_display,\\n        )\\n"}, "memory": {"_input_type": "HandleInput", "advanced": true, "display_name": "External Memory", "dynamic": false, "info": "Retrieve messages from an external memory. If empty, it will use the Langflow tables.", "input_types": ["Memory"], "list": false, "list_add_label": "Add More", "name": "memory", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "message": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "Message", "dynamic": true, "info": "The chat message to be stored.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "message", "placeholder": "", "required": false, "show": false, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "mode": {"_input_type": "TabInput", "advanced": false, "display_name": "Mode", "dynamic": false, "info": "Operation mode: Store messages or Retrieve messages.", "name": "mode", "options": ["Retrieve", "Store"], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tab", "value": "Retrieve"}, "n_messages": {"_input_type": "IntInput", "advanced": true, "display_name": "Number of Messages", "dynamic": false, "info": "Number of messages to retrieve.", "list": false, "list_add_label": "Add More", "name": "n_messages", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "int", "value": 100}, "order": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Order", "dynamic": false, "info": "Order of the messages.", "name": "order", "options": ["Ascending", "Descending"], "options_metadata": [], "placeholder": "", "required": true, "show": true, "title_case": false, "toggle": false, "tool_mode": true, "trace_as_metadata": true, "type": "str", "value": "Ascending"}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Sender", "dynamic": false, "info": "The sender of the message. Might be Machine or User. If empty, the current sender parameter will be used.", "name": "sender", "options": ["Machine", "User", "Machine and User"], "options_metadata": [], "placeholder": "", "required": false, "show": false, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Machine and User"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Filter by sender name.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": false, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "sender_type": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Sender Type", "dynamic": false, "info": "Filter by sender type.", "name": "sender_type", "options": ["Machine", "User", "Machine and User"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Machine and User"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": false, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "template": {"_input_type": "MultilineInput", "advanced": true, "copy_field": false, "display_name": "Template", "dynamic": false, "info": "The template to use for formatting the data. It can contain the keys {text}, {sender} or any other key in the message data.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "{sender_name}: {text}"}}, "tool_mode": false}, "selected_output": "messages_text", "showNode": true, "type": "Memory"}, "dragging": false, "id": "Memory-MKGtC", "measured": {"height": 218, "width": 320}, "position": {"x": 1872.1863138733531, "y": 662.4809140460989}, "selected": false, "type": "genericNode"}, {"data": {"id": "LanguageModelComponent-n8KRg", "node": {"base_classes": ["LanguageModel", "Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Runs a language model given a specified provider. ", "display_name": "Language Model", "documentation": "", "edited": false, "field_order": ["provider", "model_name", "api_key", "input_value", "system_message", "stream", "temperature"], "frozen": false, "icon": "brain-circuit", "legacy": false, "lf_version": "1.4.3", "metadata": {"keywords": ["model", "llm", "language model", "large language model"]}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Model Response", "group_outputs": false, "method": "text_response", "name": "text_output", "options": null, "required_inputs": null, "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}, {"allows_loop": false, "cache": true, "display_name": "Language Model", "group_outputs": false, "method": "build_model", "name": "model_output", "options": null, "required_inputs": null, "selected": "LanguageModel", "tool_mode": true, "types": ["LanguageModel"], "value": "__UNDEFINED__"}], "pinned": false, "priority": 0, "template": {"_type": "Component", "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "OpenAI API Key", "dynamic": false, "info": "Model Provider API key", "input_types": [], "load_from_db": true, "name": "api_key", "password": true, "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "type": "str", "value": "OPENAI_API_KEY"}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from typing import Any\\n\\nfrom langchain_anthropic import ChatAnthropic\\nfrom langchain_google_genai import ChatGoogleGenerativeAI\\nfrom langchain_openai import ChatOpenAI\\n\\nfrom langflow.base.models.anthropic_constants import ANTHROPIC_MODELS\\nfrom langflow.base.models.google_generative_ai_constants import GOOGLE_GENERATIVE_AI_MODELS\\nfrom langflow.base.models.model import LCModelComponent\\nfrom langflow.base.models.openai_constants import OPENAI_CHAT_MODEL_NAMES, OPENAI_REASONING_MODEL_NAMES\\nfrom langflow.field_typing import LanguageModel\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.inputs.inputs import BoolInput\\nfrom langflow.io import DropdownInput, MessageInput, MultilineInput, SecretStrInput, SliderInput\\nfrom langflow.schema.dotdict import dotdict\\n\\n\\nclass LanguageModelComponent(LCModelComponent):\\n    display_name = \\"Language Model\\"\\n    description = \\"Runs a language model given a specified provider.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-models\\"\\n    icon = \\"brain-circuit\\"\\n    category = \\"models\\"\\n    priority = 0  # Set priority to 0 to make it appear first\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\"provider\\",\\n            display_name=\\"Model Provider\\",\\n            options=[\\"OpenAI\\", \\"Anthropic\\", \\"Google\\"],\\n            value=\\"OpenAI\\",\\n            info=\\"Select the model provider\\",\\n            real_time_refresh=True,\\n            options_metadata=[{\\"icon\\": \\"OpenAI\\"}, {\\"icon\\": \\"Anthropic\\"}, {\\"icon\\": \\"GoogleGenerativeAI\\"}],\\n        ),\\n        DropdownInput(\\n            name=\\"model_name\\",\\n            display_name=\\"Model Name\\",\\n            options=OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES,\\n            value=OPENAI_CHAT_MODEL_NAMES[0],\\n            info=\\"Select the model to use\\",\\n            real_time_refresh=True,\\n        ),\\n        SecretStrInput(\\n            name=\\"api_key\\",\\n            display_name=\\"OpenAI API Key\\",\\n            info=\\"Model Provider API key\\",\\n            required=False,\\n            show=True,\\n            real_time_refresh=True,\\n        ),\\n        MessageInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input\\",\\n            info=\\"The input text to send to the model\\",\\n        ),\\n        MultilineInput(\\n            name=\\"system_message\\",\\n            display_name=\\"System Message\\",\\n            info=\\"A system message that helps set the behavior of the assistant\\",\\n            advanced=False,\\n        ),\\n        BoolInput(\\n            name=\\"stream\\",\\n            display_name=\\"Stream\\",\\n            info=\\"Whether to stream the response\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n        SliderInput(\\n            name=\\"temperature\\",\\n            display_name=\\"Temperature\\",\\n            value=0.1,\\n            info=\\"Controls randomness in responses\\",\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:\\n        provider = self.provider\\n        model_name = self.model_name\\n        temperature = self.temperature\\n        stream = self.stream\\n\\n        if provider == \\"OpenAI\\":\\n            if not self.api_key:\\n                msg = \\"OpenAI API key is required when using OpenAI provider\\"\\n                raise ValueError(msg)\\n\\n            if model_name in OPENAI_REASONING_MODEL_NAMES:\\n                # reasoning models do not support temperature (yet)\\n                temperature = None\\n\\n            return ChatOpenAI(\\n                model_name=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                openai_api_key=self.api_key,\\n            )\\n        if provider == \\"Anthropic\\":\\n            if not self.api_key:\\n                msg = \\"Anthropic API key is required when using Anthropic provider\\"\\n                raise ValueError(msg)\\n            return ChatAnthropic(\\n                model=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                anthropic_api_key=self.api_key,\\n            )\\n        if provider == \\"Google\\":\\n            if not self.api_key:\\n                msg = \\"Google API key is required when using Google provider\\"\\n                raise ValueError(msg)\\n            return ChatGoogleGenerativeAI(\\n                model=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                google_api_key=self.api_key,\\n            )\\n        msg = f\\"Unknown provider: {provider}\\"\\n        raise ValueError(msg)\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:\\n        if field_name == \\"provider\\":\\n            if field_value == \\"OpenAI\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES\\n                build_config[\\"model_name\\"][\\"value\\"] = OPENAI_CHAT_MODEL_NAMES[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"OpenAI API Key\\"\\n            elif field_value == \\"Anthropic\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = ANTHROPIC_MODELS\\n                build_config[\\"model_name\\"][\\"value\\"] = ANTHROPIC_MODELS[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"Anthropic API Key\\"\\n            elif field_value == \\"Google\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = GOOGLE_GENERATIVE_AI_MODELS\\n                build_config[\\"model_name\\"][\\"value\\"] = GOOGLE_GENERATIVE_AI_MODELS[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"Google API Key\\"\\n        elif field_name == \\"model_name\\" and field_value.startswith(\\"o1\\") and self.provider == \\"OpenAI\\":\\n            # Hide system_message for o1 models - currently unsupported\\n            if \\"system_message\\" in build_config:\\n                build_config[\\"system_message\\"][\\"show\\"] = False\\n        elif field_name == \\"model_name\\" and not field_value.startswith(\\"o1\\") and \\"system_message\\" in build_config:\\n            build_config[\\"system_message\\"][\\"show\\"] = True\\n        return build_config\\n"}, "input_value": {"_input_type": "MessageInput", "advanced": false, "display_name": "Input", "dynamic": false, "info": "The input text to send to the model", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "model_name": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Name", "dynamic": false, "info": "Select the model to use", "name": "model_name", "options": ["gpt-4o-mini", "gpt-4o", "gpt-4.1", "gpt-4.1-mini", "gpt-4.1-nano", "gpt-4.5-preview", "gpt-4-turbo", "gpt-4-turbo-preview", "gpt-4", "gpt-3.5-turbo"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "gpt-4o-mini"}, "provider": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Provider", "dynamic": false, "info": "Select the model provider", "name": "provider", "options": ["OpenAI", "Anthropic", "Google"], "options_metadata": [{"icon": "OpenAI"}, {"icon": "Anthropic"}, {"icon": "GoogleGenerativeAI"}], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "OpenAI"}, "stream": {"_input_type": "BoolInput", "advanced": true, "display_name": "Stream", "dynamic": false, "info": "Whether to stream the response", "list": false, "list_add_label": "Add More", "name": "stream", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "system_message": {"_input_type": "MultilineInput", "advanced": false, "copy_field": false, "display_name": "System Message", "dynamic": false, "info": "A system message that helps set the behavior of the assistant", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "system_message", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "temperature": {"_input_type": "SliderInput", "advanced": true, "display_name": "Temperature", "dynamic": false, "info": "Controls randomness in responses", "max_label": "", "max_label_icon": "", "min_label": "", "min_label_icon": "", "name": "temperature", "placeholder": "", "range_spec": {"max": 1, "min": 0, "step": 0.01, "step_type": "float"}, "required": false, "show": true, "slider_buttons": false, "slider_buttons_options": [], "slider_input": false, "title_case": false, "tool_mode": false, "type": "slider", "value": 0.1}}, "tool_mode": false}, "selected_output": "text_output", "showNode": true, "type": "LanguageModelComponent"}, "dragging": false, "id": "LanguageModelComponent-n8KRg", "measured": {"height": 534, "width": 320}, "position": {"x": 2726.7653522