me=\\"Template\\"),\\n        MessageTextInput(\\n            name=\\"tool_placeholder\\",\\n            display_name=\\"Tool Placeholder\\",\\n            tool_mode=True,\\n            advanced=True,\\n            info=\\"A placeholder input for tool mode.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Prompt\\", name=\\"prompt\\", method=\\"build_prompt\\"),\\n    ]\\n\\n    async def build_prompt(self) -> Message:\\n        prompt = Message.from_template(**self._attributes)\\n        self.status = prompt.text\\n        return prompt\\n\\n    def _update_template(self, frontend_node: dict):\\n        prompt_template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        custom_fields = frontend_node[\\"custom_fields\\"]\\n        frontend_node_template = frontend_node[\\"template\\"]\\n        _ = process_prompt_template(\\n            template=prompt_template,\\n            name=\\"template\\",\\n            custom_fields=custom_fields,\\n            frontend_node_template=frontend_node_template,\\n        )\\n        return frontend_node\\n\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict):\\n        \\"\\"\\"This function is called after the code validation is done.\\"\\"\\"\\n        frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        # Kept it duplicated for backwards compatibility\\n        _ = process_prompt_template(\\n            template=template,\\n            name=\\"template\\",\\n            custom_fields=frontend_node[\\"custom_fields\\"],\\n            frontend_node_template=frontend_node[\\"template\\"],\\n        )\\n        # Now that template is updated, we need to grab any values that were set in the current_frontend_node\\n        # and update the frontend_node with those values\\n        update_template_values(new_template=frontend_node, previous_template=current_frontend_node[\\"template\\"])\\n        return frontend_node\\n\\n    def _get_fallback_input(self, **kwargs):\\n        return DefaultPromptField(**kwargs)\\n"}, "input_value": {"advanced": false, "display_name": "input_value", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message", "Text"], "list": false, "load_from_db": false, "multiline": true, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": ""}, "search_results": {"advanced": false, "display_name": "search_results", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message", "Text"], "list": false, "load_from_db": false, "multiline": true, "name": "search_results", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": ""}, "template": {"_input_type": "PromptInput", "advanced": false, "display_name": "Template", "dynamic": false, "info": "", "list": false, "load_from_db": false, "name": "template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "type": "prompt", "value": "RESEARCH FINDINGS: {search_results}\\nORIGINAL QUERY: {input_value}\\n"}, "tool_placeholder": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Tool Placeholder", "dynamic": false, "info": "A placeholder input for tool mode.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "tool_placeholder", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "selected_output": "prompt", "type": "Prompt"}, "dragging": false, "height": 433, "id": "Prompt-aHVYv", "measured": {"height": 433, "width": 320}, "position": {"x": 2504.138359606453, "