\",\\n            display_name=\\"Text\\",\\n            info=\\"Text to be passed as input.\\",\\n        ),\\n    ]\\n    outputs = [\\n        Output(display_name=\\"Output Text\\", name=\\"text\\", method=\\"text_response\\"),\\n    ]\\n\\n    def text_response(self) -> Message:\\n        return Message(\\n            text=self.input_value,\\n        )\\n"}, "input_value": {"_input_type": "MultilineInput", "advanced": false, "display_name": "Text", "dynamic": false, "info": "Text to be passed as input.", "input_types": ["Message"], "list": false, "load_from_db": false, "multiline": true, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "Use the references above for style to write a new blog/tutorial about Langflow and AI. Suggest non-covered topics."}}}, "selected_output": "text", "type": "TextInput"}, "dragging": false, "height": 234, "id": "TextInput-mM5Wa", "measured": {"height": 234, "width": 320}, "position": {"x": 955.8314364398983, "y": 402.24423846638155}, "positionAbsolute": {"x": 955.8314364398983, "y": 402.24423846638155}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"description": "Display a chat message in the Playground.", "display_name": "Chat Output", "id": "ChatOutput-GOjXV", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Display a chat message in the Playground.", "display_name": "Chat Output", "documentation": "", "edited": false, "field_order": ["input_value", "store_message", "sender", "sender_name", "session_id", "data_template"], "frozen": false, "icon": "MessagesSquare", "legacy": false, "lf_version": "1.4.2", "metadata": {}, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Output Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "background_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Background Color", "dynamic": false, "info": "The background color of the icon.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "background_color", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "chat_icon": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "clean_data": {"_input_type": "BoolInput", "advanced": true, "display_name": "Basic Clean Data", "dynamic": false, "info": "Whether to clean the data", "list": false, "list_add_label": "Add More", "name": "clean_data", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from collections.abc import Generator\\nfrom typing import Any\\n\\nimport orjson\\nfrom fastapi.encoders import jsonable_encoder\\n\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.inputs.inputs import BoolInput, DropdownInput, HandleInput, MessageTextInput\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.schema.properties import Source\\nfrom langflow.template.field.base import Output\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_AI,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatOutput(ChatComponent):\\n    display_name = \\"Chat Output\\"\\n    description = \\"Display a chat message in the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-output\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatOutput\\"\\n    minimized = True\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Inputs\\",\\n            info=\\"Message to be passed as output.\\",\\n            input_types=[\\"Data\\", \\"DataFrame\\", \\"Message\\"],\\n            required=True,\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_AI,\\n            advanced=True,\\n            info=\\"Type of sender.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_AI,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"data_template\\",\\n            display_name=\\"Data Template\\",\\n            value=\\"{text}\\",\\n            advanced=True,\\n            info=\\"Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"clean_data\\",\\n            display_name=\\"Basic Clean Data\\",\\n            value=True,\\n            info=\\"Whether to clean the data\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\"Output Message\\",\\n            name=\\"message\\",\\n            method=\\"message_response\\",\\n        ),\\n    ]\\n\\n    def _build_source(self, id_: str | None, display_name: str | None, source: str | None) -> Source:\\n        source_dict = {}\\n        if id_:\\n            source_dict[\\"id\\"] = id_\\n        if display_name:\\n            source_dict[\\"display_name\\"] = display_name\\n        if source:\\n            # Handle case where source is a ChatOpenAI object\\n            if hasattr(source, \\"model_name\\"):\\n                source_dict[\\"source\\"] = source.model_name\\n            elif hasattr(source, \\"model\\"):\\n                source_dict[\\"source\\"] = str(source.model)\\n            else:\\n                source_dict[\\"source\\"] = str(source)\\n        return Source(**source_dict)\\n\\n    async def message_response(self) -> Message:\\n        # First convert the input to string if needed\\n        text = self.convert_to_string()\\n\\n        # Get source properties\\n        source, icon, display_name, source_id = self.get_properties_from_source_component()\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        if self.chat_icon:\\n            icon = self.chat_icon\\n\\n        # Create or use existing Message object\\n        if isinstance(self.input_value, Message):\\n            message = self.input_value\\n            # Update message properties\\n            message.text = text\\n        else:\\n            message = Message(text=text)\\n\\n        # Set message properties\\n        message.sender = self.sender\\n        message.sender_name = self.sender_name\\n        message.session_id = self.session_id\\n        message.flow_id = self.graph.flow_id if hasattr(self, \\"graph\\") else None\\n        message.properties.source = self._build_source(source_id, display_name, source)\\n        message.properties.icon = icon\\n        message.properties.background_color = background_color\\n        message.properties.text_color = text_color\\n\\n        # Store message if needed\\n        if self.session_id and self.should_store_message:\\n            stored_message = await self.send_message(message)\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n\\n    def _serialize_data(self, data: Data) -> str:\\n        \\"\\"\\"Serialize Data object to JSON string.\\"\\"\\"\\n        # Convert data.data to JSON-serializable format\\n        serializable_data = jsonable_encoder(data.data)\\n        # Serialize with orjson, enabling pretty printing with indentation\\n        json_bytes = orjson.dumps(serializable_data, option=orjson.OPT_INDENT_2)\\n        # Convert bytes to string and wrap in Markdown code blocks\\n        return \\"```json\\\\n\\" + json_bytes.decode(\\"utf-8\\") + \\"\\\\n```\\"\\n\\n    def _validate_input(self) -> None:\\n        \\"\\"\\"Validate the input data and raise ValueError if invalid.\\"\\"\\"\\n        if self.input_value is None:\\n            msg = \\"Input data cannot be None\\"\\n            raise ValueError(msg)\\n        if isinstance(self.input_value, list) and not all(\\n            isinstance(item, Message | Data | DataFrame | str) for item in self.input_value\\n        ):\\n            invalid_types = [\\n                type(item).__name__\\n                for item in self.input_value\\n                if not isinstance(item, Message | Data | DataFrame | str)\\n            ]\\n            msg = f\\"Expected Data or DataFrame or Message or str, got {invalid_types}\\"\\n            raise TypeError(msg)\\n        if not isinstance(\\n            self.input_value,\\n            Message | Data | DataFrame | str | list | Generator | type(None),\\n        ):\\n            type_name = type(self.input_value).__name__\\n            msg = f\\"Expected Data or DataFrame or Message or str, Generator or None, got {type_name}\\"\\n            raise TypeError(msg)\\n\\n    def convert_to_string(self) -> str | Generator[Any, None, None]:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        self._validate_input()\\n        if isinstance(self.input_value, list):\\n            return \\"\\\\n\\".join([safe_convert(item, clean_data=self.clean_data) for item in self.input_value])\\n        if isinstance(self.input_value, Generator):\\n            return self.input_value\\n        return safe_convert(self.input_value)\\n"}, "data_template": {"advanced": true, "display_name": "Data Template", "dynamic": false, "info": "Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "data_template", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "{text}"}, "input_value": {"advanced": false, "display_name": "Inputs", "dynamic": false, "info": "Message to be passed as output.", "input_types": ["Data", "DataFrame", "Message"], "list": false, "load_from_db": false, "name": "input_value", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "sender": {"advanced": true, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "str", "value": "Machine"}, "sender_name": {"advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "AI"}, "session_id": {"advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}}, "type": "ChatOutput"}, "dragging": false, "height": 234, "id": "ChatOutput-GOjXV", "measured": {"height": 234, "width": 320}, "position": {"x": 2097.489047349972, "y": 603.355618581002}, "positionAbsolute": {"x": 2113.228183852361, "y": 594.6116538574528}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"id": "note-OB8Tz", "node": {"description": "# Blog Writing Flow Overview\\n\\nCreate a blog post by using content fetched from URLs and user-provided instructions.\\n\\n## Prerequisites\\n\\n* An [OpenAI API key](https://platform.openai.com/)\\n\\n## Quickstart\\n\\n1. Paste your OpenAI API key in the **Language Model** model component.\\n2.  In the **URL** component, enter URLs you want to fetch content from. Ensure they start with `http://` or `https://`.\\n3. Open the **Playground**. A blog post is written from the content fetched by the **URL** component.", "display_name": "", "documentation": "", "template": {}}, "type": "note"}, "dragging": false, "height": 582, "id": "note-OB8Tz", "measured": {"height": 582, "width": 508}, "position": {"x": -86.00395676688996, "y": 408.833268195498}, "positionAbsolute": {"x": -78.41970365609802, "y": 405.04114164010207}, "resizing": false, "selected": false, "style": {"height": 509, "width": 562}, "type": "noteNode", "width": 507}, {"data": {"id": "ParserComponent-YRRd0", "node": {"base_classes": ["Message"], "beta": false, "category": "processing", "conditional_paths": [], "custom_fields": {}, "description": "Extracts text using a template.", "display_name": "Parser", "documentation": "", "edited": false, "field_order": ["mode", "pattern", "input_data", "sep"], "frozen": false, "icon": "braces", "key": "ParserComponent", "legacy": false, "lf_version": "1.4.2", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Parsed Text", "group_outputs": false, "method": "parse_combined_text", "name": "parsed_text", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 2.220446049250313e-16, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.custom.custom_component.component import Component\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.inputs.inputs import BoolInput, HandleInput, MessageTextInput, MultilineInput, TabInput\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.template.field.base import Output\\n\\n\\nclass ParserComponent(Component):\\n    display_name = \\"Parser\\"\\n    description = \\"Extracts text using a template.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-processing#parser\\"\\n    icon = \\"braces\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"input_data\\",\\n            display_name=\\"Data or DataFrame\\",\\n            input_types=[\\"DataFrame\\", \\"Data\\"],\\n            info=\\"Accepts either a DataFrame or a Data object.\\",\\n            required=True,\\n        ),\\n        TabInput(\\n            name=\\"mode\\",\\n            display_name=\\"Mode\\",\\n            options=[\\"Parser\\", \\"Stringify\\"],\\n            value=\\"Parser\\",\\n            info=\\"Convert into raw string instead of using a template.\\",\\n            real_time_refresh=True,\\n        ),\\n        MultilineInput(\\n            name=\\"pattern\\",\\n            display_name=\\"Template\\",\\n            info=(\\n                \\"Use variables within curly brackets to extract column values for DataFrames \\"\\n                \\"or key values for Data.\\"\\n                \\"For example: `Name: {Name}, Age: {Age}, Country: {Country}`\\"\\n            ),\\n            value=\\"Text: {text}\\",  # Example default\\n            dynamic=True,\\n            show=True,\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sep\\",\\n            display_name=\\"Separator\\",\\n            advanced=True,\\n            value=\\"\\\\n\\",\\n            info=\\"String used to separate rows/items.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\"Parsed Text\\",\\n            name=\\"parsed_text\\",\\n            info=\\"Formatted text output.\\",\\n            method=\\"parse_combined_text\\",\\n        ),\\n    ]\\n\\n    def update_build_config(self, build_config, field_value, field_name=None):\\n        \\"\\"\\"Dynamically hide/show `template` and enforce requirement based on `stringify`.\\"\\"\\"\\n        if field_name == \\"mode\\":\\n            build_config[\\"pattern\\"][\\"show\\"] = self.mode == \\"Parser\\"\\n            build_config[\\"pattern\\"][\\"required\\"] = self.mode == \\"Parser\\"\\n            if field_value:\\n                clean_data = BoolInput(\\n                    name=\\"clean_data\\",\\n                    display_name=\\"Clean Data\\",\\n                    info=(\\n                        \\"Enable to clean the data by removing empty rows and lines \\"\\n                        \\"in each cell of the DataFrame/ Data object.\\"\\n                    ),\\n                    value=True,\\n                    advanced=True,\\n                    required=False,\\n                )\\n                build_config[\\"clean_data\\"] = clean_data.to_dict()\\n            else:\\n                build_config.pop(\\"clean_data\\", None)\\n\\n        return build_config\\n\\n    def _clean_args(self):\\n        \\"\\"\\"Prepare arguments based on input type.\\"\\"\\"\\n        input_data = self.input_data\\n\\n        match input_data:\\n            case list() if all(isinstance(item, Data) for item in input_data):\\n                msg = \\"List of Data objects is not supported.\\"\\n                raise ValueError(msg)\\n            case DataFrame():\\n                return input_data, None\\n            case Data():\\n                return None, input_data\\n            case dict() if \\"data\\" in input_data:\\n                try:\\n                    if \\"columns\\" in input_data:  # Likely a DataFrame\\n                        return DataFrame.from_dict(input_data), None\\n                    # Likely a Data object\\n                    return None, Data(**input_data)\\n                except (TypeError, ValueError, KeyError) as e:\\n                    msg = f\\"Invalid structured input provided: {e!s}\\"\\n                    raise ValueError(msg) from e\\n            case _:\\n                msg = f\\"Unsupported input type: {type(input_data)}. Expected DataFrame or Data.\\"\\n                raise ValueError(msg)\\n\\n    def parse_combined_text(self) -> Message:\\n        \\"\\"\\"Parse all rows/items into a single text or convert input to string if `stringify` is enabled.\\"\\"\\"\\n        # Early return for stringify option\\n        if self.mode == \\"Stringify\\":\\n            return self.convert_to_string()\\n\\n        df, data = self._clean_args()\\n\\n        lines = []\\n        if df is not None:\\n            for _, row in df.iterrows():\\n                formatted_text = self.pattern.format(**row.to_dict())\\n                lines.append(formatted_text)\\n        elif data is not None:\\n            formatted_text = self.pattern.format(**data.data)\\n            lines.append(formatted_text)\\n\\n        combined_text = self.sep.join(lines)\\n        self.status = combined_text\\n        return Message(text=combined_text)\\n\\n    def convert_to_string(self) -> Message:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        result = \\"\\"\\n        if isinstance(self.input_data, list):\\n            result = \\"\\\\n\\".join([safe_convert(item, clean_data=self.clean_data or False) for item in self.input_data])\\n        else:\\n            result = safe_convert(self.input_data or False)\\n        self.log(f\\"Converted to string with length: {len(result)}\\")\\n\\n        message = Message(text=result)\\n        self.status = message\\n        return message\\n"}, "input_data": {"_input_type": "HandleInput", "advanced": false, "display_name": "Data or DataFrame", "dynamic": false, "info": "Accepts either a DataFrame or a Data object.", "input_types": ["DataFrame", "Data"], "list": false, "list_add_label": "Add More", "name": "input_data", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "mode": {"_input_type": "TabInput", "advanced": false, "display_name": "Mode", "dynamic": false, "info": "Convert into raw string instead of using a template.", "name": "mode", "options": ["Parser", "Stringify"], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tab", "value": "Parser"}, "pattern": {"_input_type": "MultilineInput", "advanced": false, "copy_field": false, "display_name": "Template", "dynamic": true, "info": "Use variables within curly brackets to extract column values for DataFrames or key values for Data.For example: `Name: {Name}, Age: {Age}, Country: {Country}`", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "pattern", "placeholder": "", "required": true, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "Text: {text}"}, "sep": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Separator", "dynamic": false, "info": "String used to separate rows/items.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sep", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "\\n"}}, "tool_mode": false}, "selected_output": "parsed_text", "showNode": true, "type": "ParserComponent"}, "dragging": false, "id": "ParserComponent-YRRd0", "measured": {"height": 329, "width": 320}, "position": {"x": 947.8993250761185, "y": 715.4566338975391}, "selected": false, "type": "genericNode"}, {"data": {"id": "URLComponent-DFXG5", "node": {"base_classes": ["DataFrame"], "beta": false, "category": "data", "conditional_paths": [], "custom_fields": {}, "description": "Fetch content from one or more web pages, following links recursively.", "display_name": "URL", "documentation": "", "edited": false, "field_order": ["urls", "max_depth", "prevent_outside", "use_async", "format", "timeout", "headers", "filter_text_html", "continue_on_failure", "check_response_status", "autoset_encoding"], "frozen": false, "icon": "layout-template", "key": "URLComponent", "legacy": false, "lf_version": "1.4.2", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Extracted Pages", "group_outputs": false, "method": "fetch_content", "name": "page_results", "selected": "DataFrame", "tool_mode": true, "types": ["DataFrame"], "value": "__UNDEFINED__"}, {"allows_loop": false, "cache": true, "display_name": "Raw Content", "group_outputs": false, "method": "fetch_content_as_message", "name": "raw_results", "selected": "Message", "tool_mode": false, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 2.220446049250313e-16, "template": {"_type": "Component", "autoset_encoding": {"_input_type": "BoolInput", "advanced": true, "display_name": "Autoset Encoding", "dynamic": false, "info": "If enabled, automatically sets the encoding of the request.", "list": false, "list_add_label": "Add More", "name": "autoset_encoding", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "check_response_status": {"_input_type": "BoolInput", "advanced": true, "display_name": "Check Response Status", "dynamic": false, "info": "If enabled, checks the response status of the request.", "list": false, "list_add_label": "Add More", "name": "check_response_status", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import re\\n\\nimport requests\\nfrom bs4 import BeautifulSoup\\nfrom langchain_community.document_loaders import RecursiveUrlLoader\\nfrom loguru import logger\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.io import BoolInput, DropdownInput, IntInput, MessageTextInput, Output, SliderInput, TableInput\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.services.deps import get_settings_service\\n\\n# Constants\\nDEFAULT_TIMEOUT = 30\\nDEFAULT_MAX_DEPTH = 1\\nDEFAULT_FORMAT = \\"Text\\"\\nURL_REGEX = re.compile(\\n    r\\"^(https?:\\\\/\\\\/)?\\" r\\"(www\\\\.)?\\" r\\"([a-zA-Z0-9.-]+)\\" r\\"(\\\\.[a-zA-Z]{2,})?\\" r\\"(:\\\\d+)?\\" r\\"(\\\\/[^\\\\s]*)?$\\",\\n    re.IGNORECASE,\\n)\\n\\n\\nclass URLComponent(Component):\\n    \\"\\"\\"A component that loads and parses content from web pages recursively.\\n\\n    This component allows fetching content from one or more URLs, with options to:\\n    - Control crawl depth\\n    - Prevent crawling outside the root domain\\n    - Use async loading for better performance\\n    - Extract either raw HTML or clean text\\n    - Configure request headers and timeouts\\n    \\"\\"\\"\\n\\n    display_name = \\"URL\\"\\n    description = \\"Fetch content from one or more web pages, following links recursively.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-data#url\\"\\n    icon = \\"layout-template\\"\\n    name = \\"URLComponent\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\"urls\\",\\n            display_name=\\"URLs\\",\\n            info=\\"Enter one or more URLs to crawl recursively, by clicking the '+' button.\\",\\n            is_list=True,\\n            tool_mode=True,\\n            placeholder=\\"Enter a URL...\\",\\n            list_add_label=\\"Add URL\\",\\n            input_types=[],\\n        ),\\n        SliderInput(\\n            name=\\"max_depth\\",\\n            display_name=\\"Depth\\",\\n            info=(\\n                \\"Controls how many 'clicks' away from the initial page the crawler will go:\\\\n\\"\\n                \\"- depth 1: only the initial page\\\\n\\"\\n                \\"- depth 2: initial page + all pages linked directly from it\\\\n\\"\\n                \\"- depth 3: initial page + direct links + links found on those direct link pages\\\\n\\"\\n                \\"Note: This is about link traversal, not URL path depth.\\"\\n            ),\\n            value=DEFAULT_MAX_DEPTH,\\n            range_spec=RangeSpec(min=1, max=5, step=1),\\n            required=False,\\n            min_label=\\" \\",\\n            max_label=\\" \\",\\n            min_label_icon=\\"None\\",\\n            max_label_icon=\\"None\\",\\n            # slider_input=True\\n        ),\\n        BoolInput(\\n            name=\\"prevent_outside\\",\\n            display_name=\\"Prevent Outside\\",\\n            info=(\\n                \\"If enabled, only crawls URLs within the same domain as the root URL. \\"\\n                \\"This helps prevent the crawler from going to external websites.\\"\\n            ),\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"use_async\\",\\n            display_name=\\"Use Async\\",\\n            info=(\\n                \\"If enabled, uses asynchronous loading which can be significantly faster \\"\\n                \\"but might use more system resources.\\"\\n            ),\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"format\\",\\n            display_name=\\"Output Format\\",\\n            info=\\"Output Format. Use 'Text' to extract the text from the HTML or 'HTML' for the raw HTML content.\\",\\n            options=[\\"Text\\", \\"HTML\\"],\\n            value=DEFAULT_FORMAT,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\"timeout\\",\\n            display_name=\\"Timeout\\",\\n            info=\\"Timeout for the request in seconds.\\",\\n            value=DEFAULT_TIMEOUT,\\n            required=False,\\n            advanced=True,\\n        ),\\n        TableInput(\\n            name=\\"headers\\",\\n            display_name=\\"Headers\\",\\n            info=\\"The headers to send with the request\\",\\n            table_schema=[\\n                {\\n                    \\"name\\": \\"key\\",\\n                    \\"display_name\\": \\"Header\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Header name\\",\\n                },\\n                {\\n                    \\"name\\": \\"value\\",\\n                    \\"display_name\\": \\"Value\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Header value\\",\\n                },\\n            ],\\n            value=[{\\"key\\": \\"User-Agent\\", \\"value\\": get_settings_service().settings.user_agent}],\\n            advanced=True,\\n            input_types=[\\"DataFrame\\"],\\n        ),\\n        BoolInput(\\n            name=\\"filter_text_html\\",\\n            display_name=\\"Filter Text/HTML\\",\\n            info=\\"If enabled, filters out text/css content type from the results.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"continue_on_failure\\",\\n            display_name=\\"Continue on Failure\\",\\n            info=\\"If enabled, continues crawling even if some requests fail.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"check_response_status\\",\\n            display_name=\\"Check Response Status\\",\\n            info=\\"If enabled, checks the response status of the request.\\",\\n            value=False,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"autoset_encoding\\",\\n            display_name=\\"Autoset Encoding\\",\\n            info=\\"If enabled, automatically sets the encoding of the request.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Extracted Pages\\", name=\\"page_results\\", method=\\"fetch_content\\"),\\n        Output(display_name=\\"Raw Content\\", name=\\"raw_results\\", method=\\"fetch_content_as_message\\", tool_mode=False),\\n    ]\\n\\n    @staticmethod\\n    def validate_url(url: str) -> bool:\\n        \\"\\"\\"Validates if the given string matches URL pattern.\\n\\n        Args:\\n            url: The URL string to validate\\n\\n        Returns:\\n            bool: True if the URL is valid, False otherwise\\n        \\"\\"\\"\\n        return bool(URL_REGEX.match(url))\\n\\n    def ensure_url(self, url: str) -> str:\\n        \\"\\"\\"Ensures the given string is a valid URL.\\n\\n        Args:\\n            url: The URL string to validate and normalize\\n\\n        Returns:\\n            str: The normalized URL\\n\\n        Raises:\\n            ValueError: If the URL is invalid\\n        \\"\\"\\"\\n        url = url.strip()\\n        if not url.startswith((\\"http://\\", \\"https://\\")):\\n            url = \\"https://\\" + url\\n\\n        if not self.validate_url(url):\\n            msg = f\\"Invalid URL: {url}\\"\\n            raise ValueError(msg)\\n\\n        return url\\n\\n    def _create_loader(self, url: str) -> RecursiveUrlLoader:\\n        \\"\\"\\"Creates a RecursiveUrlLoader instance with the configured settings.\\n\\n        Args:\\n            url: The URL to load\\n\\n        Returns:\\n            RecursiveUrlLoader: Configured loader instance\\n        \\"\\"\\"\\n        headers_dict = {header[\\"key\\"]: header[\\"value\\"] for header in self.headers}\\n        extractor = (lambda x: x) if self.format == \\"HTML\\" else (lambda x: BeautifulSoup(x, \\"lxml\\").get_text())\\n\\n        return RecursiveUrlLoader(\\n            url=url,\\n            max_depth=self.max_depth,\\n            prevent_outside=self.prevent_outside,\\n            use_async=self.use_async,\\n            extractor=extractor,\\n            timeout=self.timeout,\\n            headers=headers_dict,\\n            check_response_status=self.check_response_status,\\n            continue_on_failure=self.continue_on_failure,\\n            base_url=url,  # Add base_url to ensure consistent domain crawling\\n            autoset_encoding=self.autoset_encoding,  # Enable automatic encoding detection\\n            exclude_dirs=[],  # Allow customization of excluded directories\\n            link_regex=None,  # Allow customization of link filtering\\n        )\\n\\n    def fetch_url_contents(self) -> list[dict]:\\n        \\"\\"\\"Load documents from the configured URLs.\\n\\n        Returns:\\n            List[Data]: List of Data objects containing the fetched content\\n\\n        Raises:\\n            ValueError: If no valid URLs are provided or if there's an error loading documents\\n        \\"\\"\\"\\n        try:\\n            urls = list({self.ensure_url(url) for url in self.urls if url.strip()})\\n            logger.debug(f\\"URLs: {urls}\\")\\n            if not urls:\\n                msg = \\"No valid URLs provided.\\"\\n                raise ValueError(msg)\\n\\n            all_docs = []\\n            for url in urls:\\n                logger.debug(f\\"Loading documents from {url}\\")\\n\\n                try:\\n                    loader = self._create_loader(url)\\n                    docs = loader.load()\\n\\n                    if not docs:\\n                        logger.warning(f\\"No documents found for {url}\\")\\n                        continue\\n\\n                    logger.debug(f\\"Found {len(docs)} documents from {url}\\")\\n                    all_docs.extend(docs)\\n\\n                except requests.exceptions.RequestException as e:\\n                    logger.exception(f\\"Error loading documents from {url}: {e}\\")\\n                    continue\\n\\n            if not all_docs:\\n                msg = \\"No documents were successfully loaded from any URL\\"\\n                raise ValueError(msg)\\n\\n            # data = [Data(text=doc.page_content, **doc.metadata) for doc in all_docs]\\n            data = [\\n                {\\n                    \\"text\\": safe_convert(doc.page_content, clean_data=True),\\n                    \\"url\\": doc.metadata.get(\\"source\\", \\"\\"),\\n                    \\"title\\": doc.metadata.get(\\"title\\", \\"\\"),\\n                    \\"description\\": doc.metadata.get(\\"description\\", \\"\\"),\\n                    \\"content_type\\": doc.metadata.get(\\"content_type\\", \\"\\"),\\n                    \\"language\\": doc.metadata.get(\\"language\\", \\"\\"),\\n                }\\n                for doc in all_docs\\n            ]\\n        except Exception as e:\\n            error_msg = e.message if hasattr(e, \\"message\\") else e\\n            msg = f\\"Error loading documents: {error_msg!s}\\"\\n            logger.exception(msg)\\n            raise ValueError(msg) from e\\n        return data\\n\\n    def fetch_content(self) -> DataFrame:\\n        \\"\\"\\"Convert the documents to a DataFrame.\\"\\"\\"\\n        return DataFrame(data=self.fetch_url_contents())\\n\\n    def fetch_content_as_message(self) -> Message:\\n        \\"\\"\\"Convert the documents to a Message.\\"\\"\\"\\n        url_contents = self.fetch_url_contents()\\n        return Message(text=\\"\\\\n\\\\n\\".join([x[\\"text\\"] for x in url_contents]), data={\\"data\\": url_contents})\\n"}, "continue_on_failure": {"_input_type": "BoolInput", "advanced": true, "display_name": "Continue on Failure", "dynamic": false, "info": "If enabled, continues crawling even if some requests fail.", "list": false, "list_add_label": "Add More", "name": "continue_on_failure", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "filter_text_html": {"_input_type": "BoolInput", "advanced": true, "display_name": "Filter Text/HTML", "dynamic": false, "info": "If enabled, filters out text/css content type from the results.", "list": false, "list_add_label": "Add More", "name": "filter_text_html", "placeholder": "", "required": false, "