alse, "conditional_paths": [], "custom_fields": {}, "description": "Extracts structured data from a web page using an AgentQL query or a Natural Language description.", "display_name": "Extract Web Data", "documentation": "https://docs.agentql.com/rest-api/api-reference", "edited": false, "field_order": ["api_key", "url", "query", "prompt", "is_stealth_mode_enabled", "timeout", "mode", "wait_for", "is_scroll_to_bottom_enabled", "is_screenshot_enabled"], "frozen": false, "icon": "AgentQL", "legacy": false, "lf_version": "1.4.3", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Toolset", "group_outputs": false, "hidden": null, "method": "to_toolkit", "name": "component_as_tool", "options": null, "required_inputs": null, "selected": "Tool", "tool_mode": true, "types": ["Tool"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "API Key", "dynamic": false, "info": "Your AgentQL API key from dev.agentql.com", "input_types": [], "load_from_db": false, "name": "api_key", "password": true, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "str", "value": ""}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import httpx\\nfrom loguru import logger\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.io import (\\n    BoolInput,\\n    DropdownInput,\\n    IntInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n    SecretStrInput,\\n)\\nfrom langflow.schema.data import Data\\n\\n\\nclass AgentQL(Component):\\n    display_name = \\"Extract Web Data\\"\\n    description = \\"Extracts structured data from a web page using an AgentQL query or a Natural Language description.\\"\\n    documentation: str = \\"https://docs.agentql.com/rest-api/api-reference\\"\\n    icon = \\"AgentQL\\"\\n    name = \\"AgentQL\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\"api_key\\",\\n            display_name=\\"API Key\\",\\n            required=True,\\n            password=True,\\n            info=\\"Your AgentQL API key from dev.agentql.com\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"url\\",\\n            display_name=\\"URL\\",\\n            required=True,\\n            info=\\"The URL of the public web page you want to extract data from.\\",\\n            tool_mode=True,\\n        ),\\n        MultilineInput(\\n            name=\\"query\\",\\n            display_name=\\"AgentQL Query\\",\\n            required=False,\\n            info=\\"The AgentQL query to execute. Learn more at https://docs.agentql.com/agentql-query or use a prompt.\\",\\n            tool_mode=True,\\n        ),\\n        MultilineInput(\\n            name=\\"prompt\\",\\n            display_name=\\"Prompt\\",\\n            required=False,\\n            info=\\"A Natural Language description of the data to extract from the page. Alternative to AgentQL query.\\",\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\"is_stealth_mode_enabled\\",\\n            display_name=\\"Enable Stealth Mode (Beta)\\",\\n            info=\\"Enable experimental anti-bot evasion strategies. May not work for all websites at all times.\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\"timeout\\",\\n            display_name=\\"Timeout\\",\\n            info=\\"Seconds to wait for a request.\\",\\n            value=900,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"mode\\",\\n            display_name=\\"Request Mode\\",\\n            info=\\"'standard' uses deep data analysis, while 'fast' trades some depth of analysis for speed.\\",\\n            options=[\\"fast\\", \\"standard\\"],\\n            value=\\"fast\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\"wait_for\\",\\n            display_name=\\"Wait For\\",\\n            info=\\"Seconds to wait for the page to load before extracting data.\\",\\n            value=0,\\n            range_spec=RangeSpec(min=0, max=10, step_type=\\"int\\"),\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"is_scroll_to_bottom_enabled\\",\\n            display_name=\\"Enable scroll to bottom\\",\\n            info=\\"Scroll to bottom of the page before extracting data.\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"is_screenshot_enabled\\",\\n            display_name=\\"Enable screenshot\\",\\n            info=\\"Take a screenshot before extracting data. Returned in 'metadata' as a Base64 string.\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Data\\", name=\\"data\\", method=\\"build_output\\"),\\n    ]\\n\\n    def build_output(self) -> Data:\\n        endpoint = \\"https://api.agentql.com/v1/query-data\\"\\n        headers = {\\n            \\"X-API-Key\\": self.api_key,\\n            \\"Content-Type\\": \\"application/json\\",\\n            \\"X-TF-Request-Origin\\": \\"langflow\\",\\n        }\\n\\n        payload = {\\n            \\"url\\": self.url,\\n            \\"query\\": self.query,\\n            \\"prompt\\": self.prompt,\\n            \\"params\\": {\\n                \\"mode\\": self.mode,\\n                \\"wait_for\\": self.wait_for,\\n                \\"is_scroll_to_bottom_enabled\\": self.is_scroll_to_bottom_enabled,\\n                \\"is_screenshot_enabled\\": self.is_screenshot_enabled,\\n            },\\n            \\"metadata\\": {\\n                \\"experimental_stealth_mode_enabled\\": self.is_stealth_mode_enabled,\\n            },\\n        }\\n\\n        if not self.prompt and not self.query:\\n            self.status = \\"Either Query or Prompt must be provided.\\"\\n            raise ValueError(self.status)\\n        if self.prompt and self.query:\\n            self.status = \\"Both Query and Prompt can't be provided at the same time.\\"\\n            raise ValueError(self.status)\\n\\n        try:\\n            response = httpx.post(endpoint, headers=headers, json=payload, timeout=self.timeout)\\n            response.raise_for_status()\\n\\n            json = response.json()\\n            data = Data(result=json[\\"data\\"], metadata=json[\\"metadata\\"])\\n\\n        except httpx.HTTPStatusError as e:\\n            response = e.response\\n            if response.status_code == httpx.codes.UNAUTHORIZED:\\n                self.status = \\"Please, provide a valid API Key. You can create one at https://dev.agentql.com.\\"\\n            else:\\n                try:\\n                    error_json = response.json()\\n                    logger.error(\\n                        f\\"Failure response: '{response.status_code} {response.reason_phrase}' with body: {error_json}\\"\\n                    )\\n                    msg = error_json[\\"error_info\\"] if \\"error_info\\" in error_json else error_json[\\"detail\\"]\\n                except (ValueError, TypeError):\\n                    msg = f\\"HTTP {e}.\\"\\n                self.status = msg\\n            raise ValueError(self.status) from e\\n\\n        else:\\n            self.status = data\\n            return data\\n"}, "is_screenshot_enabled": {"_input_type": "BoolInput", "advanced": true, "display_name": "Enable screenshot", "dynamic": false, "info": "Take a screenshot before extracting data. Returned in 'metadata' as a Base64 string.", "list": false, 