"method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 0.0020353564437605998, "template": {"_type": "Component", "background_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Background Color", "dynamic": false, "info": "The background color of the icon.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "background_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "chat_icon": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.base.data.utils import IMG_FILE_TYPES, TEXT_FILE_TYPES\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.inputs.inputs import BoolInput\\nfrom langflow.io import (\\n    DropdownInput,\\n    FileInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n)\\nfrom langflow.schema.message import Message\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_USER,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatInput(ChatComponent):\\n    display_name = \\"Chat Input\\"\\n    description = \\"Get chat inputs from the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-input\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatInput\\"\\n    minimized = True\\n\\n    inputs = [\\n        MultilineInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input Text\\",\\n            value=\\"\\",\\n            info=\\"Message to be passed as input.\\",\\n            input_types=[],\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_USER,\\n            info=\\"Type of sender.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_USER,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        FileInput(\\n            name=\\"files\\",\\n            display_name=\\"Files\\",\\n            file_types=TEXT_FILE_TYPES + IMG_FILE_TYPES,\\n            info=\\"Files to be sent with the message.\\",\\n            advanced=True,\\n            is_list=True,\\n            temp_file=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(display_name=\\"Chat Message\\", name=\\"message\\", method=\\"message_response\\"),\\n    ]\\n\\n    async def message_response(self) -> Message:\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        icon = self.chat_icon\\n\\n        message = await Message.create(\\n            text=self.input_value,\\n            sender=self.sender,\\n            sender_name=self.sender_name,\\n            session_id=self.session_id,\\n            files=self.files,\\n            properties={\\n                \\"background_color\\": background_color,\\n                \\"text_color\\": text_color,\\n                \\"icon\\": icon,\\n            },\\n        )\\n        if self.session_id and isinstance(message, Message) and self.should_store_message:\\n            stored_message = await self.send_message(\\n                message,\\n            )\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n"}, "files": {"_input_type": "FileInput", "advanced": true, "display_name": "Files", "dynamic": false, "fileTypes": ["txt", "md", "mdx", "csv", "json", "yaml", "yml", "xml", "html", "htm", "pdf", "docx", "py", "sh", "sql", "js", "ts", "tsx", "jpg", "jpeg", "png", "bmp", "image"], "file_path": "", "info": "Files to be sent with the message.", "list": true, "list_add_label": "Add More", "name": "files", "placeholder": "", "required": false, "show": true, "temp_file": true, "title_case": false, "trace_as_metadata": true, "type": "file", "value": ""}, "input_value": {"_input_type": "MultilineInput", "advanced": false, "display_name": "Input Text", "dynamic": false, "info": "Message to be passed as input.", "input_types": [], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "In 2022, the company demonstrated strong financial performance, reporting a gross profit of $1.2 billion, reflecting stable revenue generation and effective cost management. The EBITDA stood at $900 million, highlighting the company\\u2019s solid operational efficiency and profitability before interest, taxes, depreciation, and amortization. Despite a slight increase in operating expenses compared to 2021, the company maintained a healthy bottom line, achieving a net income of $500 million. This growth underscores the company\\u2019s ability to navigate economic challenges while sustaining profitability, reinforcing its financial stability and competitive position in the market."}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "User"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "User"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "list_add_label": "Add More", "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "selected_output": "message", "showNode": false, "type": "ChatInput"}, "dragging": false, "id": "ChatInput-VaLgK", "measured": {"height": 48, "width": 192}, "position": {"x": 866.761331501802, "y": 581.619639019103}, "selected": false, "type": "genericNode"}, {"data": {"id": "note-O8fhi", "node": {"description": "### \\ud83d\\udca1 Add your OpenAI API key here", "display_name": "", "documentation": "", "template": {"backgroundColor": "transparent"}}, "type": "note"}, "dragging": false, "id": "note-O8fhi", "measured": {"height": 324, "width": 324}, "position": {"x": 905.0310846743869, "y": -389.43902326187924}, "selected": false, "type": "noteNode"}, {"data": {"id": "note-2715s", "node": {"description": "\\n# Financial Report Parser\\n\\nThis template extracts key financial metrics from a given financial report text using OpenAI's GPT-4o-mini model. The extracted data is structured and formatted for chat consumption.\\n\\n## Prerequisites\\n\\n- **[OpenAI API Key](https://platform.openai.com/)**\\n\\n## Quickstart\\n\\n1. Add your OpenAI API key to the Language model.\\n2. To run the flow, click **Playground**.\\nThe **Chat Input** component in this template is pre-loaded with a sample financial report for demonstrating how structured data is extracted.\\n\\n* The **Language Model** model component identifies and retrieves Gross Profit, EBITDA, Net Income, and Operating Expenses from the financial report.\\n* The **Structured Output** component formats extracted data into a structured format for better readability and further processing.\\n* The **Parser** component converts extracted data into formatted messages for chat consumption.\\n\\n\\n\\n\\n\\n", "display_name": "", "documentation": "", "template": {}}, "type": "note"}, "dragging": false, "height": 688, "id": "note-2715s", "measured": {"height": 688, "width": 620}, "position": {"x": 270.9912976390468, "y": -396.43811550696176}, "resizing": false, "selected": false, "type": "noteNode", "width": 619}, {"data": {"id": "parser-ZMjjt", "node": {"base_classes": ["Message"], "beta": false, "category": "processing", "conditional_paths": [], "custom_fields": {}, "description": "Format a DataFrame or Data object into text using a template. Enable 'Stringify' to convert input into a readable string instead.", "display_name": "Parser", "documentation": "", "edited": false, "field_order": ["mode", "pattern", "input_data", "sep"], "frozen": false, "icon": "braces", "key": "parser", "legacy": false, "lf_version": "1.4.3", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Parsed Text", "hidden": false, "method": "parse_combined_text", "name": "parsed_text", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 2.220446049250313e-16, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import json\\nfrom typing import Any\\n\\nfrom langflow.custom import Component\\nfrom langflow.io import (\\n    BoolInput,\\n    HandleInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n    TabInput,\\n)\\nfrom langflow.schema import Data, DataFrame\\nfrom langflow.schema.message import Message\\n\\n\\nclass ParserComponent(Component):\\n    name = \\"parser\\"\\n    display_name = \\"Parser\\"\\n    description = (\\n        \\"Format a DataFrame or Data object into text using a template. \\"\\n        \\"Enable 'Stringify' to convert input into a readable string instead.\\"\\n    )\\n    icon = \\"braces\\"\\n\\n    inputs = [\\n        TabInput(\\n            name=\\"mode\\",\\n            display_name=\\"Mode\\",\\n            options=[\\"Parser\\", \\"Stringify\\"],\\n            value=\\"Parser\\",\\n            info=\\"Convert into raw string instead of using a template.\\",\\n            real_time_refresh=True,\\n        ),\\n        MultilineInput(\\n            name=\\"pattern\\",\\n            display_name=\\"Template\\",\\n            info=(\\n                \\"Use variables within curly brackets to extract column values for DataFrames \\"\\n                \\"or key values for Data.\\"\\n                \\"For example: `Name: {Name}, Age: {Age}, Country: {Country}`\\"\\n            ),\\n            value=\\"Text: {text}\\",  # Example default\\n            dynamic=True,\\n            show=True,\\n            required=True,\\n        ),\\n        HandleInput(\\n            name=\\"input_data\\",\\n            display_name=\\"Data or DataFrame\\",\\n            input_types=[\\"DataFrame\\", \\"Data\\"],\\n            info=\\"Accepts either a DataFrame or a Data object.\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sep\\",\\n            display_name=\\"Separator\\",\\n            advanced=True,\\n            value=\\"\\\\n\\",\\n            info=\\"String used to separate rows/items.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\"Parsed Text\\",\\n            name=\\"parsed_text\\",\\n            info=\\"Formatted text output.\\",\\n            method=\\"parse_combined_text\\",\\n        ),\\n    ]\\n\\n    def update_build_config(self, build_config, field_value, field_name=None):\\n        \\"\\"\\"Dynamically hide/show `template` and enforce requirement based on `stringify`.\\"\\"\\"\\n        if field_name == \\"mode\\":\\n            build_config[\\"pattern\\"][\\"show\\"] = self.mode == \\"Parser\\"\\n            build_config[\\"pattern\\"][\\"required\\"] = self.mode == \\"Parser\\"\\n            if field_value:\\n                clean_data = BoolInput(\\n                    name=\\"clean_data\\",\\n                    display_name=\\"Clean Data\\",\\n                    info=(\\n                        \\"Enable to clean the data by removing empty rows and lines \\"\\n                        \\"in each cell of the DataFrame/ Data object.\\"\\n                    ),\\n                    value=True,\\n                    advanced=True,\\n                    required=False,\\n                )\\n                build_config[\\"clean_data\\"] = clean_data.to_dict()\\n            else:\\n                build_config.pop(\\"clean_data\\", None)\\n\\n        return build_config\\n\\n    def _clean_args(self):\\n        \\"\\"\\"Prepare arguments based on input type.\\"\\"\\"\\n        input_data = self.input_data\\n\\n        match input_data:\\n            case list() if all(isinstance(item, Data) for item in input_data):\\n                msg = \\"List of Data objects is not supported.\\"\\n                raise ValueError(msg)\\n            case DataFrame():\\n                return input_data, None\\n            case Data():\\n                return None, input_data\\n            case dict() if \\"data\\" in input_data:\\n                try:\\n                    if \\"columns\\" in input_data:  # Likely a DataFrame\\n                        return DataFrame.from_dict(input_data), None\\n                    # Likely a Data object\\n                    return None, Data(**input_data)\\n                except (TypeError, ValueError, KeyError) as e:\\n                    msg = f\\"Invalid structured input provided: {e!s}\\"\\n                    raise ValueError(msg) from e\\n            case _:\\n                msg = f\\"Unsupported input type: {type(input_data)}. Expected DataFrame or Data.\\"\\n                raise ValueError(msg)\\n\\n    def parse_combined_text(self) -> Message:\\n        \\"\\"\\"Parse all rows/items into a single text or convert input to string if `stringify` is enabled.\\"\\"\\"\\n        # Early return for stringify option\\n        if self.mode == \\"Stringify\\":\\n            return self.convert_to_string()\\n\\n        df, data = self._clean_args()\\n\\n        lines = []\\n        if df is not None:\\n            for _, row in df.iterrows():\\n                formatted_text = self.pattern.format(**row.to_dict())\\n                lines.append(formatted_text)\\n        elif data is not None:\\n            formatted_text = self.pattern.format(**data.data)\\n            lines.append(formatted_text)\\n\\n        combined_text = self.sep.join(lines)\\n        self.status = combined_text\\n        return Message(text=combined_text)\\n\\n    def _safe_convert(self, data: Any) -> str:\\n        \\"\\"\\"Safely convert input data to string.\\"\\"\\"\\n        try:\\n            if isinstance(data, str):\\n                return data\\n            if isinstance(data, Message):\\n                return data.get_text()\\n            if isinstance(data, Data):\\n                return json.dumps(data.data)\\n            if isinstance(data, DataFrame):\\n                if hasattr(self, \\"clean_data\\") and self.clean_data:\\n                    # Remove empty rows\\n                    data = data.dropna(how=\\"all\\")\\n                    # Remove empty lines in each cell\\n                    data = data.replace(r\\"^\\\\s*$\\", \\"\\", regex=True)\\n                    # Replace multiple newlines with a single newline\\n                    data = data.replace(r\\"\\\\n+\\", \\"\\\\n\\", regex=True)\\n                return data.to_markdown(index=False)\\n            return str(data)\\n        except (ValueError, TypeError, AttributeError) as e:\\n            msg = f\\"Error converting data: {e!s}\\"\\n            raise ValueError(msg) from e\\n\\n    def convert_to_string(self) -> Message:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        result = \\"\\"\\n        if isinstance(self.input_data, list):\\n            result = \\"\\\\n\\".join([self._safe_convert(item) for item in self.input_data])\\n        else:\\n            result = self._safe_convert(self.input_data)\\n        self.log(f\\"Converted to string with length: {len(result)}\\")\\n\\n        message = Message(text=result)\\n        self.status = message\\n        return message\\n"}, "input_data": {"_input_type": "HandleInput", "advanced": false, "display_name": "Data or DataFrame", "dynamic": false, "info": "Accepts either a DataFrame or a Data object.", "input_types": ["DataFrame", "Data"], "list": false, "list_add_label": "Add More", "name": "input_data", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "mode": {"_input_type": "TabInput", "advanced": false, "display_name": "Mode", "dynamic": false, "info": "Convert into raw string instead of using a template.", "name": "mode", "options": ["Parser", "Stringify"], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tab", "value": "Parser"}, "pattern": {"_input_type": "MultilineInput", "advanced": false, "copy_field": false, "display_name": "Template", "dynamic": true, "info": "Use variables within curly brackets to extract column values for DataFrames or key values for Data.For example: `Name: {Name}, Age: {Age}, Country: {Country}`", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "pattern", "placeholder": "", "required": true, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "EBITDA: {EBITDA}  ,  Net Income: {NET_INCOME} , GROSS_PROFIT: {GROSS_PROFIT}"}, "sep": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Separator", "dynamic": false, "info": "String used to separate rows/items.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sep", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "\\n"}}, "tool_mode": false}, "showNode": true, "type": "parser"}, "dragging": false, "id": "parser-ZMjjt", "measured": {"height": 360, "width": 320}, "position": {"x": 1765.290752395121, "y": 164.78283431885177}, "selected": true, "type": "genericNode"}, {"data": {"id": "LanguageModelComponent-jtKdb", "node": {"base_classes": ["LanguageModel", "Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Runs a language model given a specified provider. ", "display_name": "Language Model", "documentation": "", "edited": false, "field_order": ["provider", "model_name", "api_key", "input_value", "system_message", "stream", "temperature"], "frozen": false, "icon": "brain-circuit", "legacy": false, "lf_version": "1.4.3", "metadata": {"keywords": ["model", "llm", "language model", "large language model"]}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Model Response", "group_outputs": false, "method": "text_response", "name": "text_output", "selected": null, "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}, {"allows_loop": false, "cache": true, "display_name": "Language Model", "group_outputs": false, "method": "build_model", "name": "model_output", "selected": "LanguageModel", "tool_mode": true, "types": ["LanguageModel"], "value": "__UNDEFINED__"}], "pinned": false, "priority": 0, "template": {"_type": "Component", "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "OpenAI API Key", "dynamic": false, "info": "Model Provider API key", "input_types": [], "load_from_db": true, "name": "api_key", "password": true, "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "type": "str", "value": "OPENAI_API_KEY"}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from typing import Any\\n\\nfrom langchain_anthropic import ChatAnthropic\\nfrom langchain_google_genai import ChatGoogleGenerativeAI\\nfrom langchain_openai import ChatOpenAI\\n\\nfrom langflow.base.models.anthropic_constants import ANTHROPIC_MODELS\\nfrom langflow.base.models.google_generative_ai_constants import GOOGLE_GENERATIVE_AI_MODELS\\nfrom langflow.base.models.model import LCModelComponent\\nfrom langflow.base.models.openai_constants import OPENAI_CHAT_MODEL_NAMES, OPENAI_REASONING_MODEL_NAMES\\nfrom langflow.field_typing import LanguageModel\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.inputs.inputs import BoolInput\\nfrom langflow.io import DropdownInput, MessageInput, MultilineInput, SecretStrInput, SliderInput\\nfrom langflow.schema.dotdict import dotdict\\n\\n\\nclass LanguageModelComponent(LCModelComponent):\\n    display_name = \\"Language Model\\"\\n    description = \\"Runs a language model given a specified provider.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-models\\"\\n    icon = \\"brain-circuit\\"\\n    category = \\"models\\"\\n    priority = 0  # Set priority to 0 to make it appear first\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\"provider\\",\\n            display_name=\\"Model Provider\\",\\n            options=[\\"OpenAI\\", \\"Anthropic\\", \\"Google\\"],\\n            value=\\"OpenAI\\",\\n            info=\\"Select the model provider\\",\\n            real_time_refresh=True,\\n            options_metadata=[{\\"icon\\": \\"OpenAI\\"}, {\\"icon\\": \\"Anthropic\\"}, {\\"icon\\": \\"GoogleGenerativeAI\\"}],\\n        ),\\n        DropdownInput(\\n            name=\\"model_name\\",\\n            display_name=\\"Model Name\\",\\n            options=OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES,\\n            value=OPENAI_CHAT_MODEL_NAMES[0],\\n            info=\\"Select the model to use\\",\\n            real_time_refresh=True,\\n        ),\\n        SecretStrInput(\\n            name=\\"api_key\\",\\n            display_name=\\"OpenAI API Key\\",\\n            info=\\"Model Provider API key\\",\\n            required=False,\\n            show=True,\\n            real_time_refresh=True,\\n        ),\\n        MessageInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Input\\",\\n            info=\\"The input text to send to the model\\",\\n        ),\\n        MultilineInput(\\n            name=\\"system_message\\",\\n            display_name=\\"System Message\\",\\n            info=\\"A system message that helps set the behavior of the assistant\\",\\n            advanced=False,\\n        ),\\n        BoolInput(\\n            name=\\"stream\\",\\n            display_name=\\"Stream\\",\\n            info=\\"Whether to stream the response\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n        SliderInput(\\n            name=\\"temperature\\",\\n            display_name=\\"Temperature\\",\\n            value=0.1,\\n            info=\\"Controls randomness in responses\\",\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:\\n        provider = self.provider\\n        model_name = self.model_name\\n        temperature = self.temperature\\n        stream = self.stream\\n\\n        if provider == \\"OpenAI\\":\\n            if not self.api_key:\\n                msg = \\"OpenAI API key is required when using OpenAI provider\\"\\n                raise ValueError(msg)\\n\\n            if model_name in OPENAI_REASONING_MODEL_NAMES:\\n                # reasoning models do not support temperature (yet)\\n                temperature = None\\n\\n            return ChatOpenAI(\\n                model_name=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                openai_api_key=self.api_key,\\n            )\\n        if provider == \\"Anthropic\\":\\n            if not self.api_key:\\n                msg = \\"Anthropic API key is required when using Anthropic provider\\"\\n                raise ValueError(msg)\\n            return ChatAnthropic(\\n                model=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                anthropic_api_key=self.api_key,\\n            )\\n        if provider == \\"Google\\":\\n            if not self.api_key:\\n                msg = \\"Google API key is required when using Google provider\\"\\n                raise ValueError(msg)\\n            return ChatGoogleGenerativeAI(\\n                model=model_name,\\n                temperature=temperature,\\n                streaming=stream,\\n                google_api_key=self.api_key,\\n            )\\n        msg = f\\"Unknown provider: {provider}\\"\\n        raise ValueError(msg)\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:\\n        if field_name == \\"provider\\":\\n            if field_value == \\"OpenAI\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = OPENAI_CHAT_MODEL_NAMES + OPENAI_REASONING_MODEL_NAMES\\n                build_config[\\"model_name\\"][\\"value\\"] = OPENAI_CHAT_MODEL_NAMES[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"OpenAI API Key\\"\\n            elif field_value == \\"Anthropic\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = ANTHROPIC_MODELS\\n                build_config[\\"model_name\\"][\\"value\\"] = ANTHROPIC_MODELS[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"Anthropic API Key\\"\\n            elif field_value == \\"Google\\":\\n                build_config[\\"model_name\\"][\\"options\\"] = GOOGLE_GENERATIVE_AI_MODELS\\n                build_config[\\"model_name\\"][\\"value\\"] = GOOGLE_GENERATIVE_AI_MODELS[0]\\n                build_config[\\"api_key\\"][\\"display_name\\"] = \\"Google API Key\\"\\n        elif field_name == \\"model_name\\" and field_value.startswith(\\"o1\\") and self.provider == \\"OpenAI\\":\\n            # Hide system_message for o1 models - currently unsupported\\n            if \\"system_message\\" in build_config:\\n                build_config[\\"system_message\\"][\\"show\\"] = False\\n        elif field_name == \\"model_name\\" and not field_value.startswith(\\"o1\\") and \\"system_message\\" in build_config:\\n            build_config[\\"system_message\\"][\\"show\\"] = True\\n        return build_config\\n"}, "input_value": {"_input_type": "MessageTextInput", "advanced": false, "display_name": "Input", "dynamic": false, "info": "The input text to send to the model", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "input_value", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "model_name": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Name", "dynamic": false, "info": "Select the model to use", "name": "model_name", "options": ["gpt-4o-mini", "gpt-4o", "gpt-4.1", "gpt-4.1-mini", "gpt-4.1-nano", "gpt-4.5-preview", "gpt-4-turbo", "gpt-4-turbo-preview", "gpt-4", "gpt-3.5-turbo"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "gpt-4o-mini"}, "provider": {"_input_type": "DropdownInput", "advanced": false, "combobox": false, "dialog_inputs": {}, "display_name": "Model Provider", "dynamic": false, "info": "Select the model provider", "name": "provider", "options": ["OpenAI", "Anthropic", "Google"], "options_metadata": [{"icon": "OpenAI"}, {"icon": "Anthropic"}, {"icon": "Google"}], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "OpenAI"}, "stream": {"_input_type": "BoolInput", "advanced": true, "display_name": "Stream", "dynamic": false, "info":