a": false, "conditional_paths": [], "custom_fields": {"template": ["context", "question"]}, "description": "Create a prompt template with dynamic variables.", "display_name": "Prompt", "documentation": "", "edited": false, "error": null, "field_order": ["template"], "frozen": false, "full_path": null, "icon": "braces", "is_composition": null, "is_input": null, "is_output": null, "legacy": false, "lf_version": "1.1.1", "metadata": {}, "name": "", "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Prompt", "group_outputs": false, "method": "build_prompt", "name": "prompt", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.base.prompts.api_utils import process_prompt_template\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.inputs.inputs import DefaultPromptField\\nfrom langflow.io import MessageTextInput, Output, PromptInput\\nfrom langflow.schema.message import Message\\nfrom langflow.template.utils import update_template_values\\n\\n\\nclass PromptComponent(Component):\\n    display_name: str = \\"Prompt\\"\\n    description: str = \\"Create a prompt template with dynamic variables.\\"\\n    icon = \\"braces\\"\\n    trace_type = \\"prompt\\"\\n    name = \\"Prompt\\"\\n\\n    inputs = [\\n        PromptInput(name=\\"template\\", display_name=\\"Template\\"),\\n        MessageTextInput(\\n            name=\\"tool_placeholder\\",\\n            display_name=\\"Tool Placeholder\\",\\n            tool_mode=True,\\n            advanced=True,\\n            info=\\"A placeholder input for tool mode.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Prompt\\", name=\\"prompt\\", method=\\"build_prompt\\"),\\n    ]\\n\\n    async def build_prompt(self) -> Message:\\n        prompt = Message.from_template(**self._attributes)\\n        self.status = prompt.text\\n        return prompt\\n\\n    def _update_template(self, frontend_node: dict):\\n        prompt_template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        custom_fields = frontend_node[\\"custom_fields\\"]\\n        frontend_node_template = frontend_node[\\"template\\"]\\n        _ = process_prompt_template(\\n            template=prompt_template,\\n            name=\\"template\\",\\n            custom_fields=custom_fields,\\n            frontend_node_template=frontend_node_template,\\n        )\\n        return frontend_node\\n\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict):\\n        \\"\\"\\"This function is called after the code validation is done.\\"\\"\\"\\n        frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        # Kept it duplicated for backwards compatibility\\n        _ = process_prompt_template(\\n            template=template,\\n            name=\\"template\\",\\n            custom_fields=frontend_node[\\"custom_fields\\"],\\n            frontend_node_template=frontend_node[\\"template\\"],\\n        )\\n        # Now that template is updated, we need to grab any values that were set in the current_frontend_node\\n        # and update the frontend_node with those values\\n        update_template_values(new_template=frontend_node, previous_template=current_frontend_node[\\"template\\"])\\n        return frontend_node\\n\\n    def _get_fallback_input(self, **kwargs):\\n        return DefaultPromptField(**kwargs)\\n"}, "context": {"advanced": false, "display_name": "context", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message", "Text"], "list": false, "load_from_db": false, "multiline": true, "name": "context", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": ""}, "question": {"advanced": false, "display_name": "question", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message", "Text"], "list": false, "load_from_db": false, "multiline": true, "name": "question", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": ""}, "template": {"advanced": false, "display_name": "Template", "dynamic": false, "info": "", "list": false, "load_from_db": false, "name": "template", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "type": "prompt", "value": "{context}\\n\\n---\\n\\nGiven the context above, answer the question as best as possible.\\n\\nQuestion: {question}\\n\\nAnswer: "}, "tool_placeholder": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Tool Placeholder", "dynamic": false, "info": "A placeholder input for tool mode.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "tool_placeholder", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "selected_output": "prompt", "type": "Prompt"}, "dragging": false, "height": 433, "id": "Prompt-V3tlJ", "measured": {"height": 433, "width": 320}, "position": {"x": 1977.9097981422992, "y": 640.5656416923846}, "positionAbsolute": {"x": 1977.9097981422992, "y": 640.5656416923846}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"description": "Split text into chunks based on specified criteria.", "display_name": "Split Text", "id": "SplitText-6H5cD", "node": {"base_classes": ["Data"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Split text into chunks based on specified criteria.", "display_name": "Split Text", "documentation": "", "edited": false, "field_order": ["data_inputs", "chunk_overlap", "chunk_size", "separator"], "frozen": false, "icon": "scissors-line-dashed", "legacy": false, "lf_version": "1.1.1", "metadata": {}, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Chunks", "group_outputs": false, "method": "split_text", "name": "dataframe", "selected": "DataFrame", "tool_mode": true, "types": ["DataFrame"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "chunk_overlap": {"advanced": false, "display_name": "Chunk Overlap", "dynamic": false, "info": "Number of characters to overlap between chunks.", "list": false, "name": "chunk_overlap", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "int", "value": 200}, "chunk_size": {"advanced": false, "display_name": "Chunk Size", "dynamic": false, "info": "The maximum length of each chunk. Text is first split by separator, then chunks are merged up to this size. Individual splits larger than this won't be further divided.", "list": false, "name": "chunk_size", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "int", "value": 1000}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langchain_text_splitters import CharacterTextSplitter\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.io import DropdownInput, HandleInput, IntInput, MessageTextInput, Output\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.utils.util import unescape_string\\n\\n\\nclass SplitTextComponent(Component):\\n    display_name: str = \\"Split Text\\"\\n    description: str = \\"Split text into chunks based on specified criteria.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-processing#split-text\\"\\n    icon = \\"scissors-line-dashed\\"\\n    name = \\"SplitText\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"data_inputs\\",\\n            display_name=\\"Input\\",\\n            info=\\"The data with texts to split in chunks.\\",\\n            input_types=[\\"Data\\", \\"DataFrame\\", \\"Message\\"],\\n            required=True,\\n        ),\\n        IntInput(\\n            name=\\"chunk_overlap\\",\\n            display_name=\\"Chunk Overlap\\",\\n            info=\\"Number of characters to overlap between chunks.\\",\\n            value=200,\\n        ),\\n        IntInput(\\n            name=\\"chunk_size\\",\\n            display_name=\\"Chunk Size\\",\\n            info=(\\n                \\"The maximum length of each chunk. Text is first split by separator, \\"\\n                \\"then chunks are merged up to this size. \\"\\n                \\"Individual splits larger than this won't be further divided.\\"\\n            ),\\n            value=1000,\\n        ),\\n        MessageTextInput(\\n            name=\\"separator\\",\\n            display_name=\\"Separator\\",\\n            info=(\\n                \\"The character to split on. Use \\\\\\\\n for newline. \\"\\n                \\"Examples: \\\\\\\\n\\\\\\\\n for paragraphs, \\\\\\\\n for lines, . for sentences\\"\\n            ),\\n            value=\\"\\\\n\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"text_key\\",\\n            display_name=\\"Text Key\\",\\n            info=\\"The key to use for the text column.\\",\\n            value=\\"text\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"keep_separator\\",\\n            display_name=\\"Keep Separator\\",\\n            info=\\"Whether to keep the separator in the output chunks and where to place it.\\",\\n            options=[\\"False\\", \\"True\\", \\"Start\\", \\"End\\"],\\n            value=\\"False\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Chunks\\", name=\\"dataframe\\", method=\\"split_text\\"),\\n    ]\\n\\n    def _docs_to_data(self, docs) -> list[Data]:\\n        return [Data(text=doc.page_content, data=doc.metadata) for doc in docs]\\n\\n    def _fix_separator(self, separator: str) -> str:\\n        \\"\\"\\"Fix common separator issues and convert to proper format.\\"\\"\\"\\n        if separator == \\"/n\\":\\n            return \\"\\\\n\\"\\n        if separator == \\"/t\\":\\n            return \\"\\\\t\\"\\n        return separator\\n\\n    def split_text_base(self):\\n        separator = self._fix_separator(self.separator)\\n        separator = unescape_string(separator)\\n\\n        if isinstance(self.data_inputs, DataFrame):\\n            if not len(self.data_inputs):\\n                msg = \\"DataFrame is empty\\"\\n                raise TypeError(msg)\\n\\n            self.data_inputs.text_key = self.text_key\\n            try:\\n                documents = self.data_inputs.to_lc_documents()\\n            except Exception as e:\\n                msg = f\\"Error converting DataFrame to documents: {e}\\"\\n                raise TypeError(msg) from e\\n        elif isinstance(self.data_inputs, Message):\\n            self.data_inputs = [self.data_inputs.to_data()]\\n            return self.split_text_base()\\n        else:\\n            if not self.data_inputs:\\n                msg = \\"No data inputs provided\\"\\n                raise TypeError(msg)\\n\\n            documents = []\\n            if isinstance(self.data_inputs, Data):\\n                self.data_inputs.text_key = self.text_key\\n                documents = [self.data_inputs.to_lc_document()]\\n            else:\\n                try:\\n                    documents = [input_.to_lc_document() for input_ in self.data_inputs if isinstance(input_, Data)]\\n                    if not documents:\\n                        msg = f\\"No valid Data inputs found in {type(self.data_inputs)}\\"\\n                        raise TypeError(msg)\\n                except AttributeError as e:\\n                    msg = f\\"Invalid input type in collection: {e}\\"\\n                    raise TypeError(msg) from e\\n        try:\\n            # Convert string 'False'/'True' to boolean\\n            keep_sep = self.keep_separator\\n            if isinstance(keep_sep, str):\\n                if keep_sep.lower() == \\"false\\":\\n                    keep_sep = False\\n                elif keep_sep.lower() == \\"true\\":\\n                    keep_sep = True\\n                # 'start' and 'end' are kept as strings\\n\\n            splitter = CharacterTextSplitter(\\n                chunk_overlap=self.chunk_overlap,\\n                chunk_size=self.chunk_size,\\n                separator=separator,\\n                keep_separator=keep_sep,\\n            )\\n            return splitter.split_documents(documents)\\n        except Exception as e:\\n            msg = f\\"Error splitting text: {e}\\"\\n            raise TypeError(msg) from e\\n\\n    def split_text(self) -> DataFrame:\\n        return DataFrame(self._docs_to_data(self.split_text_base()))\\n"}, "data_inputs": {"advanced": false, "display_name": "Input", "dynamic": false, "info": "The data with texts to split in chunks.", "input_types": ["Data", "DataFrame", "Message"], "list": false, "name": "data_inputs", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "keep_separator": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Keep Separator", "dynamic": false, "info": "Whether to keep the separator in the output chunks and where to place it.", "name": "keep_separator", "options": ["False", "True", "Start", "End"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "False"}, "separator": {"advanced": false, "display_name": "Separator", "dynamic": false, "info": "The character to split on. Use \\\\n for newline. Examples: \\\\n\\\\n for paragraphs, \\\\n for lines, . for sentences", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "separator", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "\\n"}, "text_key": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Key", "dynamic": false, "info": "The key to use for the text column.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "text_key", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "text"}}}, "selected_output": "chunks", "type": "SplitText"}, "dragging": false, "height": 475, "id": "SplitText-6H5cD", "measured": {"height": 475, "width": 320}, "position": {"x": 1692.461995335383, "y": 1328.2681481569232}, "positionAbsolute": {"x": 1683.4543896546102, "y": 1350.7871623588553}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"id": "note-rR7dl", "node": {"description": "## \\ud83d\\udc15 2. Retriever Flow\\n\\nThis flow answers your questions with contextual data retrieved from your vector database.\\n\\nOpen the **Playground** and ask, \\n\\n```\\nWhat is this document about?\\n```\\n", "display_name": "", "documentation": "", "template": {"backgroundColor": "neutral"}}, "type": "note"}, "dragging": false, "height": 324, "id": "note-rR7dl", "measured": {"height": 324, "width": 324}, "position": {"x": 374.388314931542, "y": 486.18094072679895}, "positionAbsolute": {"x": 374.388314931542, "y": 486.18094072679895}, "resizing": false, "selected": false, "style": {"height": 324, "width": 324}, "type": "noteNode", "width": 324}, {"data": {"id": "note-zTYux", "node": {"description": "## \\ud83d\\udcd6 README\\n\\nLoad your data into a vector database with the \\ud83d\\udcda **Load Data** flow, and then use your data as chat context with the \\ud83d\\udc15 **Retriever** flow.\\n\\n**\\ud83d\\udea8 Add your OpenAI API key as a global variable to easily add it to all of the OpenAI components in this flow.** \\n\\n**Quick start**\\n1. Run the \\ud83d\\udcda **Load Data** flow.\\n2. Run the \\ud83d\\udc15 **Retriever** flow.\\n\\n**Next steps** \\n\\n- Experiment by changing the prompt and the loaded data to see how the bot's responses change. \\n\\nFor more info, see the [Langflow docs](https://docs.langflow.org/starter-projects-vector-store-rag).", "display_name": "Read Me", "documentation": "", "template": {"backgroundColor": "neutral"}}, "type": "note"}, "dragging": false, "height": 556, "id": "note-zTYux", "measured": {"height": 556, "width": 389}, "position": {"x": 191.12162720143235, "y": 1157.6038620251531}, "positionAbsolute": {"x": 94.28986613312418, "y": 907.6428043837066}, "resizing": false, "selected": false, "style": {"height": 324, "width": 324}, "type": "noteNode", "width": 389}, {"data": {"description": "Display a chat message in the Playground.", "display_name": "Chat Output", "id": "ChatOutput-ZaYDW", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Display a chat message in the Playground.", "display_name": "Chat Output", "documentation": "", "edited": false, "field_order": ["input_value", "should_store_message", "sender", "sender_name", "session_id", "data_template", "background_color", "chat_icon", "text_color"], "frozen": false, "icon": "MessagesSquare", "legacy": false, "lf_version": "1.1.1", "metadata": {}, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Output Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "background_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Background Color", "dynamic": false, "info": "The background color of the icon.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "background_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "chat_icon": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "clean_data": {"_input_type": "BoolInput", "advanced": true, "display_name": "Basic Clean Data", "dynamic": false, "info": "Whether to clean the data", "list": false, "list_add_label": "Add More", "name": "clean_data", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from collections.abc import Generator\\nfrom typing import Any\\n\\nimport orjson\\nfrom fastapi.encoders import jsonable_encoder\\n\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.inputs.inputs import BoolInput, DropdownInput, HandleInput, MessageTextInput\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.schema.properties import Source\\nfrom langflow.template.field.base import Output\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_AI,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatOutput(ChatComponent):\\n    display_name = \\"Chat Output\\"\\n    description = \\"Display a chat message in the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-output\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatOutput\\"\\n    minimized = True\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Inputs\\",\\n            info=\\"Message to be passed as output.\\",\\n            input_types=[\\"Data\\", \\"DataFrame\\", \\"Message\\"],\\n            required=True,\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_AI,\\n            advanced=True,\\n            info=\\"Type of sender.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_AI,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"data_template\\",\\n            display_name=\\"Data Template\\",\\n            value=\\"{text}\\",\\n            advanced=True,\\n            info=\\"Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"clean_data\\",\\n            display_name=\\"Basic Clean Data\\",\\n            value=True,\\n            info=\\"Whether to clean the data\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\"Output Message\\",\\n            name=\\"message\\",\\n            method=\\"message_response\\",\\n        ),\\n    ]\\n\\n    def _build_source(self, id_: str | None, display_name: str | None, source: str | None) -> Source:\\n        source_dict = {}\\n        if id_:\\n            source_dict[\\"id\\"] = id_\\n        if display_name:\\n            source_dict[\\"display_name\\"] = display_name\\n        if source:\\n            # Handle case where source is a ChatOpenAI object\\n            if hasattr(source, \\"model_name\\"):\\n                source_dict[\\"source\\"] = source.model_name\\n            elif hasattr(source, \\"model\\"):\\n                source_dict[\\"source\\"] = str(source.model)\\n            else:\\n                source_dict[\\"source\\"] = str(source)\\n        return Source(**source_dict)\\n\\n    async def message_response(self) -> Message:\\n        # First convert the input to string if needed\\n        text = self.convert_to_string()\\n\\n        # Get source properties\\n        source, icon, display_name, source_id = self.get_properties_from_source_component()\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        if self.chat_icon:\\n            icon = self.chat_icon\\n\\n        # Create or use existing Message object\\n        if isinstance(self.input_value, Message):\\n            message = self.input_value\\n            # Update message properties\\n            message.text = text\\n        else:\\n            message = Message(text=text)\\n\\n        # Set message properties\\n        message.sender = self.sender\\n        message.sender_name = self.sender_name\\n        message.session_id = self.session_id\\n        message.flow_id = self.graph.flow_id if hasattr(self, \\"graph\\") else None\\n        message.properties.source = self._build_source(source_id, display_name, source)\\n        message.properties.icon = icon\\n        message.properties.background_color = background_color\\n        message.properties.text_color = text_color\\n\\n        # Store message if needed\\n        if self.session_id and self.should_store_message:\\n            stored_message = await self.send_message(message)\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n\\n    def _serialize_data(self, data: Data) -> str:\\n        \\"\\"\\"Serialize Data object to JSON string.\\"\\"\\"\\n        # Convert data.data to JSON-serializable format\\n        serializable_data = jsonable_encoder(data.data)\\n        # Serialize with orjson, enabling pretty printing with indentation\\n        json_bytes = orjson.dumps(serializable_data, option=orjson.OPT_INDENT_2)\\n        # Convert bytes to string and wrap in Markdown code blocks\\n        return \\"```json\\\\n\\" + json_bytes.decode(\\"utf-8\\") + \\"\\\\n```\\"\\n\\n    def _validate_input(self) -> None:\\n        \\"\\"\\"Validate the input data and raise ValueError if invalid.\\"\\"\\"\\n        if self.input_value is None:\\n            msg = \\"Input data cannot be None\\"\\n            raise ValueError(msg)\\n        if isinstance(self.input_value, list) and not all(\\n            isinstance(item, Message | Data | DataFrame | str) for item in self.input_value\\n        ):\\n            invalid_types = [\\n                type(item).__name__\\n                for item in self.input_value\\n                if not isinstance(item, Message | Data | DataFrame | str)\\n            ]\\n            msg = f\\"Expected Data or DataFrame or Message or str, got {invalid_types}\\"\\n            raise TypeError(msg)\\n        if not isinstance(\\n            self.input_value,\\n            Message | Data | DataFrame | str | list | Generator | type(None),\\n        ):\\n            type_name = type(self.input_value).__name__\\n            msg = f\\"Expected Data or DataFrame or Message or str, Generator or None, got {type_name}\\"\\n            raise TypeError(msg)\\n\\n    def convert_to_string(self) -> str | Generator[Any, None, None]:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        self._validate_input()\\n        if isinstance(self.input_value, list):\\n            return \\"\\\\n\\".join([safe_convert(item, clean_data=self.clean_data) for item in self.input_value])\\n        if isinstance(self.input_value, Generator):\\n            return self.input_value\\n        return safe_convert(self.input_value)\\n"}, "data_template": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Data Template", "dynamic": false, "info": "Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "data_template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "{text}"}, "input_value": {"_input_type": "MessageInput", "advanced": false, "display_name": "Inputs", "dynamic": false, "info": "Message to be passed as output.", "input_types": ["Data", "DataFrame", "Message"], "list": false, "load_from_db": false, "name": "input_value", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "sender": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "display_name": "Sender Type", "dynamic": false, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Machine"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "sender_name", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "AI"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "session_id", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "name": "should_store_message", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "bool", "value": true}, "text_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Text Color", "dynamic": false, "info": "The text color of the name", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "text_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}}, "tool_mode": false}, "type": "ChatOutput"}, "dragging": false, "height": 234, "id": "ChatOutput-ZaYDW", "measured": {"height": 234, "width": 320}, "position": {"x": 2738.611008351098, "y": 829.6219994149209}, "positionAbsolute": {"x": 2734.385670401691, "y": 810.6079786425926}, "selected": false, "type": "genericNode", "width": 320}, {"data": {"id": "OpenAIEmbeddings-v0rcw", "node": {"base_classes": ["Embeddings"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Generate embeddings using OpenAI models.", "display_name": "OpenAI Embeddings", "documentation": "", "edited": false, "field_order": ["default_headers", "default_query", "chunk_size", "client", "deployment", "embedding_ctx_length", "max_retries", "model", "model_kwargs", "openai_api_key", "openai_api_base", "openai_api_type", "openai_api_version", "openai_organization", "openai_proxy", "request_timeout", "show_progress_bar", "skip_empty", "tiktoken_model_name", "tiktoken_enable", "dimensions"], "frozen": false, "icon": "OpenAI", "legacy": false, "lf_version": "1.2.0", "metadata": {}, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Embedding Model", "group_outputs": false, "method": "build_embeddings", "name": "embeddings", "selected": "Embeddings", "tool_mode": true, "types": ["Embeddings"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "chunk_size": {"_input_type": "IntInput", "advanced": true, "display_name": "Chunk Size", "dynamic": false, "info": "", "list": false, "name": "chunk_size", "placeholder": "", "required": false, "show": true, "title_case": false, "trace_as_metadata": true, "type": "int", "value": 1000}, "client": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Client", "dynamic": false, "info": "", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "client", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langchain_openai import OpenAIEmbeddings\\n\\nfrom langflow.base.embeddings.model import LCEmbeddingsModel\\nfrom langflow.base.models.openai_constants import OPENAI_EMBEDDING_MODEL_NAMES\\nfrom langflow.field_typing import Embeddings\\nfrom langflow.io import BoolInput, DictInput, DropdownInput, FloatInput, IntInput, MessageTextInput, SecretStrInput\\n\\n\\nclass OpenAIEmbeddingsComponent(LCEmbeddingsModel):\\n    display_name = \\"OpenAI Embeddings\\"\\n    description = \\"Generate embeddings using OpenAI models.\\"\\n    icon = \\"OpenAI\\"\\n    name = \\"OpenAIEmbeddings\\"\\n\\n    inputs = [\\n        DictInput(\\n            name=\\"default_headers\\",\\n            display_name=\\"Default Headers\\",\\n            advanced=True,\\n            info=\\"Default headers to use for the API request.\\",\\n        ),\\n        DictInput(\\n            name=\\"default_query\\",\\n            display_name=\\"Default Query\\",\\n            advanced=True,\\n            info=\\"Default query parameters to use for the API request.\\",\\n        ),\\n        IntInput(name=\\"chunk_size\\", display_name=\\"Chunk Size\\", advanced=True, value=1000),\\n        MessageTextInput(name=\\"client\\", display_name=\\"Client\\", advanced=True),\\n        MessageTextInput(name=\\"deployment\\", display_name=\\"Deployment\\", advanced=True),\\n        IntInput(name=\\"embedding_ctx_length\\", display_name=\\"Embedding Context Length\\", advanced=True, value=1536),\\n        IntInput(name=\\"max_retries\\", display_name=\\"Max Retries\\", value=3, advanced=True),\\n        DropdownInput(\\n            name=\\"model\\",\\n            display_name=\\"Model\\",\\n            advanced=False,\\n            options=OPENAI_EMBEDDING_MODEL_NAMES,\\n            value=\\"text-embedding-3-small\\",\\n        ),\\n        DictInput(name=\\"model_kwargs\\", display_name=\\"Model Kwargs\\", advanced=True),\\n        SecretStrInput(name=\\"openai_api_key\\", display_name=\\"OpenAI API Key\\", value=\\"OPENAI_API_KEY\\", required=True),\\n        MessageTextInput(name=\\"openai_api_base\\", display_name=\\"OpenAI API Base\\", advanced=True),\\n        MessageTextInput(name=\\"openai_api_type\\", display_name=\\"OpenAI API Type\\", advanced=True),\\n        MessageTextInput(name=\\"openai_api_version\\", display_name=\\"OpenAI API Version\\", advanced=True),\\n        MessageTextInput(\\n            name=\\"openai_organization\\",\\n            display_name=\\"OpenAI Organization\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(name=\\"openai_proxy\\", display_name=\\"OpenAI Proxy\\", advanced=True),\\n        FloatInput(name=\\"request_timeout\\", display_name=\\"Request Timeout\\", advanced=True),\\n        BoolInput(name=\\"show_progress_bar\\", display_name=\\"Show Progress Bar\\", advanced=True),\\n        BoolInput(name=\\"skip_empty\\", display_name=\\"Skip Empty\\", advanced=True),\\n        MessageTextInput(\\n            name=\\"tiktoken_model_name\\",\\n            display_name=\\"TikToken Model Name\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"tiktoken_enable\\",\\n            display_name=\\"TikToken Enable\\",\\n            advanced=True,\\n            value=True,\\n            info=\\"If False, you must have transformers installed.\\",\\n        ),\\n        IntInput(\\n            name=\\"dimensions\\",\\n            display_name=\\"Dimensions\\",\\n            info=\\"The number of dimensions the resulting output embeddings should have. \\"\\n            \\"Only supported by certain models.\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_embeddings(self) -> Embeddings:\\n        return OpenAIEmbeddings(\\n            client=self.client or None,\\n            model=self.model,\\n            dimensions=self.dimensions or None,\\n            deployment=self.deployment or None,\\n            api_version=self.openai_api_version or None,\\n            base_url=self.openai_api_base or None,\\n            openai_api_type=self.openai_api_type or None,\\n            openai_proxy=self.openai_proxy or None,\\n            embedding_ctx_length=self.embedding_ctx_length,\\n            api_key=self.openai_api_key or None,\\n            organization=self.openai_organization or None,\\n            allowed_special=\\"all\\",\\n            disallowed_special=\\"all\\",\\n            chunk_size=self.chunk_size,\\n            max_retries=self.max_retries,\\n            timeout=self.request_timeout or No