data": true, "type": "bool", "value": true}}, "tool_mode": false}, "selected_output": "response", "showNode": true, "type": "Agent"}, "dragging": false, "id": "Agent-D0Kx2", "measured": {"height": 594, "width": 320}, "position": {"x": 1641.6239626366948, "y": 301.10345101561927}, "selected": true, "type": "genericNode"}, {"data": {"id": "URLComponent-TpTHB", "node": {"base_classes": ["DataFrame", "Message"], "beta": false, "category": "data", "conditional_paths": [], "custom_fields": {}, "description": "Fetch content from one or more web pages, following links recursively.", "display_name": "URL", "documentation": "", "edited": false, "field_order": ["urls", "max_depth", "prevent_outside", "use_async", "format", "timeout", "headers", "filter_text_html", "continue_on_failure", "check_response_status", "autoset_encoding"], "frozen": false, "icon": "layout-template", "key": "URLComponent", "legacy": false, "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Toolset", "group_outputs": false, "hidden": null, "method": "to_toolkit", "name": "component_as_tool", "options": null, "required_inputs": null, "selected": "Tool", "tool_mode": true, "types": ["Tool"], "value": "__UNDEFINED__"}], "pinned": false, "score": 2.220446049250313e-16, "template": {"_type": "Component", "autoset_encoding": {"_input_type": "BoolInput", "advanced": true, "display_name": "Autoset Encoding", "dynamic": false, "info": "If enabled, automatically sets the encoding of the request.", "list": false, "list_add_label": "Add More", "name": "autoset_encoding", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "check_response_status": {"_input_type": "BoolInput", "advanced": true, "display_name": "Check Response Status", "dynamic": false, "info": "If enabled, checks the response status of the request.", "list": false, "list_add_label": "Add More", "name": "check_response_status", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import re\\n\\nimport requests\\nfrom bs4 import BeautifulSoup\\nfrom langchain_community.document_loaders import RecursiveUrlLoader\\nfrom loguru import logger\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.io import BoolInput, DropdownInput, IntInput, MessageTextInput, Output, SliderInput, TableInput\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.services.deps import get_settings_service\\n\\n# Constants\\nDEFAULT_TIMEOUT = 30\\nDEFAULT_MAX_DEPTH = 1\\nDEFAULT_FORMAT = \\"Text\\"\\nURL_REGEX = re.compile(\\n    r\\"^(https?:\\\\/\\\\/)?\\" r\\"(www\\\\.)?\\" r\\"([a-zA-Z0-9.-]+)\\" r\\"(\\\\.[a-zA-Z]{2,})?\\" r\\"(:\\\\d+)?\\" r\\"(\\\\/[^\\\\s]*)?$\\",\\n    re.IGNORECASE,\\n)\\n\\n\\nclass URLComponent(Component):\\n    \\"\\"\\"A component that loads and parses content from web pages recursively.\\n\\n    This component allows fetching content from one or more URLs, with options to:\\n    - Control crawl depth\\n    - Prevent crawling outside the root domain\\n    - Use async loading for better performance\\n    - Extract either raw HTML or clean text\\n    - Configure request headers and timeouts\\n    \\"\\"\\"\\n\\n    display_name = \\"URL\\"\\n    description = \\"Fetch content from one or more web pages, following links recursively.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-data#url\\"\\n    icon = \\"layout-template\\"\\n    name = \\"URLComponent\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\"urls\\",\\n            display_name=\\"URLs\\",\\n            info=\\"Enter one or more URLs to crawl recursively, by clicking the '+' button.\\",\\n            is_list=True,\\n            tool_mode=True,\\n            placeholder=\\"Enter a URL...\\",\\n            list_add_label=\\"Add URL\\",\\n            input_types=[],\\n        ),\\n        SliderInput(\\n            name=\\"max_depth\\",\\n            display_name=\\"Depth\\",\\n            info=(\\n                \\"Controls how many 'clicks' away from the initial page the crawler will go:\\\\n\\"\\n                \\"- depth 1: only the initial page\\\\n\\"\\n                \\"- depth 2: initial page + all pages linked directly from it\\\\n\\"\\n                \\"- depth 3: initial page + direct links + links found on those direct link pages\\\\n\\"\\n                \\"Note: This is about link traversal, not URL path depth.\\"\\n            ),\\n            value=DEFAULT_MAX_DEPTH,\\n            range_spec=RangeSpec(min=1, max=5, step=1),\\n            required=False,\\n            min_label=\\" \\",\\n            max_label=\\" \\",\\n            min_label_icon=\\"None\\",\\n            max_label_icon=\\"None\\",\\n            # slider_input=True\\n        ),\\n        BoolInput(\\n            name=\\"prevent_outside\\",\\n            display_name=\\"Prevent Outside\\",\\n            info=(\\n                \\"If enabled, only crawls URLs within the same domain as the root URL. \\"\\n                \\"This helps prevent the crawler from going to external websites.\\"\\n            ),\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"use_async\\",\\n            display_name=\\"Use Async\\",\\n            info=(\\n                \\"If enabled, uses asynchronous loading which can be significantly faster \\"\\n                \\"but might use more system resources.\\"\\n            ),\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"format\\",\\n            display_name=\\"Output Format\\",\\n            info=\\"Output Format. Use 'Text' to extract the text from the HTML or 'HTML' for the raw HTML content.\\",\\n            options=[\\"Text\\", \\"HTML\\"],\\n            value=DEFAULT_FORMAT,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\"timeout\\",\\n            display_name=\\"Timeout\\",\\n            info=\\"Timeout for the request in seconds.\\",\\n            value=DEFAULT_TIMEOUT,\\n            required=False,\\n            advanced=True,\\n        ),\\n        TableInput(\\n            name=\\"headers\\",\\n            display_name=\\"Headers\\",\\n            info=\\"The headers to send with the request\\",\\n            table_schema=[\\n                {\\n                    \\"name\\": \\"key\\",\\n                    \\"display_name\\": \\"Header\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Header name\\",\\n                },\\n                {\\n                    \\"name\\": \\"value\\",\\n                    \\"display_name\\": \\"Value\\",\\n                    \\"type\\": \\"str\\",\\n                    \\"description\\": \\"Header value\\",\\n                },\\n            ],\\n            value=[{\\"key\\": \\"User-Agent\\", \\"value\\": get_settings_service().settings.user_agent}],\\n            advanced=True,\\n            input_types=[\\"DataFrame\\"],\\n        ),\\n        BoolInput(\\n            name=\\"filter_text_html\\",\\n            display_name=\\"Filter Text/HTML\\",\\n            info=\\"If enabled, filters out text/css content type from the results.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"continue_on_failure\\",\\n            display_name=\\"Continue on Failure\\",\\n            info=\\"If enabled, continues crawling even if some requests fail.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"check_response_status\\",\\n            display_name=\\"Check Response Status\\",\\n            info=\\"If enabled, checks the response status of the request.\\",\\n            value=False,\\n            required=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"autoset_encoding\\",\\n            display_name=\\"Autoset Encoding\\",\\n            info=\\"If enabled, automatically sets the encoding of the request.\\",\\n            value=True,\\n            required=False,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Extracted Pages\\", name=\\"page_results\\", method=\\"fetch_content\\"),\\n        Output(display_name=\\"Raw Content\\", name=\\"raw_results\\", method=\\"fetch_content_as_message\\", tool_mode=False),\\n    ]\\n\\n    @staticmethod\\n    def validate_url(url: str) -> bool:\\n        \\"\\"\\"Validates if the given string matches URL pattern.\\n\\n        Args:\\n            url: The URL string to validate\\n\\n        Returns:\\n            bool: True if the URL is valid, False otherwise\\n        \\"\\"\\"\\n        return bool(URL_REGEX.match(url))\\n\\n    def ensure_url(self, url: str) -> str:\\n        \\"\\"\\"Ensures the given string is a valid URL.\\n\\n        Args:\\n            url: The URL string to validate and normalize\\n\\n        Returns:\\n            str: The normalized URL\\n\\n        Raises:\\n            ValueError: If the URL is invalid\\n        \\"\\"\\"\\n        url = url.strip()\\n        if not url.startswith((\\"http://\\", \\"https://\\")):\\n            url = \\"https://\\" + url\\n\\n        if not self.validate_url(url):\\n            msg = f\\"Invalid URL: {url}\\"\\n            raise ValueError(msg)\\n\\n        return url\\n\\n    def _create_loader(self, url: str) -> RecursiveUrlLoader:\\n        \\"\\"\\"Creates a RecursiveUrlLoader instance with the configured settings.\\n\\n        Args:\\n            url: The URL to load\\n\\n        Returns:\\n            RecursiveUrlLoader: Configured loader instance\\n        \\"\\"\\"\\n        headers_dict = {header[\\"key\\"]: header[\\"value\\"] for header in self.headers}\\n        extractor = (lambda x: x) if self.format == \\"HTML\\" else (lambda x: BeautifulSoup(x, \\"lxml\\").get_text())\\n\\n        return RecursiveUrlLoader(\\n            url=url,\\n            max_depth=self.max_depth,\\n            prevent_outside=self.prevent_outside,\\n            use_async=self.use_async,\\n            extractor=extractor,\\n            timeout=self.timeout,\\n            headers=headers_dict,\\n            check_response_status=self.check_response_status,\\n            continue_on_failure=self.continue_on_failure,\\n            base_url=url,  # Add base_url to ensure consistent domain crawling\\n            autoset_encoding=self.autoset_encoding,  # Enable automatic encoding detection\\n            exclude_dirs=[],  # Allow customization of excluded directories\\n            link_regex=None,  # Allow customization of link filtering\\n        )\\n\\n    def fetch_url_contents(self) -> list[dict]:\\n        \\"\\"\\"Load documents from the configured URLs.\\n\\n        Returns:\\n            List[Data]: List of Data objects containing the fetched content\\n\\n        Raises:\\n            ValueError: If no valid URLs are provided or if there's an error loading documents\\n        \\"\\"\\"\\n        try:\\n            urls = list({self.ensure_url(url) for url in self.urls if url.strip()})\\n            logger.debug(f\\"URLs: {urls}\\")\\n            if not urls:\\n                msg = \\"No valid URLs provided.\\"\\n                raise ValueError(msg)\\n\\n            all_docs = []\\n            for url in urls:\\n                logger.debug(f\\"Loading documents from {url}\\")\\n\\n                try:\\n                    loader = self._create_loader(url)\\n                    docs = loader.load()\\n\\n                    if not docs:\\n                        logger.warning(f\\"No documents found for {url}\\")\\n                        continue\\n\\n                    logger.debug(f\\"Found {len(docs)} documents from {url}\\")\\n                    all_docs.extend(docs)\\n\\n                except requests.exceptions.RequestException as e:\\n                    logger.exception(f\\"Error loading documents from {url}: {e}\\")\\n                    continue\\n\\n            if not all_docs:\\n                msg = \\"No documents were successfully loaded from any URL\\"\\n                raise ValueError(msg)\\n\\n            # data = [Data(text=doc.page_content, **doc.metadata) for doc in all_docs]\\n            data = [\\n                {\\n                    \\"text\\": safe_convert(doc.page_content, clean_data=True),\\n                    \\"url\\": doc.metadata.get(\\"source\\", \\"\\"),\\n                    \\"title\\": doc.metadata.get(\\"title\\", \\"\\"),\\n                    \\"description\\": doc.metadata.get(\\"description\\", \\"\\"),\\n                    \\"content_type\\": doc.metadata.get(\\"content_type\\", \\"\\"),\\n                    \\"language\\": doc.metadata.get(\\"language\\", \\"\\"),\\n                }\\n                for doc in all_docs\\n            ]\\n        except Exception as e:\\n            error_msg = e.message if hasattr(e, \\"message\\") else e\\n            msg = f\\"Error loading documents: {error_msg!s}\\"\\n            logger.exception(msg)\\n            raise ValueError(msg) from e\\n        return data\\n\\n    def fetch_content(self) -> DataFrame:\\n        \\"\\"\\"Convert the documents to a DataFrame.\\"\\"\\"\\n        return DataFrame(data=self.fetch_url_contents())\\n\\n    def fetch_content_as_message(self) -> Message:\\n        \\"\\"\\"Convert the documents to a Message.\\"\\"\\"\\n        url_contents = self.fetch_url_contents()\\n        return Message(text=\\"\\\\n\\\\n\\".join([x[\\"text\\"] for x in url_contents]), data={\\"data\\": url_contents})\\n"}, "continue_on_failure": {"_input_type": "BoolInput", "advanced": true, "display_name": "Continue on Failure", "dynamic": false, "info": "If enabled, continues crawling even if some requests fail.", "list": false, "list_add_label": "Add More", "name": "continue_on_failure", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "filter_text_html": {"_input_type": "BoolInput", "advanced": true, "display_name": "Filter Text/HTML", "dynamic": false, "info": "If enabled, filters out text/css content type from the results.", "list": false, "list_add_label": "Add More", "name": "filter_text_html", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "format": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Output Format", "dynamic": false, "info": "Output Format. Use 'Text' to extract the text from the HTML or 'HTML' for the raw HTML content.", "name": "format", "options": ["Text", "HTML"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "Text"}, "headers": {"_input_type": "TableInput", "advanced": true, "display_name": "Headers", "dynamic": false, "info": "The headers to send with the request", "input_types": ["DataFrame"], "is_list": true, "list_add_l