153: [\\u0153Data\\u0153, \\u0153DataFrame\\u0153, \\u0153Message\\u0153], \\u0153type\\u0153: \\u0153str\\u0153}"}, {"data": {"sourceHandle": {"dataType": "Memory", "id": "Memory-dFlpS", "name": "messages_text", "output_types": ["Message"]}, "targetHandle": {"fieldName": "history", "id": "Prompt-36nA8", "inputTypes": ["Message", "Text"], "type": "str"}}, "id": "xy-edge__Memory-dFlpS{\\u0153dataType\\u0153:\\u0153Memory\\u0153,\\u0153id\\u0153:\\u0153Memory-dFlpS\\u0153,\\u0153name\\u0153:\\u0153messages_text\\u0153,\\u0153output_types\\u0153:[\\u0153Message\\u0153]}-Prompt-36nA8{\\u0153fieldName\\u0153:\\u0153history\\u0153,\\u0153id\\u0153:\\u0153Prompt-36nA8\\u0153,\\u0153inputTypes\\u0153:[\\u0153Message\\u0153,\\u0153Text\\u0153],\\u0153type\\u0153:\\u0153str\\u0153}", "source": "Memory-dFlpS", "sourceHandle": "{\\u0153dataType\\u0153: \\u0153Memory\\u0153, \\u0153id\\u0153: \\u0153Memory-dFlpS\\u0153, \\u0153name\\u0153: \\u0153messages_text\\u0153, \\u0153output_types\\u0153: [\\u0153Message\\u0153]}", "target": "Prompt-36nA8", "targetHandle": "{\\u0153fieldName\\u0153: \\u0153history\\u0153, \\u0153id\\u0153: \\u0153Prompt-36nA8\\u0153, \\u0153inputTypes\\u0153: [\\u0153Message\\u0153, \\u0153Text\\u0153], \\u0153type\\u0153: \\u0153str\\u0153}"}], "nodes": [{"data": {"id": "AssemblyAITranscriptionJobPoller-sCJsy", "node": {"base_classes": ["Data"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Poll for the status of a transcription job using AssemblyAI", "display_name": "AssemblyAI Poll Transcript", "documentation": "https://www.assemblyai.com/docs", "edited": false, "field_order": ["api_key", "transcript_id", "polling_interval"], "frozen": false, "icon": "AssemblyAI", "legacy": false, "lf_version": "1.1.5", "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Transcription Result", "group_outputs": false, "method": "poll_transcription_job", "name": "transcription_result", "selected": "Data", "tool_mode": true, "types": ["Data"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "Assembly API Key", "dynamic": false, "info": "Your AssemblyAI API key. You can get one from https://www.assemblyai.com/", "input_types": [], "load_from_db": true, "name": "api_key", "password": true, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "str", "value": "ASSEMBLYAI_API_KEY"}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import assemblyai as aai\\nfrom loguru import logger\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.field_typing.range_spec import RangeSpec\\nfrom langflow.io import DataInput, FloatInput, Output, SecretStrInput\\nfrom langflow.schema.data import Data\\n\\n\\nclass AssemblyAITranscriptionJobPoller(Component):\\n    display_name = \\"AssemblyAI Poll Transcript\\"\\n    description = \\"Poll for the status of a transcription job using AssemblyAI\\"\\n    documentation = \\"https://www.assemblyai.com/docs\\"\\n    icon = \\"AssemblyAI\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\"api_key\\",\\n            display_name=\\"Assembly API Key\\",\\n            info=\\"Your AssemblyAI API key. You can get one from https://www.assemblyai.com/\\",\\n            required=True,\\n        ),\\n        DataInput(\\n            name=\\"transcript_id\\",\\n            display_name=\\"Transcript ID\\",\\n            info=\\"The ID of the transcription job to poll\\",\\n            required=True,\\n        ),\\n        FloatInput(\\n            name=\\"polling_interval\\",\\n            display_name=\\"Polling Interval\\",\\n            value=3.0,\\n            info=\\"The polling interval in seconds\\",\\n            advanced=True,\\n            range_spec=RangeSpec(min=3, max=30),\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Transcription Result\\", name=\\"transcription_result\\", method=\\"poll_transcription_job\\"),\\n    ]\\n\\n    def poll_transcription_job(self) -> Data:\\n        \\"\\"\\"Polls the transcription status until completion and returns the Data.\\"\\"\\"\\n        aai.settings.api_key = self.api_key\\n        aai.settings.polling_interval = self.polling_interval\\n\\n        # check if it's an error message from the previous step\\n        if self.transcript_id.data.get(\\"error\\"):\\n            self.status = self.transcript_id.data[\\"error\\"]\\n            return self.transcript_id\\n\\n        try:\\n            transcript = aai.Transcript.get_by_id(self.transcript_id.data[\\"transcript_id\\"])\\n        except Exception as e:  # noqa: BLE001\\n            error = f\\"Getting transcription failed: {e}\\"\\n            logger.opt(exception=True).debug(error)\\n            self.status = error\\n            return Data(data={\\"error\\": error})\\n\\n        if transcript.status == aai.TranscriptStatus.completed:\\n            json_response = transcript.json_response\\n            text = json_response.pop(\\"text\\", None)\\n            utterances = json_response.pop(\\"utterances\\", None)\\n            transcript_id = json_response.pop(\\"id\\", None)\\n            sorted_data = {\\"text\\": text, \\"utterances\\": utterances, \\"id\\": transcript_id}\\n            sorted_data.update(json_response)\\n            data = Data(data=sorted_data)\\n            self.status = data\\n            return data\\n        self.status = transcript.error\\n        return Data(data={\\"error\\": transcript.error})\\n"}, "polling_interval": {"_input_type": "FloatInput", "advanced": true, "display_name": "Polling Interval", "dynamic": false, "info": "The polling interval in seconds", "list": false, "list_add_label": "Add More", "name": "polling_interval", "placeholder": "", "range_spec": {"max": 30, "min": 3, "step": 0.1, "step_type": "float"}, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "float", "value": 3}, "transcript_id": {"_input_type": "DataInput", "advanced": false, "display_name": "Transcript ID", "dynamic": false, "info": "The ID of the transcription job to poll", "input_types": ["Data"], "list": false, "list_add_label": "Add More", "name": "transcript_id", "placeholder": "", "required": true, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "other", "value": ""}}, "tool_mode": false}, "selected_output": "transcription_result", "showNode": true, "type": "AssemblyAITranscriptionJobPoller"}, "id": "AssemblyAITranscriptionJobPoller-sCJsy", "measured": {"height": 264, "width": 320}, "position": {"x": 943.468098795128, "y": 282.3188316337007}, "selected": false, "type": "genericNode"}, {"data": {"id": "Prompt-AMW8y", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {"template": ["transcript"]}, "description": "Create a prompt template with dynamic variables.", "display_name": "Prompt", "documentation": "", "edited": false, "error": null, "field_order": ["template", "tool_placeholder"], "frozen": false, "full_path": null, "icon": "braces", "is_composition": null, "is_input": null, "is_output": null, "legacy": false, "lf_version": "1.1.5", "metadata": {}, "minimized": false, "name": "", "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Prompt", "group_outputs": false, "method": "build_prompt", "name": "prompt", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "template": {"_type": "Component", "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from langflow.base.prompts.api_utils import process_prompt_template\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.inputs.inputs import DefaultPromptField\\nfrom langflow.io import MessageTextInput, Output, PromptInput\\nfrom langflow.schema.message import Message\\nfrom langflow.template.utils import update_template_values\\n\\n\\nclass PromptComponent(Component):\\n    display_name: str = \\"Prompt\\"\\n    description: str = \\"Create a prompt template with dynamic variables.\\"\\n    icon = \\"braces\\"\\n    trace_type = \\"prompt\\"\\n    name = \\"Prompt\\"\\n\\n    inputs = [\\n        PromptInput(name=\\"template\\", display_name=\\"Template\\"),\\n        MessageTextInput(\\n            name=\\"tool_placeholder\\",\\n            display_name=\\"Tool Placeholder\\",\\n            tool_mode=True,\\n            advanced=True,\\n            info=\\"A placeholder input for tool mode.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Prompt\\", name=\\"prompt\\", method=\\"build_prompt\\"),\\n    ]\\n\\n    async def build_prompt(self) -> Message:\\n        prompt = Message.from_template(**self._attributes)\\n        self.status = prompt.text\\n        return prompt\\n\\n    def _update_template(self, frontend_node: dict):\\n        prompt_template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        custom_fields = frontend_node[\\"custom_fields\\"]\\n        frontend_node_template = frontend_node[\\"template\\"]\\n        _ = process_prompt_template(\\n            template=prompt_template,\\n            name=\\"template\\",\\n            custom_fields=custom_fields,\\n            frontend_node_template=frontend_node_template,\\n        )\\n        return frontend_node\\n\\n    async def update_frontend_node(self, new_frontend_node: dict, current_frontend_node: dict):\\n        \\"\\"\\"This function is called after the code validation is done.\\"\\"\\"\\n        frontend_node = await super().update_frontend_node(new_frontend_node, current_frontend_node)\\n        template = frontend_node[\\"template\\"][\\"template\\"][\\"value\\"]\\n        # Kept it duplicated for backwards compatibility\\n        _ = process_prompt_template(\\n            template=template,\\n            name=\\"template\\",\\n            custom_fields=frontend_node[\\"custom_fields\\"],\\n            frontend_node_template=frontend_node[\\"template\\"],\\n        )\\n        # Now that template is updated, we need to grab any values that were set in the current_frontend_node\\n        # and update the frontend_node with those values\\n        update_template_values(new_template=frontend_node, previous_template=current_frontend_node[\\"template\\"])\\n        return frontend_node\\n\\n    def _get_fallback_input(self, **kwargs):\\n        return DefaultPromptField(**kwargs)\\n"}, "template": {"_input_type": "PromptInput", "advanced": false, "display_name": "Template", "dynamic": false, "info": "", "list": false, "name": "template", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "type": "prompt", "value": "{transcript}\\n\\n---\\n\\nSummarize the action items and main ideas based on the conversation above. Be objective and avoid redundancy. \\n\\n"}, "tool_placeholder": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Tool Placeholder", "dynamic": false, "info": "A placeholder input for tool mode.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "tool_placeholder", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": true, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "transcript": {"advanced": false, "display_name": "transcript", "dynamic": false, "field_type": "str", "fileTypes": [], "file_path": "", "info": "", "input_types": ["Message", "Text"], "list": false, "load_from_db": false, "multiline": true, "name": "transcript", "placeholder": "", "required": false, "show": true, "title_case": false, "type": "str", "value": ""}}, "tool_mode": false}, "selected_output": "prompt", "showNode": true, "type": "Prompt"}, "id": "Prompt-AMW8y", "measured": {"height": 367, "width": 320}, "position": {"x": 1752.6947356866303, "y": 491.51833853334665}, "selected": false, "type": "genericNode"}, {"data": {"id": "ChatOutput-9KeOi", "node": {"base_classes": ["Message"], "beta": false, "category": "outputs", "conditional_paths": [], "custom_fields": {}, "description": "Display a chat message in the Playground.", "display_name": "Chat Output", "documentation": "", "edited": false, "field_order": ["input_value", "should_store_message", "sender", "sender_name", "session_id", "data_template", "background_color", "chat_icon", "text_color"], "frozen": false, "icon": "MessagesSquare", "key": "ChatOutput", "legacy": false, "lf_version": "1.1.5", "metadata": {}, "minimized": true, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Output Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 0.00012027401062119145, "template": {"_type": "Component", "background_color": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Background Color", "dynamic": false, "info": "The background color of the icon.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "background_color", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "chat_icon": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Icon", "dynamic": false, "info": "The icon of the message.", "input_types": ["Message"], "list": false, "load_from_db": false, "name": "chat_icon", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "clean_data": {"_input_type": "BoolInput", "advanced": true, "display_name": "Basic Clean Data", "dynamic": false, "info": "Whether to clean the data", "list": false, "list_add_label": "Add More", "name": "clean_data", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from collections.abc import Generator\\nfrom typing import Any\\n\\nimport orjson\\nfrom fastapi.encoders import jsonable_encoder\\n\\nfrom langflow.base.io.chat import ChatComponent\\nfrom langflow.helpers.data import safe_convert\\nfrom langflow.inputs.inputs import BoolInput, DropdownInput, HandleInput, MessageTextInput\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom langflow.schema.properties import Source\\nfrom langflow.template.field.base import Output\\nfrom langflow.utils.constants import (\\n    MESSAGE_SENDER_AI,\\n    MESSAGE_SENDER_NAME_AI,\\n    MESSAGE_SENDER_USER,\\n)\\n\\n\\nclass ChatOutput(ChatComponent):\\n    display_name = \\"Chat Output\\"\\n    description = \\"Display a chat message in the Playground.\\"\\n    documentation: str = \\"https://docs.langflow.org/components-io#chat-output\\"\\n    icon = \\"MessagesSquare\\"\\n    name = \\"ChatOutput\\"\\n    minimized = True\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\"input_value\\",\\n            display_name=\\"Inputs\\",\\n            info=\\"Message to be passed as output.\\",\\n            input_types=[\\"Data\\", \\"DataFrame\\", \\"Message\\"],\\n            required=True,\\n        ),\\n        BoolInput(\\n            name=\\"should_store_message\\",\\n            display_name=\\"Store Messages\\",\\n            info=\\"Store the message in the history.\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"sender\\",\\n            display_name=\\"Sender Type\\",\\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\\n            value=MESSAGE_SENDER_AI,\\n            advanced=True,\\n            info=\\"Type of sender.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"sender_name\\",\\n            display_name=\\"Sender Name\\",\\n            info=\\"Name of the sender.\\",\\n            value=MESSAGE_SENDER_NAME_AI,\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"session_id\\",\\n            display_name=\\"Session ID\\",\\n            info=\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"data_template\\",\\n            display_name=\\"Data Template\\",\\n            value=\\"{text}\\",\\n            advanced=True,\\n            info=\\"Template to convert Data to Text. If left empty, it will be dynamically set to the Data's text key.\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"background_color\\",\\n            display_name=\\"Background Color\\",\\n            info=\\"The background color of the icon.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"chat_icon\\",\\n            display_name=\\"Icon\\",\\n            info=\\"The icon of the message.\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"text_color\\",\\n            display_name=\\"Text Color\\",\\n            info=\\"The text color of the name\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"clean_data\\",\\n            display_name=\\"Basic Clean Data\\",\\n            value=True,\\n            info=\\"Whether to clean the data\\",\\n            advanced=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\"Output Message\\",\\n            name=\\"message\\",\\n            method=\\"message_response\\",\\n        ),\\n    ]\\n\\n    def _build_source(self, id_: str | None, display_name: str | None, source: str | None) -> Source:\\n        source_dict = {}\\n        if id_:\\n            source_dict[\\"id\\"] = id_\\n        if display_name:\\n            source_dict[\\"display_name\\"] = display_name\\n        if source:\\n            # Handle case where source is a ChatOpenAI object\\n            if hasattr(source, \\"model_name\\"):\\n                source_dict[\\"source\\"] = source.model_name\\n            elif hasattr(source, \\"model\\"):\\n                source_dict[\\"source\\"] = str(source.model)\\n            else:\\n                source_dict[\\"source\\"] = str(source)\\n        return Source(**source_dict)\\n\\n    async def message_response(self) -> Message:\\n        # First convert the input to string if needed\\n        text = self.convert_to_string()\\n\\n        # Get source properties\\n        source, icon, display_name, source_id = self.get_properties_from_source_component()\\n        background_color = self.background_color\\n        text_color = self.text_color\\n        if self.chat_icon:\\n            icon = self.chat_icon\\n\\n        # Create or use existing Message object\\n        if isinstance(self.input_value, Message):\\n            message = self.input_value\\n            # Update message properties\\n            message.text = text\\n        else:\\n            message = Message(text=text)\\n\\n        # Set message properties\\n        message.sender = self.sender\\n        message.sender_name = self.sender_name\\n        message.session_id = self.session_id\\n        message.flow_id = self.graph.flow_id if hasattr(self, \\"graph\\") else None\\n        message.properties.source = self._build_source(source_id, display_name, source)\\n        message.properties.icon = icon\\n        message.properties.background_color = background_color\\n        message.properties.text_color = text_color\\n\\n        # Store message if needed\\n        if self.session_id and self.should_store_message:\\n            stored_message = await self.send_message(message)\\n            self.message.value = stored_message\\n            message = stored_message\\n\\n        self.status = message\\n        return message\\n\\n    def _serialize_data(self, data: Data) -> str:\\n        \\"\\"\\"Serialize Data object to JSON string.\\"\\"\\"\\n        # Convert data.data to JSON-serializable format\\n        serializable_data = jsonable_encoder(data.data)\\n        # Serialize with orjson, enabling pretty printing with indentation\\n        json_bytes = orjson.dumps(serializable_data, option=orjson.OPT_INDENT_2)\\n        # Convert bytes to string and wrap in Markdown code blocks\\n        return \\"```json\\\\n\\" + json_bytes.decode(\\"utf-8\\") + \\"\\\\n```\\"\\n\\n    def _validate_input(self) -> None:\\n        \\"\\"\\"Validate the input data and raise ValueError if invalid.\\"\\"\\"\\n        if self.input_value is None:\\n            msg = \\"Input data cannot be None\\"\\n            raise ValueError(msg)\\n        if isinstance(self.input_value, list) and not all(\\n            isinstance(item, Message | Data | DataFrame | str) for item in 