ption job for an audio file using AssemblyAI with advanced options", "display_name": "AssemblyAI Start Transcript", "documentation": "https://www.assemblyai.com/docs", "edited": false, "field_order": ["api_key", "audio_file", "audio_file_url", "speech_model", "language_detection", "language_code", "speaker_labels", "speakers_expected", "punctuate", "format_text"], "frozen": false, "icon": "AssemblyAI", "key": "AssemblyAITranscriptionJobCreator", "legacy": false, "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Transcript ID", "group_outputs": false, "method": "create_transcription_job", "name": "transcript_id", "selected": "Data", "tool_mode": true, "types": ["Data"], "value": "__UNDEFINED__"}], "pinned": false, "score": 1.8578044550916993e-05, "template": {"_type": "Component", "api_key": {"_input_type": "SecretStrInput", "advanced": false, "display_name": "Assembly API Key", "dynamic": false, "info": "Your AssemblyAI API key. You can get one from https://www.assemblyai.com/", "input_types": [], "load_from_db": true, "name": "api_key", "password": true, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "str", "value": "ASSEMBLYAI_API_KEY"}, "audio_file": {"_input_type": "FileInput", "advanced": false, "display_name": "Audio File", "dynamic": false, "fileTypes": ["3ga", "8svx", "aac", "ac3", "aif", "aiff", "alac", "amr", "ape", "au", "dss", "flac", "flv", "m4a", "m4b", "m4p", "m4r", "mp3", "mpga", "ogg", "oga", "mogg", "opus", "qcp", "tta", "voc", "wav", "wma", "wv", "webm", "mts", "m2ts", "ts", "mov", "mp2", "mp4", "m4p", "m4v", "mxf"], "file_path": "", "info": "The audio file to transcribe", "list": false, "list_add_label": "Add More", "name": "audio_file", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_metadata": true, "type": "file", "value": ""}, "audio_file_url": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Audio File URL", "dynamic": false, "info": "The URL of the audio file to transcribe (Can be used instead of a File)", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "audio_file_url", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from pathlib import Path\\n\\nimport assemblyai as aai\\nfrom loguru import logger\\n\\nfrom langflow.custom.custom_component.component import Component\\nfrom langflow.io import BoolInput, DropdownInput, FileInput, MessageTextInput, Output, SecretStrInput\\nfrom langflow.schema.data import Data\\n\\n\\nclass AssemblyAITranscriptionJobCreator(Component):\\n    display_name = \\"AssemblyAI Start Transcript\\"\\n    description = \\"Create a transcription job for an audio file using AssemblyAI with advanced options\\"\\n    documentation = \\"https://www.assemblyai.com/docs\\"\\n    icon = \\"AssemblyAI\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\"api_key\\",\\n            display_name=\\"Assembly API Key\\",\\n            info=\\"Your AssemblyAI API key. You can get one from https://www.assemblyai.com/\\",\\n            required=True,\\n        ),\\n        FileInput(\\n            name=\\"audio_file\\",\\n            display_name=\\"Audio File\\",\\n            file_types=[\\n                \\"3ga\\",\\n                \\"8svx\\",\\n                \\"aac\\",\\n                \\"ac3\\",\\n                \\"aif\\",\\n                \\"aiff\\",\\n                \\"alac\\",\\n                \\"amr\\",\\n                \\"ape\\",\\n                \\"au\\",\\n                \\"dss\\",\\n                \\"flac\\",\\n                \\"flv\\",\\n                \\"m4a\\",\\n                \\"m4b\\",\\n                \\"m4p\\",\\n                \\"m4r\\",\\n                \\"mp3\\",\\n                \\"mpga\\",\\n                \\"ogg\\",\\n                \\"oga\\",\\n                \\"mogg\\",\\n                \\"opus\\",\\n                \\"qcp\\",\\n                \\"tta\\",\\n                \\"voc\\",\\n                \\"wav\\",\\n                \\"wma\\",\\n                \\"wv\\",\\n                \\"webm\\",\\n                \\"mts\\",\\n                \\"m2ts\\",\\n                \\"ts\\",\\n                \\"mov\\",\\n                \\"mp2\\",\\n                \\"mp4\\",\\n                \\"m4p\\",\\n                \\"m4v\\",\\n                \\"mxf\\",\\n            ],\\n            info=\\"The audio file to transcribe\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"audio_file_url\\",\\n            display_name=\\"Audio File URL\\",\\n            info=\\"The URL of the audio file to transcribe (Can be used instead of a File)\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\"speech_model\\",\\n            display_name=\\"Speech Model\\",\\n            options=[\\n                \\"best\\",\\n                \\"nano\\",\\n            ],\\n            value=\\"best\\",\\n            info=\\"The speech model to use for the transcription\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"language_detection\\",\\n            display_name=\\"Automatic Language Detection\\",\\n            info=\\"Enable automatic language detection\\",\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"language_code\\",\\n            display_name=\\"Language\\",\\n            info=(\\n                \\"\\"\\"\\n            The language of the audio file. Can be set manually if automatic language detection is disabled.\\n            See https://www.assemblyai.com/docs/getting-started/supported-languages \\"\\"\\"\\n                \\"for a list of supported language codes.\\"\\n            ),\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"speaker_labels\\",\\n            display_name=\\"Enable Speaker Labels\\",\\n            info=\\"Enable speaker diarization\\",\\n        ),\\n        MessageTextInput(\\n            name=\\"speakers_expected\\",\\n            display_name=\\"Expected Number of Speakers\\",\\n            info=\\"Set the expected number of speakers (optional, enter a number)\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\"punctuate\\",\\n            display_name=\\"Punctuate\\",\\n            info=\\"Enable automatic punctuation\\",\\n            advanced=True,\\n            value=True,\\n        ),\\n        BoolInput(\\n            name=\\"format_text\\",\\n            display_name=\\"Format Text\\",\\n            info=\\"Enable text formatting\\",\\n            advanced=True,\\n            value=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\"Transcript ID\\", name=\\"transcript_id\\", method=\\"create_transcription_job\\"),\\n    ]\\n\\n    def create_transcription_job(self) -> Data:\\n        aai.settings.api_key = self.api_key\\n\\n        # Convert speakers_expected to int if it's not empty\\n        speakers_expected = None\\n        if self.speakers_expected and self.speakers_expected.strip():\\n            try:\\n                speakers_expected = int(self.speakers_expected)\\n            except ValueError:\\n                self.status = \\"Error: Expected Number of Speakers must be a valid integer\\"\\n                return Data(data={\\"error\\": \\"Error: Expected Number of Speakers must be a valid integer\\"})\\n\\n        language_code = self.language_code or None\\n\\n        config = aai.TranscriptionConfig(\\n            speech_model=self.speech_model,\\n            language_detection=self.language_detection,\\n            language_code=language_code,\\n            speaker_labels=self.speaker_labels,\\n            speakers_expected=speakers_expected,\\n            punctuate=self.punctuate,\\n            format_text=self.format_text,\\n        )\\n\\n        audio = None\\n        if self.audio_file:\\n            if self.audio_file_url:\\n                logger.warning(\\"Both an audio file an audio URL were specified. The audio URL was ignored.\\")\\n\\n            # Check if the file exists\\n            if not Path(self.audio_file).exists():\\n                self.status = \\"Error: Audio file not found\\"\\n                return Data(data={\\"error\\": \\"Error: Audio file not found\\"})\\n            audio = self.audio_file\\n        elif self.audio_file_url:\\n            audio = self.audio_file_url\\n        else:\\n            self.status = \\"Error: Either an audio file or an audio URL must be specified\\"\\n            return Data(data={\\"error\\": \\"Error: Either an audio file or an audio URL must be specified\\"})\\n\\n        try:\\n            transcript = aai.Transcriber().submit(audio, config=config)\\n        except Exception as e:  # noqa: BLE001\\n            logger.opt(exception=True).debug(\\"Error submitting transcription job\\")\\n            self.status = f\\"An error occurred: {e}\\"\\n            return Data(data={\\"error\\": f\\"An error occurred: {e}\\"})\\n\\n        if transcript.error:\\n            self.status = transcript.error\\n            return Data(data={\\"error\\": transcript.error})\\n        result = Data(data={\\"transcript_id\\": transcript.id})\\n        self.status = result\\n        return result\\n"}, "format_text": {"_input_type": "BoolInput", "advanced": true, "display_name": "Format Text", "dynamic": false, "info": "Enable text formatting", "list": false, "list_add_label": "Add More", "name": "format_text", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "language_code": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Language", "dynamic": false, "info": "\\n            The language of the audio file. Can be set manually if automatic language detection is disabled.\\n            See https://www.assemblyai.com/docs/getting-started/supported-languages for a list of supported language codes.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "language_code", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "language_detection": {"_input_type": "BoolInput", "advanced": true, "display_name": "Automatic Language Detection", "dynamic": false, "info": "Enable automatic language detection", "list": false, "list_add_label": "Add More", "name": "language_detection", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": false}, "punctuate": {"_input_type": "BoolInput", "advanced": true, "display_name": "Punctuate", "dynamic": false, "info": "Enable automatic punctuation", "list": false, "list_add_label": "Add More", "name": "punctuate", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "speaker_labels": {"_input_type": "BoolInput", "advanced": false, "display_name": "Enable Speaker Labels", "dynamic": false, "info": "Enable speaker diarization", "list": false, "list_add_label": "Add More", "name": "speaker_labels", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "speakers_expected": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Expected Number of Speakers", "dynamic": false, "info": "Set the expected number of speakers (optional, enter a number)", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "speakers_expected", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": ""}, "speech_model": {"_input_type": "DropdownInput", "advanced": true, "combobox": false, "dialog_inputs": {}, "display_name": "Speech Model", "dynamic": false, "info": "The speech model to use for the transcription", "name": "speech_model", "options": ["best", "nano"], "options_metadata": [], "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "str", "value": "best"}}, "tool_mode": false}, "selected_output": "transcript_id", "showNode": true, "type": "AssemblyAITranscriptionJobCreator"}, "dragging": false, "id": "AssemblyAITranscriptionJobCreator-Nu1dV", "measured": {"height": 343, "width": 320}, "position": {"x": 515.589850902064, "y": 232.58183434411956}, "selected": false, "type": "genericNode"}, {"data": {"id": "note-a9dFN", "node": {"description": "# Meeting Summary Generator\\n\\nThis flow automatically transcribes and summarizes meetings by converting audio recordings into concise summaries using **AssemblyAI** and **OpenAI GPT-4**. \\n\\n## Prerequisites\\n\\n- **[AssemblyAI API Key](https://www.assemblyai.com/)**\\n- **[OpenAI API Key](https://platform.openai.com/)**\\n\\n## Quickstart\\n\\n1. Upload an audio file. Most common audio file formats are [supported](https://github.com/langflow-ai/langflow/blob/main/src/backend/base/langflow/components/assemblyai/assemblyai_start_transcript.py#L27).\\n2. To run the summary generator flow, click **Playground**.\\n\\nThe flow transcribes the audio using **AssemblyAI**.\\nThe transcript is formatted for AI processing.\\nThe **GPT-4** model extracts key points and insights.\\nThe summarized meeting details are displayed in a chat-friendly format.\\n\\n\\n\\n", "display_name": "", "documentation": "", "template": {}}, "type": "note"}, "dragging": false, "height": 612, "id": "note-a9dFN", "measured": {"height": 612, "width": 548}, "position": {"x": -128.87171443390673, "y": 227.16742082405324}, "resizing": false, "selected": false, "type": "noteNode", "width": 548}, {"data": {"id": "parser-6bJ9b", "node": {"base_classes": ["Message"], "beta": false, "category": "processing", "conditional_paths": [], "custom_fields": {}, "description": "Format a DataFrame or Data object into text using a template. Enable 'Stringify' to convert input into a readable string instead.", "display_name": "Parser", "documentation": "", "edited": false, "field_order": ["mode", "pattern", "input_data", "sep"], "frozen": false, "icon": "braces", "key": "parser", "legacy": false, "metadata": {}, "minimized": false, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Parsed Text", "group_outputs": false, "method": "parse_combined_text", "name": "parsed_text", "options": null, "required_inputs": null, "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__"}], "pinned": false, "score": 2.220446049250313e-16, "template": {"_type": "Component", "clean_data": {"_input_type": "BoolInput", "advanced": true, "display_name": "Clean Data", "dynamic": false, "info": "Enable to clean the data by removing empty rows and lines in each cell of the DataFrame/ Data object.", "list": false, "list_add_label": "Add More", "name": "clean_data", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "bool", "value": true}, "code": {"advanced": true, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "import json\\nfrom typing import Any\\n\\nfrom langflow.custom import Component\\nfrom langflow.io import (\\n    BoolInput,\\n    HandleInput,\\n    MessageTextInput,\\n    MultilineInput,\\n    Output,\\n    TabInput,\\n)\\nfrom langflow.schema import Data, DataFrame\\nfrom langflow.schema.message import Message\\n\\n\\nclass ParserComponent(Component):\\n    name = \\"parser\\"\\n    display_name = \\"Parser\\"\\n    description = (\\n        \\"Format a DataFrame or Data object into text using a template. \\"\\n        \\"Enable 'Stringify' to convert input into a readable string instead.\\"\\n    )\\n    icon = \\"braces\\"\\n\\n    inputs = [\\n        TabInput(\\n            name=\\"mode\\",\\n            display_name=\\"Mode\\",\\n            options=[\\"Parser\\", \\"Stringify\\"],\\n            value=\\"Parser\\",\\n            info=\\"Convert into raw string instead of using a template.\\",\\n            real_time_refresh=True,\\n        ),\\n        MultilineInput(\\n            name=\\"pattern\\",\\n            display_name=\\"Template\\",\\n            info=(\\n                \\"Use variables within curly brackets to extract column values for DataFrames \\"\\n                \\"or key values for Data.\\"\\n                \\"For example: `Name: {Name}, Age: {Age}, Country: {Country}`\\"\\n            ),\\n            value=\\"Text: {text}\\",  # Example default\\n            dynamic=True,\\n            show=True,\\n            required=True,\\n        ),\\n        HandleInput(\\n            name=\\"input_data\\",\\n            display_name=\\"Data or DataFrame\\",\\n            input_types=[\\"DataFrame\\", \\"Data\\"],\\n            info=\\"Accepts either a DataFrame or a Data object.\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\"sep\\",\\n            display_name=\\"Separator\\",\\n            advanced=True,\\n            value=\\"\\\\n\\",\\n            info=\\"String used to separate rows/items.\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\"Parsed Text\\",\\n            name=\\"parsed_text\\",\\n            info=\\"Formatted text output.\\",\\n            method=\\"parse_combined_text\\",\\n        ),\\n    ]\\n\\n    def update_build_config(self, build_config, field_value, field_name=None):\\n        \\"\\"\\"Dynamically hide/show `template` and enforce requirement based on `stringify`.\\"\\"\\"\\n        if field_name == \\"mode\\":\\n            build_config[\\"pattern\\"][\\"show\\"] = self.mode == \\"Parser\\"\\n            build_config[\\"pattern\\"][\\"required\\"] = self.mode == \\"Parser\\"\\n            if field_value:\\n                clean_data = BoolInput(\\n                    name=\\"clean_data\\",\\n                    display_name=\\"Clean Data\\",\\n                    info=(\\n                        \\"Enable to clean the data by removing empty rows and lines \\"\\n                        \\"in each cell of the DataFrame/ Data object.\\"\\n                    ),\\n                    value=True,\\n                    advanced=True,\\n                    required=False,\\n                )\\n                build_config[\\"clean_data\\"] = clean_data.to_dict()\\n            else:\\n                build_config.pop(\\"clean_data\\", None)\\n\\n        return build_config\\n\\n    def _clean_args(self):\\n        \\"\\"\\"Prepare arguments based on input type.\\"\\"\\"\\n        input_data = self.input_data\\n\\n        match input_data:\\n            case list() if all(isinstance(item, Data) for item in input_data):\\n                msg = \\"List of Data objects is not supported.\\"\\n                raise ValueError(msg)\\n            case DataFrame():\\n                return input_data, None\\n            case Data():\\n                return None, input_data\\n            case dict() if \\"data\\" in input_data:\\n                try:\\n                    if \\"columns\\" in input_data:  # Likely a DataFrame\\n                        return DataFrame.from_dict(input_data), None\\n                    # Likely a Data object\\n                    return None, Data(**input_data)\\n                except (TypeError, ValueError, KeyError) as e:\\n                    msg = f\\"Invalid structured input provided: {e!s}\\"\\n                    raise ValueError(msg) from e\\n            case _:\\n                msg = f\\"Unsupported input type: {type(input_data)}. Expected DataFrame or Data.\\"\\n                raise ValueError(msg)\\n\\n    def parse_combined_text(self) -> Message:\\n        \\"\\"\\"Parse all rows/items into a single text or convert input to string if `stringify` is enabled.\\"\\"\\"\\n        # Early return for stringify option\\n        if self.mode == \\"Stringify\\":\\n            return self.convert_to_string()\\n\\n        df, data = self._clean_args()\\n\\n        lines = []\\n        if df is not None:\\n            for _, row in df.iterrows():\\n                formatted_text = self.pattern.format(**row.to_dict())\\n                lines.append(formatted_text)\\n        elif data is not None:\\n            formatted_text = self.pattern.format(**data.data)\\n            lines.append(formatted_text)\\n\\n        combined_text = self.sep.join(lines)\\n        self.status = combined_text\\n        return Message(text=combined_text)\\n\\n    def _safe_convert(self, data: Any) -> str:\\n        \\"\\"\\"Safely convert input data to string.\\"\\"\\"\\n        try:\\n            if isinstance(data, str):\\n                return data\\n            if isinstance(data, Message):\\n                return data.get_text()\\n            if isinstance(data, Data):\\n                return json.dumps(data.data)\\n            if isinstance(data, DataFrame):\\n                if hasattr(self, \\"clean_data\\") and self.clean_data:\\n                    # Remove empty rows\\n                    data = data.dropna(how=\\"all\\")\\n                    # Remove empty lines in each cell\\n                    data = data.replace(r\\"^\\\\s*$\\", \\"\\", regex=True)\\n                    # Replace multiple newlines with a single newline\\n                    data = data.replace(r\\"\\\\n+\\", \\"\\\\n\\", regex=True)\\n                return data.to_markdown(index=False)\\n            return str(data)\\n        except (ValueError, TypeError, AttributeError) as e:\\n            msg = f\\"Error converting data: {e!s}\\"\\n            raise ValueError(msg) from e\\n\\n    def convert_to_string(self) -> Message:\\n        \\"\\"\\"Convert input data to string with proper error handling.\\"\\"\\"\\n        result = \\"\\"\\n        if isinstance(self.input_data, list):\\n            result = \\"\\\\n\\".join([self._safe_convert(item) for item in self.input_data])\\n        else:\\n            result = self._safe_convert(self.input_data)\\n        self.log(f\\"Converted to string with length: {len(result)}\\")\\n\\n        message = Message(text=result)\\n        self.status = message\\n        return message\\n"}, "input_data": {"_input_type": "HandleInput", "advanced": false, "display_name": "Data or DataFrame", "dynamic": false, "info": "Accepts either a DataFrame or a Data object.", "input_types": ["DataFrame", "Data"], "list": false, "list_add_label": "Add More", "name": "input_data", "placeholder": "", "required": true, "show": true, "title_case": false, "trace_as_metadata": true, "type": "other", "value": ""}, "mode": {"_input_type": "TabInput", "advanced": false, "display_name": "Mode", "dynamic": false, "info": "Convert into raw string instead of using a template.", "name": "mode", "options": ["Parser", "Stringify"], "placeholder": "", "real_time_refresh": true, "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "type": "tab", "value": "Stringify"}, "pattern": {"_input_type": "MultilineInput", "advanced": false, "copy_field": false, "display_name": "Template", "dynamic": true, "info": "Use variables within curly brackets to extract column values for DataFrames or key values for Data.For example: `Name: {Name}, Age: {Age}, Country: {Country}`", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "pattern", "placeholder": "", "required": false, "show": false, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "Text: {text}"}, "sep": {"_input_type": "MessageTextInput", "advanced": true, "display_name": "Separator", "dynamic": false, "info": "String used to separate rows/items.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sep", "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "type": "str", "value": "\\n"}}, "tool_mode": false}, "selected_output": "parsed_text", "showNode": true, "type": "parser"}, "dragging": false, "id": "parser-6bJ9b", "measured": {"height": 278, "width": 320}, "position": {"x": 1315.3283640699676, "y": 413.6106535940148}, "selected": false, "type": "genericNode"}, {"data": {"id": "LanguageModelComponent-cPCaH", "node": {"base_classes": ["LanguageModel", "Message"], "beta": false, "category": "models", "conditional_paths": [], "custom_fields": {}, "description": "Runs a language model given a specified provider. ", "display_name": "Language Model", "documentation": "", "edited": false, "field_order": ["provider", "model_name", "api_key", "input_value", "system_message", "stream", "temperature"], "frozen": false, "icon": "brain-circuit", "key": "LanguageModelComponent", "legacy": false, "metadata": {"keywords": [